import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-e-001","clusterId":"E","werkstueckRef":"E.1.1","stufe":1,"question":"Du liest eine Schlagzeile und merkst, dass dich eine Meldung sofort wütend macht. Du willst gleich einen empörten Kommentar schreiben. Welche Reaktion ist am klügsten?","options":["Der starken Reaktion vertrauen, weil ein spontanes Gefühl meist auch ein verlässliches Urteil ist und gründliches Nachdenken es nur verwässert.","Das Gefühl als Warnsignal nehmen, erst den Artikel mit Zahlen und Quellen prüfen und dann entscheiden, ob und was du kommentierst.","Schnell kommentieren, damit die Empörung nicht verfliegt, und erst später nachlesen, falls jemand widerspricht oder Fragen stellt.","Die Meldung für wahr halten, weil sie so eindeutig klingt und niemand eine so einfache Schlagzeile einfach erfinden würde."],"correctIndex":1,"explanation":"Eine starke, sofortige Emotion bei einer einfach gestrickten Meldung ist ein typisches Zeichen dafür, dass das schnelle, automatische Denken die Führung hat. Das schnelle Denken ist für Routine nützlich, aber bei neuen oder wichtigen Urteilen anfällig für Fehler. Das langsame, anstrengende Prüfen muss man bewusst einschalten, von allein springt es nicht an. Wer nur die Überschrift kennt, weiß weder, wie hoch die Summe wirklich ist, noch, was sie umfasst oder womit sie zu vergleichen ist. Das Gefühl ist also ein Anlass, innezuhalten und zu prüfen, kein Beweis. Zeitdruck und starke Emotionen nutzen Betrüger, um das langsame Prüfen zu verhindern; beides sind Warnzeichen dafür, dass das schnelle Denken die Kontrolle übernommen hat. Deshalb hilft es, erst die Fakten zu lesen und danach zu urteilen. Ein Gefühl der Stimmigkeit ist kein Wahrheitsbeleg.","coreRule":"⚡ Starkes Gefühl plus Eile ist ein Signal zum Innehalten: Erst bewusst prüfen, dann urteilen.","quote":"Du spürst eine starke, sofortige emotionale Reaktion auf eine Information.","quoteLabel":"Merksatz:","beleg":"Werkstück E.1.1 (Kernidee; Kontext & Tiefe); Fn. gl-e-zweisystem (Kahneman 2012, Teil I, Kap. 1: „fiktive Figuren“)","status":"entwurf","scenario":"Die Schlagzeile lautet: „Skandal: Stadt verschwendet Millionen für nutzlose Radwege!“ Du hast nur die Überschrift gelesen, spürst aber sofort ein klares Urteil.","kurz":"Die Wut ist ein Anlass innezuhalten, kein Beweis. Aus einer Überschrift allein lässt sich weder Summe noch Umfang beurteilen; erst Zahlen und Quellen lesen, dann urteilen.","prueffrage":"Welche Angaben zu Summe, Umfang und Vergleich findest du in der Überschrift, und welche fehlen?","rueckmeldung":[{"option":0,"text":"Spontane Urteile sind bei Routine oft brauchbar, bei einer neuen, wichtigen Frage aber fehleranfällig. Prüfen verwässert ein Urteil nicht, es macht es belastbar. Über die Überschrift hinaus weißt du noch nichts."},{"option":2,"text":"Die Empörung wirkt dringlich, und schnell zu reagieren fühlt sich konsequent an. Ein Kommentar zu einer bloßen Überschrift steht dann aber schon da, und wer später nachliest, verteidigt leicht nur noch das Geschriebene. Erst lesen, dann urteilen."},{"option":3,"text":"Eine klare, einfache Schlagzeile wirkt glaubwürdig, weil sie sich stimmig anfühlt. Dieses Gefühl ist aber kein Beleg: Auch eine nicht erfundene Meldung kann zugespitzt sein, und Summe, Umfang und Vergleichswert bleiben unbekannt."}],"familie":"innehalten-bei-druck","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality: A Perspective on Intuitive Judgment and Choice. Nobelpreis-Vortrag, Nobel Foundation","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"PDF-S. 3, 5–6","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kahneman, D. (2012): Schnelles Denken, langsames Denken. München: Siedler, Teil I","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"f4a996099e31826b"}},{"id":"qx-e-002","clusterId":"E","werkstueckRef":"E.1.1","stufe":2,"question":"Du bemerkst, dass du fast automatisch klicken würdest. Was ist in dieser Lage der klügste nächste Schritt, und warum?","scenario":"Du bekommst eine Nachricht: „Ihr Konto wird in einer Stunde gesperrt – jetzt sofort bestätigen!“ Dein Puls steigt, und du willst nur noch schnell klicken.","options":["Kurz innehalten und die Nachricht über einen eigenen, bekannten Weg prüfen, etwa die offizielle App deiner Bank, weil Druck das gründliche Prüfen verhindern soll.","Sofort klicken und die Angaben prüfen, sobald sich die Seite öffnet, weil schnelles Handeln bei echten Warnungen die sicherste Reaktion ist.","Dem ersten Gefühl vertrauen und handeln, weil ein starkes Alarmgefühl fast immer anzeigt, dass tatsächlich eine echte Gefahr besteht.","Die Nachricht ohne weitere Prüfung ignorieren, weil schon der Zeitdruck beweist, dass es sich auf jeden Fall um Betrug handeln muss."],"correctIndex":0,"explanation":"Zeitdruck und starke Gefühle wie Angst oder Gier sind ein bewährtes Mittel von Betrügern: Wer unter Druck steht und aufgeregt ist, greift eher auf schnelle, automatische Reaktionen zurück, statt die Lage in Ruhe zu prüfen. Die wirksamste Gegenmaßnahme ist, die Situation zu verlangsamen und die Behauptung unabhängig zu überprüfen, also nicht über den Link in der Nachricht, sondern über einen Kanal, den du selbst kennst. Ein starkes Alarmgefühl ist kein Beweis für eine echte Gefahr, denn es lässt sich gezielt erzeugen. Aber auch der Zeitdruck allein beweist nicht, dass es Betrug ist: Er ist ein Warnsignal, das eine Prüfung auslösen sollte, kein Urteil, das sie ersetzt. Erst prüfen, dann handeln, vermeidet beide Fehler.","coreRule":"⚡ Je schneller und emotionaler man dich zu einer Entscheidung drängt, desto dringender brauchst du eine Denkpause und eine unabhängige Prüfung.","beleg":"Werkstück E.1.1 (Anwendung & Relevanz: Bei Betrugsmaschen; Red Flags)","status":"entwurf","kurz":"Wer unter Druck steht, greift eher zu schnellen, automatischen Reaktionen; genau darauf setzen Betrüger. Wirksam ist, zu verlangsamen und die Behauptung über einen selbst gewählten Kanal zu prüfen, nicht über den Link in der Nachricht.","prueffrage":"Was weißt du über den Absender sicher, abgesehen von dem, was die Nachricht selbst über sich behauptet?","rueckmeldung":[{"option":1,"text":"Schnelles Handeln klingt bei einer Warnung vernünftig. Doch der Klick führt dich auf den Weg, den die Nachricht vorgibt, und eine Prüfung dort ist keine unabhängige. Auch echte Meldungen lassen sich ohne Eile über einen eigenen Kanal prüfen."},{"option":2,"text":"Ein starkes Alarmgefühl fühlt sich wie ein verlässlicher Hinweis an. Es beweist aber keine echte Gefahr, denn Angst lässt sich gezielt erzeugen, etwa mit einer knappen Frist. Das Gefühl ist ein Anlass zum Prüfen, kein Beleg."},{"option":3,"text":"Der Zeitdruck ist tatsächlich ein Warnsignal. Als Beweis taugt er aber nicht: Auch echte Mitteilungen können dringlich klingen. Ignorieren ohne Prüfung ersetzt die Prüfung durch ein vorschnelles Urteil, nur in die andere Richtung."}],"familie":"innehalten-bei-druck","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Federal Trade Commission (FTC): How To Avoid a Scam","oeffentlich":true,"url":"https://consumer.ftc.gov/articles/how-avoid-scam","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality: A Perspective on Intuitive Judgment and Choice. Nobelpreis-Vortrag, Nobel Foundation","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"PDF-S. 5–6","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"1e9c97d3a4512cda"}},{"id":"qx-e-003","clusterId":"E","werkstueckRef":"E.1.1","stufe":3,"question":"In welcher dieser Situationen ist es am riskantesten, dich auf dein schnelles Bauchgefühl zu verlassen?","options":["Du entscheidest über deine Ersparnisse allein nach dem Gefühl, das ein einfach klingendes Anlageversprechen bei dir auslöst.","Du läufst den gewohnten Weg zur Arbeit, ohne an jeder Kreuzung neu darüber nachzudenken, wohin du abbiegen musst.","Du erkennst im Gedränge eines Bahnhofs auf den ersten Blick das Gesicht einer guten Freundin, ohne dich erst zu besinnen.","Du greifst beim Frühstück zum gewohnten Müsli, weil dir die Auswahl im Regal keine lange Überlegung und keinen Vergleich wert ist."],"correctIndex":0,"explanation":"Schnelles, intuitives Denken ist bei Routine und Vertrautem sehr effizient: Der gewohnte Weg, ein bekanntes Gesicht und die tägliche Müslisorte sind Aufgaben, bei denen ein Irrtum wenig kostet und die Intuition meist zuverlässig arbeitet. Anders bei Geld, Gesundheit oder politischen Weichenstellungen: Hier geht es um viel, die Lage ist komplex oder neu, und gerade ein „einfach klingendes“ Versprechen ist ein typischer Köder für das Bauchgefühl. Wo viel auf dem Spiel steht oder die Situation ungewohnt ist, lohnt sich das langsame, bewusste Nachprüfen. Der Aufwand ist dort gut investiert, weil ein Fehlurteil teuer wird.","coreRule":"⚡ Bei Routine mit geringem Einsatz darf das Bauchgefühl entscheiden; bei hohen Einsätzen oder Neuem lohnt sich das langsame, bewusste Prüfen.","beleg":"Werkstück E.1.1 (Der Kipppunkt; Kontext & Tiefe: Zuständigkeit von System 1)","status":"entwurf","scenario":"","kurz":"Riskant wird das Bauchgefühl dort, wo viel auf dem Spiel steht und die Lage unvertraut ist, etwa bei Geld. Ein „einfach klingendes“ Versprechen ködert die Intuition, und ein Fehlurteil wird teuer; bei Routine kostet ein Irrtum wenig.","prueffrage":"Wie oft hast du jede dieser Entscheidungen schon getroffen, und wie schnell würdest du jeweils merken, dass du falsch lagst?","rueckmeldung":[{"option":1,"text":"Gewohnte Wege wirken schnell fehleranfällig, weil man dabei kaum mitdenkt. Gerade bei Routine arbeitet die Intuition aber meist zuverlässig, und ein Irrtum kostet wenig: Man bemerkt ihn schnell und korrigiert ihn."},{"option":2,"text":"Im Gedränge könnte man sich leicht vertun. Ein vertrautes Gesicht zu erkennen, gelingt der schnellen Wahrnehmung aber meist gut, und ein Irrtum kostet wenig: Schlimmstenfalls winkt man einer Fremden zu."},{"option":3,"text":"Ohne Vergleich zu wählen, wirkt unüberlegt. Beim gewohnten Müsli steht aber kaum etwas auf dem Spiel, ein Fehlgriff kostet fast nichts. Ein langes Abwägen wäre hier schlicht verschwendeter Aufwand."}],"familie":"faustregel-oder-rechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality: A Perspective on Intuitive Judgment and Choice. Nobelpreis-Vortrag, Nobel Foundation","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"PDF-S. 3, 5","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kahneman, D. (2012): Schnelles Denken, langsames Denken. München: Siedler, Teil I","oeffentlich":false},{"typ":"literatur","kurz":"Kahneman, D.; Klein, G. (2009): Conditions for intuitive expertise: A failure to disagree. American Psychologist","oeffentlich":false,"doi":"10.1037/a0016755"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"5d5ad012bfd41bfe"}},{"id":"qx-e-004","clusterId":"E","werkstueckRef":"E.1.1","stufe":4,"question":"Wie gehst du mit der Zahl um?","options":["Du behandelst sie als ungeprüft, weil ohne nachprüfbare Studie auch häufiges Wiederholen sie nicht zum Befund macht.","Du übernimmst sie vorläufig, weil die ähnlichen Werte um 95 % zeigen, dass mehrere unabhängige Quellen dasselbe gemessen haben.","Du hältst sie für plausibel, weil intuitives Denken schnell und mühelos abläuft und deshalb im Alltag sehr häufig zum Einsatz kommt.","Du akzeptierst sie, weil ein bekannter Psychologe als Gewährsmann genannt wird, und prüfst nur noch, ob er richtig zitiert wurde."],"correctIndex":0,"explanation":"Eine glatte Prozentzahl ohne nachvollziehbare Studie dahinter ist zunächst nur eine Behauptung. Dass sie in vielen Marketingtexten steht, ist kein Beleg: Die Zahl lässt sich auf keine belastbare Studie zurückführen und kursiert vor allem im Marketing. Die leicht abweichenden Werte (90, 95, 98 %) sind deshalb keine Bestätigung durch mehrere Messungen, sondern eher ein Zeichen, dass eine Zahl weitergereicht und dabei abgewandelt wird. Auch ein berühmter Name ersetzt keine Quelle, und dass intuitives Denken im Alltag sehr häufig ist, rechtfertigt noch keine feste Prozentzahl. Die richtige Reaktion ist deshalb: nach der Originalstudie fragen und die Zahl bis dahin als ungeprüft behandeln.","coreRule":"⚡ Eine glatte Prozentzahl ohne Studie dahinter ist eine Behauptung, kein Befund.","beleg":"Werkstück E.1.1; Fn. gl-e-95prozent; Fn. gl-e-hirnenergie (Raichle & Gusnard 2002, S. 10237–10238)","status":"entwurf","scenario":"Eine Werbeagentur wirbt mit der Aussage: „Unser intuitives Denken steuert 95 % unserer Entscheidungen.“ Die Zahl steht in einer Präsentation, mit der sie ihren Kunden „neurowissenschaftlich fundiertes Marketing“ verkauft. Eine Studie nennt die Agentur nicht, sie verweist nur auf einen bekannten Psychologen. Auf Nachfrage heißt es, die Zahl stehe „in jedem Marketingbuch“, und je nach Quelle seien es 90, 95 oder 98 %.","quote":"","quoteLabel":"","kurz":"Eine glatte Prozentzahl ohne nachvollziehbare Studie ist zunächst nur eine Behauptung; häufiges Wiederholen, ähnliche Werte oder ein berühmter Name machen sie nicht zum Befund. Frag nach der Originalstudie und behandle die Zahl bis dahin als ungeprüft.","prueffrage":"Lässt sich verfolgen, woher die 95 % ursprünglich stammen, und warum nennen andere Bücher 90 oder 98 %?","rueckmeldung":[{"option":1,"text":"Mehrere Quellen wären ein gutes Zeichen, wenn sie unabhängig voneinander gemessen hätten. Hier geht aber keiner der Werte auf eine belastbare Studie zurück; die Abweichungen zeigen eher, dass die Zahl kursiert und dabei leicht abgewandelt wird."},{"option":2,"text":"Dass intuitives Denken im Alltag sehr oft zum Einsatz kommt, mag stimmen. Daraus ergibt sich aber keine feste Prozentzahl: „sehr häufig“ ist etwas anderes als „95 %“, und für genau diese Zahl fehlt die Messung."},{"option":3,"text":"Ein berühmter Name macht eine Zahl nicht belegt. Auch ein korrektes Zitat zeigt nur, dass jemand die Zahl gesagt hat, nicht, dass sie gemessen wurde, und eine prüfbare Studie nennt die Agentur nicht."}],"familie":"zahl-zur-quelle","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Harvey, C. (2025): 3 dangerous behavioural science myths – and what to do about them. Research World (ESOMAR)","oeffentlich":true,"url":"https://researchworld.com/articles/3-dangerous-behavioural-science-myths-and-what-to-do-about-them","abruf":"2026-10-12"},{"typ":"url","kurz":"Fletcher, W. (2003): Sigmund fells trendy straw men (Rezension zu Zaltman, How Customers Think). Times Higher Education","oeffentlich":true,"url":"https://www.timeshighereducation.com/books/sigmund-fells-trendy-straw-men/177940.article","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Zaltman, G. (2003): How Customers Think. Boston: Harvard Business School Press","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"29cc36c63b2db3d7"}},{"id":"qx-e-005","clusterId":"E","werkstueckRef":"E.1.2","stufe":1,"question":"Welche Erklärung beschreibt den Kern ihres Verhaltens am sparsamsten?","options":["Sie hat die Information nicht richtig verstanden und kann zwei widersprüchliche Testergebnisse nicht gleichzeitig im Kopf behalten.","Sie ist grundsätzlich unehrlich und nimmt Kritik nie ernst, auch nicht bei Kleinigkeiten oder in anderen Lebensbereichen.","Der Zweifel an der eigenen Entscheidung ist unangenehm, und sie rückt ihre Überzeugung zurecht, statt die Entscheidung zu prüfen.","Sie hat neutral abgewogen und die Tests nach ihrer Qualität gewichtet, ohne dass ihr eigener Wunsch dabei eine Rolle spielt."],"correctIndex":2,"explanation":"Der Widerspruch zwischen „Ich habe klug entschieden“ und „Es gibt Hinweise, dass die Wahl schlecht war“ erzeugt eine unangenehme Spannung (kognitive Dissonanz). Sie lässt sich auf mehreren Wegen verringern: das Verhalten ändern (Auto zurückgeben), die Überzeugung ändern, neue stützende Gründe suchen oder den Widerspruch herunterspielen; oft ist es am einfachsten, bestätigende Informationen zu suchen, statt die Entscheidung zu prüfen. Dazu passt eine klassische Studie von Ehrlich und Kollegen (1957) aus Festingers Umfeld: Neuwagenkäufer lasen häufiger Anzeigen für das eigene Modell (65 %) als für Modelle, die bei ihrer Wahl keine Rolle gespielt hatten (34 %). Dass Mara die Informationen nicht versteht, passt nicht, denn gerade weil sie den Widerspruch bemerkt, entsteht die Spannung. Eine pauschale Unehrlichkeit müsste man erst belegen, und eine neutrale Abwägung würde die Kritik inhaltlich prüfen, statt sie mit einer Unterstellung abzutun.","coreRule":"⚡ Wenn Kritik an einer eigenen Entscheidung vor allem unangenehm ist, lohnt die Frage: Ist sie falsch, oder löse ich gerade Spannung auf, indem ich meine Geschichte zurechtrücke?","beleg":"Werkstück E.1.2 (Kernidee; Anwendung: Nach einer wichtigen Entscheidung; Anti-Denkmuster); Fn. gl-e-dissonanz (Festinger 1957, S. 3 und 13), gl-e-autokauf (Festinger 1957, S. 50–53)","status":"entwurf","scenario":"Mara hat sich für ein teures Auto entschieden. Seitdem kommen ihr Zweifel, ob die Wahl klug war: Ein Freund hat auf Mängel hingewiesen, ein Test bewertet ein anderes Modell besser. Mara liest nun nur noch Tests, die ihr Modell loben, und sagt: „Kritiker sind doch nur neidisch. Mein Auto ist die richtige Wahl, das sehe ich jeden Tag.“","kurz":"Mara hat sich festgelegt, und jeder Hinweis auf eine schlechte Wahl erzeugt unangenehme Spannung. Statt die Entscheidung zu prüfen, passt sie lieber ihre Überzeugung an und liest nur Bestätigendes. Das ist oft der einfachste Weg, die Spannung loszuwerden.","prueffrage":"Prüft Mara den Inhalt der Kritik, oder erklärt sie nur, warum die Kritiker sie äußern?","rueckmeldung":[{"option":0,"text":"Ein Verständnisproblem wäre eine einfache Erklärung, passt aber nicht: Mara bemerkt den Widerspruch ja deutlich, sonst würde er sie nicht beunruhigen. Sie versteht die Hinweise, wehrt sie aber ab."},{"option":1,"text":"Dass Mara Kritik wegwischt, wirkt wie Unehrlichkeit. Gezeigt wird aber nur ein Verhalten in einer einzigen Lage. Ein allgemeiner Charakterzug über alle Lebensbereiche und Kleinigkeiten wäre eine Unterstellung, die erst belegt werden müsste."},{"option":3,"text":"Abwägen würde bedeuten, auch die kritischen Berichte inhaltlich zu prüfen. Mara liest nur Lobendes und tut Kritik mit der Unterstellung „Neid“ ab. Ihr Wunsch, richtig entschieden zu haben, steuert hier offensichtlich mit."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Tueanrat, Y.; Alamanos, E. (2026): Cognitive Dissonance Theory: A review. In: Papagiannidis, S. (Hg.): TheoryHub Book, Newcastle University","oeffentlich":true,"url":"https://open.ncl.ac.uk/theories/7/pdf/cognitive-dissonance-theory","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Festinger, L. (1957): A Theory of Cognitive Dissonance. Stanford: Stanford University Press","oeffentlich":false,"doi":"10.1515/9781503620766"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"750cc631ba994798"}},{"id":"qx-e-006","clusterId":"E","werkstueckRef":"E.1.2","stufe":2,"question":"Was tut Jonas mit seiner Antwort, und was ändert sich dadurch an seiner Lage?","scenario":"Dein Freund Jonas hat vor drei Wochen für 280 Euro eine Designerjacke gekauft und sie seitdem nie getragen. Als du ihn darauf ansprichst, sagt er: „Ach, das war doch nicht so viel Geld, das merke ich gar nicht.“","options":["Er spielt den Widerspruch herunter, damit lässt das unangenehme Gefühl nach, die ungenutzte Jacke bleibt aber, wie sie ist.","Er wägt Kosten und Nutzen nüchtern ab, dabei zeigt sich, dass der niedrige Preis den Kauf ohnehin gerechtfertigt hat.","Er nennt einen neuen Grund für den Kauf, damit erscheint die Jacke im Nachhinein als kluge Anschaffung für ihn.","Er korrigiert sein Verhalten, weil er sieht, dass er das Teil nicht braucht, damit endet der innere Konflikt für ihn."],"correctIndex":0,"explanation":"Jonas spielt die Wichtigkeit des Widerspruchs herunter. Zwischen „Ich habe viel Geld ausgegeben“ und „Ich brauche das Teil gar nicht“ besteht eine Spannung, die sich unangenehm anfühlt. Wenn das Geld plötzlich „nicht so viel“ war, schrumpft der Widerspruch, und das Gefühl lässt nach. An der Lage ändert sich dadurch nichts: Die Jacke hängt weiter ungenutzt im Schrank, und aus dem Kauf wird nichts gelernt. Bei kleinen Enttäuschungen ist solche Dissonanzreduktion meist harmlos. Gefährlich wird sie erst, wenn sie uns daran hindert, aus gravierenden Fehlern zu lernen. Zur Unterscheidung der Wege, übertragen auf die Jacke: Wer sie zurückgibt, ändert sein Verhalten. Wer sagt „Das ist ein Klassiker, der kommt wieder“, ändert seine Überzeugung. Wer sagt „Aber es war ein Schnäppchen“, fügt einen neuen Grund hinzu. Wer den Widerspruch für unwichtig erklärt, spielt das Problem herunter.","coreRule":"⚡ Dissonanz lässt sich auf vier Wegen mindern: Verhalten ändern, Überzeugung ändern, neue Gründe hinzufügen oder die Wichtigkeit des Widerspruchs herunterspielen.","beleg":"Werkstück E.1.2 (Kontext & Tiefe, vier Strategien; Werkbank-Frage); Fn. gl-e-dissonanz-wege (Festinger 1957, S. 6 und 18–22)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Jonas macht den Widerspruch klein: Wenn 280 Euro „nicht viel“ sind, drückt der Kauf weniger, und das unangenehme Gefühl lässt nach. Die Jacke hängt aber weiter ungenutzt im Schrank, die Lage bleibt dieselbe, gelernt wird nichts.","prueffrage":"Worauf bezieht sich Jonas' Satz genau, und hat er die Jacke seitdem getragen oder zurückgegeben?","rueckmeldung":[{"option":1,"text":"Eine Abwägung würde etwas gegeneinander halten, doch Jonas sagt nur, der Betrag sei klein. Dass die Jacke dadurch gerechtfertigt wäre, folgt daraus nicht, denn ungenutzt bringt sie auch zu einem kleinen Preis keinen Nutzen."},{"option":2,"text":"Ein neuer Grund für den Kauf wäre etwa „Es war ein Schnäppchen“, und der Ausgang fühlt sich ähnlich an. Jonas nennt aber keinen Grund für den Kauf, sondern macht den Betrag selbst unwichtig, und das ist ein anderer Weg."},{"option":3,"text":"Der Konflikt lässt bei Jonas tatsächlich nach, nur nicht durch eine Korrektur. Er gibt die Jacke nicht zurück und trägt sie nicht, das Gefühl beruhigt sich allein dadurch, dass er den Betrag kleinredet."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Tueanrat, Y.; Alamanos, E. (2026): Cognitive Dissonance Theory: A review. In: Papagiannidis, S. (Hg.): TheoryHub Book, Newcastle University","oeffentlich":true,"url":"https://open.ncl.ac.uk/theories/7/pdf/cognitive-dissonance-theory","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Festinger, L. (1957): A Theory of Cognitive Dissonance. Stanford: Stanford University Press","oeffentlich":false,"doi":"10.1515/9781503620766"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"18213a835813cd6d"}},{"id":"qx-e-007","clusterId":"E","werkstueckRef":"E.1.2","stufe":3,"question":"Was erklärt den Unterschied zwischen beiden Beobachtungen am sparsamsten?","options":["Die Gruppe im zweiten Versuch war vermutlich von vornherein weniger interessant als die Gruppe im ersten, sodass der Aufwand sie nicht mehr aufwerten konnte.","Die Stromstöße dauerten im zweiten Versuch wahrscheinlich zu lange, sodass die Erschöpfung die Aufwertung in Abwertung umschlagen ließ.","Im zweiten Versuch wussten die Teilnehmenden vermutlich, dass Aufwand und Wert nichts miteinander zu tun haben, und entzogen sich so dem Effekt.","Im ersten Fall war der Aufwand der Preis für die Aufnahme, im zweiten galten die Stöße nur als Teil des Versuchs."],"correctIndex":3,"explanation":"Mühe wertet ein Ziel nur auf, wenn sie als Preis für dieses Ziel erlebt wird. Wer sich für eine Aufnahme gequält hat, muss den Aufwand vor sich selbst rechtfertigen und findet die Gruppe deshalb besser, als sie ist. Gilt die Strapaze dagegen als bloßer Teil eines Versuchs, entfällt der Anlass zur Aufwertung; die Gruppe wurde nach starken Stößen tendenziell sogar schlechter bewertet als nach schwachen. Die drei anderen Erklärungen führen zusätzliche, nicht belegte Annahmen ein (eine von vornherein schlechtere Gruppe, eine kritische Dauer, ein Wissen der Teilnehmenden), obwohl der Unterschied in der Rahmung des Aufwands schon ausreicht. Im Sinn der Dissonanztheorie ist das die sparsamste Erklärung. Wichtig bleibt eine Einschränkung: Eine konkurrierende Deutung sieht im ersten Effekt nur einen Kontrast zum unangenehmen Vorlauf, die Rechtfertigungs-Erklärung ist also nicht die einzig mögliche.","coreRule":"⚡ Aufwand wertet nur auf, was als Ziel des Aufwands erlebt wird – sonst fehlt der Anlass zur Rechtfertigung.","beleg":"Werkstück E.1.2 (Anwendung & Relevanz); Fn. gl-e-aufwand (Harmon-Jones & Mills 2019, S. 6–7; Harmon-Jones u. a. 2024, S. 1–2 und 12); Aronson, E. (1969): The theory of cognitive dissonance: A current perspective. Advances in Experimental Social Psychology 4, 1–34, hier S. 9–11 (zu Gerard & Mathewson 1966, J. Exp. Soc. Psychol. 2, 278–287): „No Initiation“-Bedingung (starke Stöße ohne Aufnahmebezug) bewertete die aufgezeichnete Diskussion tendenziell schlechter als die Bedingung mit schwachen Stößen; Bedingung „Initiation“ (starke Stöße für die Aufnahme) bewertete sie besser. Von Sturm als Scan geliefert, am 12.10.2026 per OCR gelesen. Konkurrierende Deutung (Chapanis & Chapanis 1964: Erfolgsgefühl) dort ebenfalls dargestellt.","status":"entwurf","scenario":"Zwei Beobachtungen zur Frage, ob Mühe das Ergebnis aufwertet: (1) Menschen, die für die Aufnahme in eine Gruppe eine peinliche Prüfung ablegen mussten, fanden die Gruppe danach anziehender als Menschen mit einer kaum peinlichen Aufnahme, obwohl sich die Gruppe als ziemlich langweilig erwies. (2) In einem anderen Versuch bekamen Teilnehmende schmerzhafte oder schwache Stromstöße, die keine Bedingung für die Aufnahme in die Gruppe waren. Sie bewerteten die Gruppe danach nach den starken Stößen tendenziell schlechter als nach den schwachen.","kurz":"Mühe wertet ein Ziel nur auf, wenn sie als Preis dafür erlebt wird und gerechtfertigt werden muss. Gelten die Stöße als bloßer Teil des Versuchs, entfällt dieser Anlass. Zusätzliche Annahmen über Gruppe, Dauer oder Wissen braucht es dafür nicht.","prueffrage":"Worin unterscheiden sich die beiden Fälle außer in der Art der Strapaze?","rueckmeldung":[{"option":0,"text":"Eine von vornherein langweiligere Gruppe wäre denkbar, beschrieben ist sie aber nirgends. Zudem wurde im zweiten Versuch dieselbe Gruppe nach starken und schwachen Stößen bewertet; ihr Reiz erklärt also nicht, warum starke Stöße sie eher abwerteten."},{"option":1,"text":"Zu lange Stöße und Erschöpfung klingen plausibel, beschrieben ist davon aber nichts. Die Annahme kommt ohne Beleg hinzu und erklärt nicht, warum die ebenfalls unangenehme Prüfung im ersten Fall aufwertet."},{"option":2,"text":"Von einem solchen Wissen der Teilnehmenden ist nirgends die Rede, die Annahme ist also unbelegt. Nötig ist sie auch nicht: Es genügt, dass die Stöße nicht als Preis für die Aufnahme erlebt wurden."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Harmon-Jones, E.; Matis, S.; Angus, D. J.; Harmon-Jones, C. (2024): Does Effort Increase or Decrease Reward Valuation? Considerations from Cognitive Dissonance Theory. Psychophysiology 61(6), e14536","oeffentlich":true,"doi":"10.1111/psyp.14536","url":"https://osf.io/r7c82","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Harmon-Jones, E.; Mills, J. (2019): An Introduction to Cognitive Dissonance Theory and an Overview of Current Perspectives on the Theory. In: Harmon-Jones, E. (Hg.): Cognitive Dissonance. 2. Aufl. Washington, DC: APA, S. 3–24","oeffentlich":false,"doi":"10.1037/0000135-001"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"26b371b03947bc09"}},{"id":"qx-e-008","clusterId":"E","werkstueckRef":"E.1.2","stufe":4,"question":"Was ist an diesem Schluss fehlerhaft?","options":["Er unterstellt, dass eine eindeutige Widerlegung den Glauben immer beendet. Wer viel investiert hat und von anderen gestützt wird, kann sie umdeuten und den Glauben verstärken.","Er verwechselt Ursache und Wirkung. Das eifrige Werben hat die Flut verhindert, nicht umgekehrt, und die Gruppe darf deshalb an ihrer Vorhersage festhalten.","Er schließt von wenigen Mitgliedern auf alle. Jede Gruppe hält nach einer gescheiterten Vorhersage zusammen und wirbt dann zwangsläufig stärker als zuvor.","Er übersieht, dass die Mitglieder gar keinen Widerspruch erleben. Ein Mensch empfindet eine eindeutige Widerlegung nie als unangenehm, sondern nimmt sie gelassen hin."],"correctIndex":0,"explanation":"Der Schluss behandelt „Widerlegung“ wie einen Schalter, der Glauben automatisch ausschaltet. Wer viel investiert hat (Arbeit, Besitz), erlebt die Widerlegung als schwer erträglichen Widerspruch; leichter, als den eigenen Irrtum einzugestehen, ist es oft, die Widerlegung umzudeuten und am Glauben festzuhalten, besonders mit Rückhalt durch andere Gläubige. Festinger, Riecken und Schachter beschrieben 1956 eine Gruppe, die für den 21. Dezember eine Flut vorhergesagt hatte: Wer nach dem Ausbleiben mit anderen zusammen war, warb eifriger als zuvor, wer allein war, gab den Glauben meist auf. Spätere Studien bestätigen vor allem das Festhalten durch Umdeuten; das verstärkte Werben gilt als schwächster Punkt der Untersuchung, und dass Gegenbeweise einen Glauben sogar verstärken, ist eher die Ausnahme. Der Fehler des Zuschauers liegt darin, das für ausgeschlossen zu halten und aus dem Festhalten auf mangelnde Überzeugung zu schließen.","coreRule":"⚡ Wer viel investiert hat und Rückhalt in einer Gruppe findet, kann eine Widerlegung umdeuten, statt sie anzunehmen. Daraus, dass jemand an einem widerlegten Glauben festhält, folgt nicht, dass er nicht wirklich überzeugt ist.","beleg":"Werkstück E.1.2 (Anwendung & Relevanz: Bei Kulten & Verschwörungsmythen); Fn. gl-e-prophezeiung (Festinger, Riecken, Schachter 1956, S. 3–4, 227–229); Fn. gl-e-luecke (Lewandowsky u. a. 2020, PDF-S. 9)","status":"entwurf","scenario":"Eine kleine Gruppe hat öffentlich vorhergesagt, an einem bestimmten Tag werde eine Flut die Welt verwüsten. Mehrere Mitglieder haben dafür ihre Arbeit aufgegeben und ihren Besitz verschenkt. Der Tag vergeht, nichts geschieht. Wenig später wirbt ein Teil der Mitglieder eifriger um neue Anhänger als zuvor. Ein Zuschauer folgert: „Wer so reagiert, glaubt gar nicht richtig. Wer wirklich überzeugt wäre, würde angesichts der Widerlegung sofort aufgeben.“","quote":"","quoteLabel":"","kurz":"Eine Widerlegung beendet den Glauben nicht automatisch. Wer viel investiert hat und von anderen gestützt wird, kann sie umdeuten und stärker glauben. Der Zuschauer hält das für ausgeschlossen und liest Festhalten als mangelnde Überzeugung.","prueffrage":"Folgt aus dem eifrigeren Werben wirklich, dass die Mitglieder zweifeln, oder lässt sich ihr Verhalten auch anders lesen?","rueckmeldung":[{"option":1,"text":"Das verstärkte Werben setzte erst ein, nachdem die Flut ausgeblieben war, und kann sie nicht verhindert haben. Der Fehler des Zuschauers liegt im Schluss auf mangelnde Überzeugung, nicht in einer verdrehten Ursache."},{"option":2,"text":"Nur ein Teil der Mitglieder wirbt eifriger, und verstärktes Werben nach einer Widerlegung ist kein Gesetz, also auch nicht zwangsläufig. Der Fehler liegt woanders: Der Zuschauer hält dieses Verhalten bei echter Überzeugung für ausgeschlossen."},{"option":3,"text":"Gelassenheit wäre denkbar, wenn jemand wenig auf die Vorhersage gesetzt hätte. Wer aber Arbeit und Besitz aufgegeben hat, erlebt die Widerlegung meist als quälenden Widerspruch, und gerade dieser Druck macht das Umdeuten verständlich."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J.; Ecker, U. K. H. u. a. (2020): The Debunking Handbook 2020","oeffentlich":true,"doi":"10.17910/b7.1182","url":"https://skepticalscience.com/docs/DebunkingHandbook2020.pdf","seite":"PDF-S. 9","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Festinger, L.; Riecken, H. W.; Schachter, S. (1956): When Prophecy Fails. Minneapolis: University of Minnesota Press","oeffentlich":false},{"typ":"literatur","kurz":"Stone, J. R. (2014): Prophecy. In: Chryssides, G. D.; Zeller, B. E. (Hg.): The Bloomsbury Companion to New Religious Movements. London: Bloomsbury Academic","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"6929ddf32579ffd4"}},{"id":"qx-e-009","clusterId":"E","werkstueckRef":"E.2.1","stufe":1,"question":"Eine Teamleiterin fragt reihum, ob ein Entwurf freigegeben werden soll. Drei Kollegen sagen nacheinander „Ja“, dann bist du an der Reihe. Du kennst die Gruppe seit Jahren und weißt, dass Widerspruch dort selten gut ankommt. Welche der folgenden Reaktionen wäre ein Fall von Konformität in dem Sinn, dass du dein Urteil dem Gruppendruck unterordnest?","options":["Du sagst „Ja“, obwohl du einen Fehler im Entwurf siehst, weil du als Einziger mit „Nein“ auffallen würdest.","Du sagst „Ja“, weil du deinen anfänglichen Fehlerverdacht noch einmal geprüft hast und er sich nicht bestätigt hat.","Du sagst „Nein“ und begründest, welchen Fehler du siehst, obwohl du dich damit gegen die Gruppe stellst.","Du sagst „Ja“, weil du dein Urteil vorab schriftlich festgehalten hattest und dein Ergebnis auch nach den Antworten der anderen unverändert „Ja“ lautet."],"correctIndex":0,"explanation":"Konformität heißt, Verhalten oder Überzeugung an die Gruppe anzupassen, obwohl das eigene Urteil in eine andere Richtung zeigt, ausgelöst durch realen oder bloß eingebildeten Druck. Hier liegt das bei der ersten Reaktion vor: Du erkennst den Fehler und stimmst trotzdem zu, um nicht aus der Reihe zu fallen und nicht ausgegrenzt zu werden. Das ist normativer Einfluss: Du willst gemocht und akzeptiert werden, auch wenn du es besser weißt. Wer nach erneuter Prüfung zu dem Schluss kommt, dass der Entwurf in Ordnung ist, urteilt selbst; dass die Gruppe zufällig dasselbe sagt, macht das nicht zur Anpassung. Dasselbe gilt, wenn du dein Urteil schon vor den Antworten der anderen festgelegt hattest und dabei bleibst: Dein „Ja“ kommt dann aus deinem eigenen Urteil, nicht aus dem Druck der Gruppe. Wer widerspricht, tut das Gegenteil von Anpassung. Das Kennzeichen von Konformität ist also nicht, dass viele dasselbe sagen, sondern dass der Druck der Gruppe das eigene Urteil ersetzt.","coreRule":"Konformität ist die Anpassung des eigenen Verhaltens und der Überzeugungen an die Normen oder das Verhalten einer Gruppe, oft aus realem oder eingebildetem Druck. Prüfstein: Hättest du genauso entschieden, wenn du allein und ohne Blick der anderen geurteilt hättest?","beleg":"Werkstück E.2.1 (Kernidee)","status":"entwurf","scenario":"","kurz":"Konformität liegt vor, wenn der Gruppendruck dein eigenes Urteil ersetzt: Du siehst den Fehler und stimmst trotzdem zu, um nicht aufzufallen. Dass alle dasselbe sagen, macht ein Ja dagegen noch nicht zur Anpassung.","prueffrage":"Was hat sich jeweils zwischen deiner eigenen Prüfung des Entwurfs und deiner lauten Antwort verändert, und wodurch?","rueckmeldung":[{"option":1,"text":"Das Ja wirkt wie Anpassung, weil es mit dem der anderen übereinstimmt. Es entsteht hier aber aus einer eigenen erneuten Prüfung, nicht aus Druck; Übereinstimmung allein macht noch keine Konformität."},{"option":2,"text":"Der Widerspruch gegen die Gruppe kostet Überwindung, deshalb denkt man hier schnell an Gruppendruck. Doch wer seinem Urteil folgt und widerspricht, tut das Gegenteil von Anpassung."},{"option":3,"text":"Hier stimmst du mit allen anderen überein, und das lässt an Anpassung denken. Dein Urteil stand aber schon vor den Antworten der anderen fest und blieb bestehen, es kommt also von dir und nicht vom Gruppendruck."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Open Social Psychology, Kap. 7: Conformity. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter21.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Asch, S. E. (1955): Opinions and Social Pressure. Scientific American 193(5) (Sonderdruck auf einer Lehrseite der University of Vermont, inoffizielle Kopie)","oeffentlich":true,"url":"https://pdodds.w3.uvm.edu/teaching/courses/2009-08UVM-300/docs/others/everything/asch1955a.pdf","seite":"PDF-S. 4","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3a9cbc581dfca3a6"}},{"id":"qx-e-010","clusterId":"E","werkstueckRef":"E.2.1","stufe":2,"question":"Was erklärt dein Schweigen am sparsamsten, und wie lässt sich der Einfluss prüfen?","scenario":"Du bist neu im Team. In der Sitzung loben alle eine Idee, die du für fehlerhaft hältst. Du hast dir deine Einwände sogar schon zurechtgelegt, schweigst aber trotzdem, weil du fürchtest, als Einziger zu widersprechen und dafür schief angesehen zu werden. Später gibst du einer Kollegin gegenüber zu: „Ich hielt den Plan für falsch, wollte aber nicht auffallen.“","options":["Du willst dazugehören und Ablehnung vermeiden. Prüfen lässt sich das, indem du dein Urteil vorab schriftlich festhältst und fragst, ob du alleine im Raum genauso entscheiden würdest.","Du hältst die Gruppe für besser informiert. Prüfen lässt sich das, indem du fragst, welche Belege die anderen für ihr Lob haben und ob sie etwas wissen, was dir fehlt.","Du bist dir deines Urteils nicht sicher. Prüfen lässt sich das, indem du abwartest, ob jemand anderes zuerst widerspricht, und dich dann dessen Meinung anschließt.","Du wirst von den anderen gar nicht beeinflusst. Prüfen lässt sich das, indem du dein Schweigen als bewusste Entscheidung einordnest und die Sache auf sich beruhen lässt."],"correctIndex":0,"explanation":"Die Sachlage spricht klar für einen normativen Einfluss: Du weißt es besser und hast deine Einwände schon formuliert, schweigst aber aus Furcht vor den Reaktionen der Gruppe. Dein Zugeständnis („wollte nicht auffallen“) zeigt dieselbe Triebfeder wie bei Aschs Linien-Versuchen, wo gerade die Angst, als Einziger aus der Reihe zu fallen, der am häufigsten genannte Grund fürs Nachgeben war. Informativer Einfluss würde bedeuten, dass du dem Urteil der Gruppe mehr traust als deinem eigenen. Das passt nicht, denn du hältst die Idee ja weiterhin für fehlerhaft. Auch bei eindeutiger Antwort gaben in Aschs Versuchen rund drei Viertel mindestens einmal der falschen Mehrheit nach. In einer Abwandlung des Asch-Versuchs gaben Versuchspersonen, die ihr Urteil vorher schriftlich festgehalten hatten, der falschen Mehrheit weit seltener nach. Die Kontrollfrage „Würde ich alleine genauso entscheiden?“ trennt das eigene Urteil vom Gruppendruck.","coreRule":"⚡ Wenn du es besser weißt und trotzdem schweigst, wirkt Angst vor Ausgrenzung, nicht Unsicherheit. Leg dein Urteil fest, bevor du die anderen hörst.","beleg":"Werkstück E.2.1 (Kontext & Tiefe, zwei Hauptgründe; Anti-Denkmuster); Fn. gl-e-einfluss (Deutsch & Gerard 1955, S. 629–633), gl-e-asch-gruende (Asch 1956, S. 32, 70), gl-e-selbstbindung (Deutsch & Gerard 1955, S. 632–634), gl-e-asch (Asch 1956, S. 10–11)","status":"entwurf","kurz":"Du hältst den Plan weiter für falsch und schweigst nur aus Furcht vor den Reaktionen: Das spricht für Gruppendruck, nicht für Vertrauen in die Gruppe. Ob das eigene Urteil trägt, zeigt die Frage, ob du allein genauso entscheiden würdest.","prueffrage":"Was sagst du später der Kollegin über den Grund deines Schweigens, und was hältst du da vom Plan?","rueckmeldung":[{"option":1,"text":"Dass eine Gruppe mehr weiß als man selbst, ist oft eine vernünftige Annahme. Hier passt sie nicht: Du hältst den Plan weiterhin für falsch und hast deine Einwände parat, vertraust also deinem eigenen Urteil mehr."},{"option":2,"text":"Zweifel am eigenen Urteil liegen nahe, wenn man neu ist. Hier fehlen sie aber: Deine Einwände sind formuliert, und du hältst den Plan für falsch. Abzuwarten und sich dann anzuschließen, wäre zudem selbst Anpassung."},{"option":3,"text":"Schweigen ist tatsächlich eine Entscheidung. Doch dein Satz „wollte nicht auffallen“ zeigt, was sie lenkte: die Furcht vor den Reaktionen der Gruppe. Das ist Einfluss, und ihn auf sich beruhen zu lassen, klärt nichts."}],"familie":"urteil-vorab-festlegen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Asch, S. E. (1955): Opinions and Social Pressure. Scientific American 193(5) (Sonderdruck auf einer Lehrseite der University of Vermont, inoffizielle Kopie)","oeffentlich":true,"url":"https://pdodds.w3.uvm.edu/teaching/courses/2009-08UVM-300/docs/others/everything/asch1955a.pdf","seite":"PDF-S. 4–5","abruf":"2026-10-12"},{"typ":"url","kurz":"Open Social Psychology, Kap. 7: Conformity. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter21.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Deutsch, M.; Gerard, H. B. (1955): A Study of Normative and Informational Social Influences upon Individual Judgment. Journal of Abnormal and Social Psychology 51(3), S. 629–636","oeffentlich":false,"doi":"10.1037/h0046408"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"ae9008aa3687722e"}},{"id":"qx-e-011","clusterId":"E","werkstueckRef":"E.2.1","stufe":3,"question":"Du leitest diese Runde. Welche Maßnahme senkt den Konformitätsdruck am ehesten – und wie sicher darfst du dir ihrer Wirkung sein?","options":["Die erfahrenste Person äußert sich zuerst, damit sich die Runde an gesichertem Wissen ausrichtet. Sicher ist die Wirkung nur, solange die Erfahrene recht hat.","Alle stimmen offen per Handzeichen ab, damit ein öffentliches Bekenntnis Verantwortung schafft. Sicher ist die Wirkung nur, solange die Runde klein bleibt.","Die Runde diskutiert, bis alle einstimmig zustimmen, damit nur echter Konsens übrig bleibt. Sicher ist die Wirkung nur, solange lange genug diskutiert wird.","Alle halten ihr Urteil schriftlich fest, bevor die anderen sprechen, damit sie sich festlegen, ehe sie zuhören. Sicher ist die Wirkung nur begrenzt, weil sie hier aus einem frühen Versuch mit kleinen Gruppen stammt."],"correctIndex":3,"explanation":"Konformitätsdruck entsteht vor allem, wenn man unter den Augen der Gruppe antworten muss und nicht auffallen will. Wer sein Urteil festlegt, bevor er die anderen hört, nimmt dem Druck den Angriffspunkt. In einer Abwandlung des Asch-Versuchs (Deutsch & Gerard, 1955) gaben Personen, die ihre Einschätzung vorher auf einem Zettel festgehalten hatten, der falschen Mehrheit weit seltener nach. Der Befund stammt aber aus einem frühen Versuch mit nur 11 bis 15 Studierenden je Bedingung (101 insgesamt), und wer seine Notiz wieder löschte, profitierte deutlich weniger. Die Maßnahme ist also plausibel und gut begründet, ihre Stärke ist aber nicht gesichert. Offene Abstimmung und das Streben nach Einstimmigkeit verschärfen den Druck eher, weil Abweichen dann sichtbar und sozial riskant wird. Die erfahrenste Person zuerst sprechen zu lassen, liefert den anderen nur einen Anker, an dem sie sich orientieren.","coreRule":"⚡ Erst festlegen, dann zuhören: Ein schriftliches Urteil vor der Runde entzieht dem Gruppendruck den Angriffspunkt. Wie stark der Effekt ist, zeigen aber nur wenige kleine Versuche.","beleg":"Werkstück E.2.1 (Anti-Denkmuster: Die Taktik); Fn. gl-e-selbstbindung (Deutsch & Gerard 1955, S. 632–634). Gelesen 12.10.2026 im Volltext: Deutsch, M.; Gerard, H. B. (1955): A study of normative and informational social influences upon individual judgment. Journal of Abnormal and Social Psychology 51(3), 629–636, 101 Studierende der New York University, Bedingungen mit N = 11 bis 15 (Tab. 1–3); Zettel nach der Serie weggeworfen (Self-commitment) bzw. mit „Magic Pad“ gelöscht.","status":"zurueckgezogen","scenario":"Bei Entscheidungen in deiner Runde nennt zuerst jemand mit Nachdruck seine Meinung, und fast alle schließen sich an. Später räumen einzelne ein, sie hätten es eigentlich anders gesehen.","kurz":"Wer sein Urteil festhält, bevor er die anderen hört, nimmt dem Druck den Angriffspunkt. Sicher ist das aber nicht: Der Befund stammt aus einem frühen Versuch mit kleinen Gruppen, die Maßnahme ist plausibel, ihre Stärke offen.","prueffrage":"Was hält die Einzelnen in der Sitzung davon ab, ihre abweichende Sicht zu äußern, die sie später doch einräumen?","rueckmeldung":[{"option":0,"text":"Eine erfahrene Einschätzung ist oft hilfreich und kann wirklich richtig sein. Spricht sie aber zuerst, wird sie zum Anker, an dem sich alle ausrichten. Der Druck, sich anzuschließen, sinkt dadurch nicht, er bekommt nur eine Richtung."},{"option":1,"text":"Ein offenes Bekenntnis wirkt verbindlich. Wer abweicht, tut es dabei aber vor aller Augen und riskiert sozial etwas. Das verschärft den Druck eher, statt ihn zu senken, auch in einer kleinen Runde."},{"option":2,"text":"Wirklicher Konsens klingt nach dem Ziel jeder Runde. Verlangt man aber Einstimmigkeit, wird Abweichen riskant, und Zustimmung kann bloße Anpassung sein. Das verstärkt den Druck eher, auch wenn lange diskutiert wird."}],"familie":"urteil-vorab-festlegen","fertigkeit":"F5","quellen":[{"typ":"literatur","kurz":"Deutsch, M.; Gerard, H. B. (1955): A Study of Normative and Informational Social Influences upon Individual Judgment. Journal of Abnormal and Social Psychology 51(3), S. 629–636","oeffentlich":false,"doi":"10.1037/h0046408"},{"typ":"literatur","kurz":"Asch, S. E. (1956): Studies of Independence and Conformity: I. A Minority of One Against a Unanimous Majority. Psychological Monographs 70(9), Whole No. 416","oeffentlich":false,"doi":"10.1037/h0093718"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e1ba651b87cbfa82"}},{"id":"qx-e-012","clusterId":"E","werkstueckRef":"E.2.1","stufe":4,"question":"Ein Blogbeitrag schreibt: „Drei Viertel aller Menschen folgen bei jeder Gelegenheit der Mehrheit, selbst gegen ihre eigenen Augen.“ Als Beleg dient das berühmte Linien-Experiment von Solomon Asch, in dem 75 % der Versuchspersonen nachgaben. Was bedeutet diese Zahl, und was folgt daraus für die Behauptung des Blogbeitrags?","options":["Drei Viertel aller Antworten in den kritischen Durchgängen waren falsch; die Mehrheit der Versuchspersonen gab also durchgehend nach.","Die Zahl galt nur für Studierende im Jahr 1956; spätere Wiederholungen in anderen Ländern fanden durchweg praktisch keine Konformität mehr.","Rund drei Viertel gaben in mindestens einem von zwölf kritischen Durchgängen nach; im Mittel waren nur 36,8 % der Antworten konform.","Die Zahl ist ein Erinnerungsfehler späterer Lehrbücher; Asch selbst berichtete, dass fast alle Teilnehmer der richtigen Linie treu blieben."],"correctIndex":2,"explanation":"Die 75 % messen „mindestens einmal nachgegeben“ (genau 76 %; 94 von 123 Personen), nicht „bei jeder Gelegenheit“. Wer eine Prozentzahl liest, muss fragen, was gezählt wurde: Personen mit mindestens einem Nachgeben oder Antworten insgesamt. Im Mittel waren nur gut ein Drittel der Antworten konform (36,8 %), und 24 % der Versuchspersonen widerstanden durchgehend. Der Blogbeitrag macht aus „mindestens einmal“ ein „immer“. Eine Replikation an der Universität Bern (Franzen & Mader 2023) fand mit 33 % falschen Antworten fast denselben Wert, die Zahl ist also kein Artefakt von 1956. Der Sog ist real, aber deutlich schwächer, als die Schlagzeile behauptet; er schwankt außerdem mit Zeit und Kultur, und schon eine einzige abweichende Stimme schwächt ihn deutlich.","coreRule":"„Mindestens einmal nachgegeben“ ist etwas anderes als „immer nachgegeben“ – prüfe, was eine Prozentzahl tatsächlich misst.","beleg":"Werkstück E.2.1 (Abschnitt „Der Test mit den Linien“); Fn. gl-e-asch (Asch 1956, S. 10–11; Franzen & Mader 2023, S. 1 und 6–8). Franzen, A.; Mader, S. (2023): The power of social influence: A replication and extension of the Asch experiment. PLOS ONE 18(11), e0294325, https://doi.org/10.1371/journal.pone.0294325 (33 % falsche Antworten ohne Anreiz, 25 % mit Anreiz; Asch 1955: 36,8 %); gelesen 12.10.2026.","status":"entwurf","scenario":"","kurz":"Die 75 % zählen Personen, die mindestens einmal nachgaben, nicht Antworten: Im Mittel war nur gut ein Drittel der Antworten konform. Der Blog macht aus „mindestens einmal“ ein „immer“; der Sog ist real, aber viel schwächer.","prueffrage":"Was müsste man über eine Versuchsperson wissen, um sagen zu können, dass sie „bei jeder Gelegenheit“ nachgegeben hat?","rueckmeldung":[{"option":0,"text":"Dass die Mehrheit nachgab, stimmt, aber nur mindestens einmal. Gezählt wurden Personen, nicht Antworten: Im Mittel war gut ein Drittel der Antworten konform, und knapp ein Viertel widerstand durchgehend."},{"option":1,"text":"Einzelne Wiederholungen fanden tatsächlich kaum Konformität. „Durchweg“ stimmt aber nicht: Viele spätere Studien in verschiedenen Ländern fanden den Effekt wieder. Er schwankt mit Zeit und Kultur, verschwindet aber nicht."},{"option":3,"text":"Die Zahl stammt tatsächlich aus Aschs Daten, nur wird sie oft zu „immer“ verkürzt. Dass fast alle standhaft blieben, stimmt aber auch nicht: Etwa drei Viertel gaben mindestens einmal nach, nur 24 % nie."}],"familie":"zahl-zur-quelle","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Franzen, A.; Mader, S. (2023): The power of social influence: A replication and extension of the Asch experiment. PLOS ONE 18(11), e0294325","oeffentlich":true,"doi":"10.1371/journal.pone.0294325","abruf":"2026-10-12"},{"typ":"url","kurz":"Open Social Psychology, Kap. 7: Conformity. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter21.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Asch, S. E. (1956): Studies of Independence and Conformity: I. A Minority of One Against a Unanimous Majority. Psychological Monographs 70(9), Whole No. 416","oeffentlich":false,"doi":"10.1037/h0093718"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"0eb8a0115b3f4c9c"}},{"id":"qx-e-013","clusterId":"E","werkstueckRef":"E.2.2","stufe":1,"question":"Welche Rückfrage prüft am besten, ob Marlene Brandt hier zu Recht als Autorität auftritt?","options":["Wie viele Jahre Berufserfahrung hat sie, und tritt sie in Interviews überzeugend und selbstsicher auf?","Welche Daten und Methoden stützen genau diese Aussage, und könnten Dritte sie nachprüfen oder widerlegen?","Wie viele Zuhörer folgen ihr, und stimmen die Kommentare unter ihren Beiträgen mehrheitlich zu?","Hat sie einen Titel, und lässt sich ihre Position in einer Organisation oder Hierarchie nachweisen?"],"correctIndex":1,"explanation":"Echte Autorität beruht auf nachprüfbarer Kompetenz: Sie ist auf ein Fachgebiet beschränkt, ist provisorisch und offen für Kritik und lädt zur Überprüfung ein („Hier sind meine Daten, prüf sie nach.“). Marlene Brandt dagegen verlangt Vertrauen in ihre Person und weicht der Beleg-Frage aus. Die Frage nach Daten und Methoden zur konkreten Behauptung trennt beides: Sind sie vorhanden und prüfbar, ist Vertrauen ein sinnvoller Zeitgewinn; fehlen sie, bleibt nur Ausstrahlung. Berufsjahre, Selbstsicherheit, Reichweite und Beifall sagen nichts darüber, ob genau diese Aussage stimmt. Auch ein Titel ersetzt nicht die Nachprüfbarkeit: Expertenautorität ist auf ein Fachgebiet beschränkt, und eine Position in einer Hierarchie belegt noch nicht, dass die Behauptung selbst stimmt.","coreRule":"⚡ Echte Expertise ist spezifisch, vorläufig und prüfbar – Autorität ohne diese drei Eigenschaften ist verdächtig.","beleg":"Werkstück E.2.2 (Kontext & Tiefe: Die zwei Gesichter der Autorität, Typ 1)","status":"entwurf","scenario":"In einem Podcast erklärt die Ernährungsberaterin Marlene Brandt mit großer Überzeugung, dass ein bestimmtes Nahrungsergänzungsmittel Erkältungen verhindert. Als die Moderatorin nach Belegen fragt, antwortet sie: „Ich arbeite seit 20 Jahren in dem Feld. Wer mir nicht vertraut, versteht nichts davon.“ Die Hörerin Jana überlegt, wie sie die Aussage einordnen soll.","kurz":"Autorität trägt, wenn sie sich prüfen lässt: Wer sich zu Recht auf Kompetenz beruft, kann für genau diese Aussage Daten und Methoden nennen. Brandt bittet stattdessen um Vertrauen in ihre Person, und das ersetzt keinen Beleg.","prueffrage":"Was antwortet Marlene Brandt genau auf die Frage nach Belegen, und was davon betrifft das Mittel selbst?","rueckmeldung":[{"option":0,"text":"Zwanzig Jahre im Feld und ein souveräner Auftritt wirken glaubwürdig, und Erfahrung kann ein Hinweis auf Kompetenz sein. Ob genau diese Aussage über das Mittel stimmt, zeigt beides aber nicht."},{"option":2,"text":"Viele Zuhörer und viel Beifall zeigen, dass jemand ankommt, und das liegt nahe, wenn man Autorität einschätzen will. Beliebtheit sagt jedoch nichts darüber, ob die Behauptung zutrifft, und auch eine große Menge kann sich irren."},{"option":3,"text":"Ein Titel oder eine Position kann auf eine Ausbildung hindeuten. Kompetenz gilt aber nur für ein Fachgebiet, und ein Titel belegt nicht, dass genau diese Behauptung über das Mittel stimmt. Entscheidend bleibt, ob sie sich prüfen lässt."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"The Royal Society: History of the Royal Society („Nullius in verba“)","oeffentlich":true,"url":"https://royalsociety.org/about-us/who-we-are/history/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kim, S. H.: Max Weber. Stanford Encyclopedia of Philosophy, Abschnitt 6.1 „Domination and Legitimacy“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/weber/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"01493743e766176b"}},{"id":"qx-e-014","clusterId":"E","werkstueckRef":"E.2.2","stufe":2,"question":"Woran lässt sich bei diesem Auftreten am besten erkennen, dass sich die Autorität des Kanal-Betreibers nicht auf Evidenz stützt?","scenario":"Ein Kanal-Betreiber erklärt in jedem Video Politik, Medizin und Ernährung mit absoluter Gewissheit. Wer Zweifel äußert, sei „vom System gekauft“, und die Zuschauer sollen „ihm vertrauen, nicht den Fakten“.","options":["Er äußert sich zu so vielen Themen so selbstsicher, dass ein sehr breites Fachwissen naheliegt.","Er hat ein großes Publikum, und so viel Reichweite gewinnt nur, wer ohne Belege auskommt.","Er verlangt Vertrauen in seine Person und behandelt Zweifel als Verrat.","Er tritt im Internet auf, und Autorität gibt es nur in formalen Hierarchien wie Armee oder Behörde."],"correctIndex":2,"explanation":"Evidenzbasierte Autorität ist spezifisch, vorläufig und lädt zur Überprüfung ein („Hier sind meine Daten, prüf sie nach“). Der Kanal-Betreiber zeigt das Gegenteil: Er verlangt Vertrauen in seine Person statt in nachprüfbare Methoden und Daten und behandelt Zweifel als Verrat. Dass er sich zu Politik, Medizin und Ernährung gleichermaßen selbstsicher äußert, spricht nicht für breites Fachwissen, sondern für den Anspruch auf eine allumfassende Autorität. Ein großes Publikum sagt nichts darüber, ob jemand Belege hat, denn auch gut belegte Fachleute können viele erreichen. Und Autorität gibt es nicht nur in formalen Hierarchien: Sie wird Menschen auch wegen ihrer Ausstrahlung oder zugeschriebener Kompetenz zugesprochen, im Internet ebenso wie anderswo.","coreRule":"⚡ Wer überall Bescheid weiß und Zweifel als Verrat behandelt, beruft sich auf Position oder Ausstrahlung, nicht auf Evidenz.","beleg":"Werkstück E.2.2 (Kontext & Tiefe: Typ 2; Red Flags)","status":"entwurf","kurz":"Wer Vertrauen in die eigene Person verlangt und Zweifel als Verrat behandelt, lädt nicht zur Überprüfung ein. Evidenzbasierte Autorität zeigt dagegen Daten und Methoden, die man nachprüfen kann.","prueffrage":"Was bietet der Betreiber seinen Zuschauern an, damit sie eine seiner Aussagen selbst überprüfen können?","rueckmeldung":[{"option":0,"text":"Wer zu allem Auskunft gibt, wirkt zunächst kompetent. Gerade diese Breite spricht aber nicht für großes Wissen, sondern für einen Anspruch auf Zuständigkeit für alles; echte Expertise ist meist eng umgrenzt und räumt Unsicherheit ein."},{"option":1,"text":"Große Reichweite kann tatsächlich mit Zuspitzung statt Belegen gewonnen werden. Daraus folgt aber nicht, dass jeder mit großem Publikum ohne Belege auskommt; auch gut belegte Fachleute erreichen viele. Aufschlussreicher ist sein Umgang mit Zweifel."},{"option":3,"text":"Formale Positionen sind tatsächlich eine Quelle von Autorität, aber nicht die einzige: Auch Ausstrahlung und zugeschriebene Kompetenz verleihen Autorität, das Internet schließt sie also nicht aus. Das Problem liegt im Umgang mit Zweifel."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Kim, S. H.: Max Weber. Stanford Encyclopedia of Philosophy, Abschnitt 6.1 „Domination and Legitimacy“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/weber/","abruf":"2026-10-12"},{"typ":"url","kurz":"The Royal Society: History of the Royal Society („Nullius in verba“)","oeffentlich":true,"url":"https://royalsociety.org/about-us/who-we-are/history/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"2e8e7d727281ffad"}},{"id":"qx-e-015","clusterId":"E","werkstueckRef":"E.2.2","stufe":3,"question":"Ein Vorgesetzter sagt einem Mitarbeiter, der Bedenken gegen eine Anweisung äußert: „Ich übernehme die volle Verantwortung. Du führst nur aus.“ Wie wirkt dieser Satz auf das Verhalten des Mitarbeiters, und warum?","options":["Er macht eher weiter, weil er sich nun als bloßes Werkzeug der Anweisung statt als moralisch Handelnder sieht.","Er bricht eher ab, weil er sich entlastet fühlt und ohne Schuldgefühl aufhören darf.","Er macht eher weiter, weil er die Anweisung nun für harmlos hält und keinen Schaden mehr erwartet.","Er prüft die Anweisung eher gründlich nach, weil er den Chef nun für einen Fachexperten hält."],"correctIndex":0,"explanation":"Der Satz lässt die Verantwortung scheinbar bei einer anderen Person. Genau das erlaubt es dem Mitarbeiter, sich nicht mehr als moralisch Handelnden, sondern als bloßes Werkzeug der Anweisung zu sehen. In Milgrams Experimenten war diese Verantwortungsübernahme einer der Faktoren, die das extreme Verhalten förderten. Die anderen Deutungen tragen nicht: Wer sich als bloßes Werkzeug sieht, hört deshalb nicht eher auf, denn die Zusage nimmt ihm gerade den Anlass, die eigene Rolle zu hinterfragen. Für Harmlosigkeit liefert der Satz kein Argument, er ändert nur, wer sich zuständig fühlt. Und mit der Nachprüfung evidenzbasierter Kompetenz hat der Satz nichts zu tun. Die vollständige Abgabe der Verantwortung ist zudem der Kipppunkt zum gefährlichen Gehorsam.","coreRule":"⚡ Wer Verantwortung vollständig an eine Autorität abgibt, wird vom Handelnden zum Werkzeug.","beleg":"Werkstück E.2.2 (Die situativen Faktoren des Gehorsams; Der Kipppunkt)","status":"entwurf","scenario":"Ein Mitarbeiter soll auf Anweisung seines Chefs Kundendaten ändern, was ihm nicht geheuer ist. Er zögert und sagt, er wolle dafür nicht geradestehen. Der Chef antwortet: „Ich übernehme die volle Verantwortung. Du führst nur aus.“","kurz":"Die Zusage lässt die Verantwortung scheinbar beim Chef, und so sieht sich der Mitarbeiter eher als Werkzeug denn als moralisch Handelnder. Wer sich entlastet fühlt, hat weniger Anlass, die eigene Rolle zu hinterfragen, und macht eher weiter.","prueffrage":"Wogegen richtete sich das Zögern des Mitarbeiters, und auf welchen Teil davon antwortet der Chef?","rueckmeldung":[{"option":1,"text":"Entlastet fühlt er sich tatsächlich, aber diese Entlastung wirkt in die andere Richtung. Wer die Verantwortung abgegeben hat, sieht weniger Anlass, die eigene Rolle zu hinterfragen, und bricht deshalb eher nicht ab."},{"option":2,"text":"Der Satz sagt nichts darüber, ob die Änderung der Daten Schaden anrichtet. Er verschiebt nur, wer sich zuständig fühlt. Die Bedenken des Mitarbeiters können bleiben, er führt dann trotzdem aus."},{"option":3,"text":"Dass der Chef die Verantwortung übernimmt, macht ihn nicht zum Fachmann. Der Satz sagt nichts über sein Wissen und liefert keinen Anlass, nachzuprüfen. Er mindert eher die Neigung, selbst hinzusehen."}],"familie":"verantwortung-benennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Uzelac, E.; Yang, Y.-F. (2026): Obedience to Authority. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter4.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Milgram, S. (1974): Obedience to Authority: An Experimental View. New York: Harper & Row","oeffentlich":false},{"typ":"url","kurz":"Milgram, S. (1963): Behavioral Study of Obedience. Journal of Abnormal and Social Psychology 67(4), S. 371–378 (Kopie auf einer Seite der University of Miami)","oeffentlich":true,"url":"https://www.psy.miami.edu/_assets/pdf/rpo-articles/milgram-1963.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"2a92bc8af8c5c9f7"}},{"id":"qx-e-016","clusterId":"E","werkstueckRef":"E.2.2","stufe":4,"question":"Ein Podcast sagt: „Milgram bewies: Zwei Drittel aller Menschen gehorchen immer, bis es tödlich wird.“ Was ist an dieser Aussage vor allem problematisch?","options":["Sie macht aus dem Ergebnis einer einzelnen Versuchsanordnung ein Gesetz, das angeblich in jeder Situation gilt.","Sie verwechselt Gehorsam mit Konformität, denn in dem Versuch spielte der Druck der Gruppe die entscheidende Rolle.","Sie nennt eine Zahl, die sich nicht überprüfen lässt, weil es zu dem Versuch keine veröffentlichten Daten gibt.","Sie unterschätzt die Quote, denn je weiter das Opfer entfernt war, desto seltener gehorchten die Teilnehmer."],"correctIndex":0,"explanation":"Die Zahl selbst ist belegt: In der Basisanordnung von 1963 gingen 26 von 40 Teilnehmern (65 %) bis zum 450-Volt-Schalter. Aber Milgram testete rund zwanzig Variationen, und dort schwankte die Quote zwischen null und über neunzig Prozent; die Situation (Legitimität der Autorität, Übernahme der Verantwortung, schrittweise Eskalation, Distanz zum Opfer) verschiebt sie erheblich. „Immer“ ist deshalb der Fehler: Aus einem Ergebnis unter bestimmten Bedingungen wird eine Naturkonstante gemacht, und das Gegenteil davon ist nicht „nie“, sondern „je nach Lage“. Größere Distanz zum Opfer erleichterte den Gehorsam übrigens, statt ihn zu erschweren. Mit der Frage „Unter welchen Bedingungen wurde das gemessen?“ lässt sich jede berühmte Zahl prüfen.","coreRule":"⚡ Eine berühmte Zahl gehört zu einer bestimmten Anordnung – ändere die Anordnung, und sie ändert sich.","beleg":"Werkstück E.2.2 (Einstieg; Situative Faktoren); Fn. gl-e-milgram (Milgram 1963, S. 371–378; Burger 2009, S. 1 f.); Fn. gl-e-milgram-varianten (Milgram 1974; Haslam & Reicher 2012)","status":"entwurf","scenario":"","kurz":"Die Zahl stimmt für die Basisanordnung von 1963. Aber in rund zwanzig Variationen schwankte die Quote zwischen null und über neunzig Prozent. Wer „immer“ sagt, macht aus einem Ergebnis unter bestimmten Bedingungen eine Naturkonstante.","prueffrage":"Wo und mit wem wurde die Zahl ermittelt, und für wen soll sie laut Podcast gelten?","rueckmeldung":[{"option":1,"text":"Gehorsam gegenüber einer Autorität und Anpassung an eine Gruppe sind tatsächlich verschiedene Dinge. In der Basisanordnung gab aber ein Versuchsleiter die Anweisungen, keine Gruppe, und das „immer“ bliebe ohnehin stehen."},{"option":2,"text":"Eine berühmte Zahl, die in Podcasts kursiert, weckt schnell Misstrauen. Hier trägt es aber nicht: Die 65 % stammen aus Milgrams veröffentlichter Studie von 1963, und auch zu den späteren Variationen liegen Ergebnisse vor."},{"option":3,"text":"Die Entfernung zum Opfer spielte tatsächlich eine Rolle. Sie wirkte aber in die andere Richtung: Je größer die Distanz, desto leichter fiel der Gehorsam. Zudem liegt der Fehler nicht in einer zu niedrigen Quote, sondern im „immer“."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Milgram, S. (1963): Behavioral Study of Obedience. Journal of Abnormal and Social Psychology 67(4), S. 371–378 (Kopie auf einer Seite der University of Miami)","oeffentlich":true,"url":"https://www.psy.miami.edu/_assets/pdf/rpo-articles/milgram-1963.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Uzelac, E.; Yang, Y.-F. (2026): Obedience to Authority. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter4.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Haslam, S. A.; Reicher, S. D. (2012): Contesting the ‚Nature‘ of Conformity: What Milgram and Zimbardo’s Studies Really Show. PLOS Biology 10(11), e1001426","oeffentlich":true,"doi":"10.1371/journal.pbio.1001426","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"092861d1bf24b1fd"}},{"id":"qx-e-017","clusterId":"E","werkstueckRef":"E.2.3","stufe":1,"question":"Welcher Denkmechanismus erklärt das Verhalten der Passantin am besten, und was wäre die wirksamste Gegenmaßnahme?","scenario":"Auf einem vollen Bahnsteig sackt jemand zusammen. Zwanzig Menschen stehen herum, alle sehen hin, keiner bewegt sich. Eine Passantin sagt hinterher: „Ich dachte die ganze Zeit, das ist schlimm. Aber ich habe gar nicht erst gerufen, denn bei so vielen Leuten hat bestimmt schon jemand den Notruf gewählt.“","options":["Sie hält die Lage für harmlos, weil alle anderen ruhig bleiben. Gegenmaßnahme: Selbst genau hinsehen, ob es wirklich ein Notfall ist.","Sie scheut die Blamage, falls es doch kein Notfall ist. Gegenmaßnahme: Sich klarmachen, dass Fehlalarme selten bestraft werden.","Sie sieht ihre Verantwortung auf alle Anwesenden verteilt. Gegenmaßnahme: Selbst handeln oder eine Person direkt ansprechen.","Sie wartet darauf, dass eine zuständige Person das Kommando übernimmt. Gegenmaßnahme: Sich der Anweisung dieser Person ausdrücklich unterordnen."],"correctIndex":2,"explanation":"Die Passantin hält die Lage ja für schlimm, sie schätzt sie also nicht als harmlos ein. Ihr Gedanke „bestimmt hat schon jemand angerufen“ zeigt, dass sie die Verantwortung auf die anderen Anwesenden abgibt: Je mehr Menschen dabei sind, desto kleiner fühlt sich der eigene Anteil an. Das nennt man Diffusion der Verantwortung. Dass alle ruhig bleiben und deshalb nichts Schlimmes sein kann, wäre pluralistische Ignoranz; die Angst vor der Blamage wäre Bewertungsangst. Beides passt nicht zu dem, was die Passantin sagt. Das Warten auf eine zuständige Person wäre eine Abgabe der Verantwortung an eine Autorität, nicht ihr Verschwinden in der Menge. Wirksam gegen die Diffusion ist, die Verantwortung wieder zu personalisieren: selbst anpacken oder eine konkrete Person direkt ansprechen, etwa „Sie da, rufen Sie bitte den Notruf!“. Eine allgemeine Bitte um Hilfe lässt die Verantwortung dagegen weiter in der Menge verschwinden.","coreRule":"⚡ „Wird schon jemand anders tun“ – so verschwindet die eigene Verantwortung in der Menge. Gegenmittel: selbst handeln oder gezielt eine Person ansprechen.","beleg":"Werkstück E.2.3 (Kernidee; Kontext & Tiefe, drei Hauptgründe; Verbindungen)","status":"entwurf","kurz":"Die Passantin hält die Lage für schlimm und nimmt trotzdem an, dass jemand anderes anruft: Je mehr Menschen dabei sind, desto kleiner fühlt sich der eigene Anteil. Dagegen hilft, selbst zu handeln oder eine konkrete Person direkt anzusprechen.","prueffrage":"Was sagt die Passantin selbst darüber, wie sie die Lage einschätzt, und worauf stützt sie ihre Entscheidung, nicht zu rufen?","rueckmeldung":[{"option":0,"text":"Dass andere ruhig bleiben und man deshalb Entwarnung annimmt, gibt es tatsächlich. Die Passantin sagt aber, sie habe die ganze Zeit gedacht, es sei schlimm. Ihr Zögern kommt also nicht aus einer Fehleinschätzung der Lage."},{"option":1,"text":"Angst vor Blamage hält Menschen tatsächlich manchmal vom Helfen ab. Die Passantin nennt aber keine solche Sorge, sondern vermutet, dass schon jemand angerufen hat. Dieser Gedanke gibt den Ausschlag, nicht die Furcht vor dem Urteil anderer."},{"option":3,"text":"Auf eine zuständige Person zu warten, wäre eine eigene Form, Verantwortung abzugeben. Auf dem Bahnsteig tritt aber niemand mit Autorität auf; die Passantin verlässt sich auf die Menge, und die Gegenmaßnahme setzt eine Person voraus, die fehlt."}],"familie":"verantwortung-benennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Barleben, L.; O’Mahony, A. (2026): Bystander Effect. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter13.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Bundeskriminalamt Österreich (2024): Mehr Zivilcourage – 6 Tipps für den Ernstfall. Wien","oeffentlich":true,"url":"https://www.bundeskriminalamt.at/212/service/files/200_2024_broschuere_zivilcourage_a5_v20240624_ansicht.pdf","seite":"S. 7","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Fischer, P.; Krueger, J. I.; Greitemeyer, T. u. a. (2011): The bystander-effect: A meta-analytic review on bystander intervention in dangerous and non-dangerous emergencies. Psychological Bulletin 137(4), S. 517–537","oeffentlich":false,"doi":"10.1037/a0023304"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"5d2e5371c3f49481"}},{"id":"qx-e-018","clusterId":"E","werkstueckRef":"E.2.3","stufe":2,"question":"Was ist an diesem Vorgehen das Hauptproblem – und was wäre die wirksamere Alternative?","options":["Der Ruf richtet sich an niemanden Bestimmten, daher fühlt sich jeder nur zum Teil zuständig. Wirksamer wäre es, eine einzelne Person direkt anzusprechen und ihr eine konkrete Bitte zu nennen.","Der Ruf ist zu leise, um bei Dutzenden Passanten Aufmerksamkeit zu erregen. Wirksamer wäre es, noch lauter und länger zu rufen, bis sich einige Menschen angesprochen fühlen.","Der Ruf wirkt auf Passanten dramatisch und verunsichert sie zusätzlich. Wirksamer wäre es, ruhig liegen zu bleiben, bis jemand von selbst die Führung übernimmt.","Der Ruf erreicht zu wenige Menschen gleichzeitig. Wirksamer wäre es abzuwarten, bis sich mehr Passanten um ihn sammeln, weil dann eher jemand hilft."],"correctIndex":0,"explanation":"Wer „Kann mir jemand helfen?“ ruft, macht niemanden persönlich zuständig: Jeder kann denken, ein anderer werde schon helfen, und die gefühlte Verantwortung verteilt sich auf alle Anwesenden. Dass alle ruhig bleiben, wirkt zudem wie ein Signal, dass nichts Schlimmes passiert ist. Wer eine einzelne Person direkt anspricht und ihr eine konkrete Bitte nennt, personalisiert die Verantwortung und macht Hilfe wahrscheinlicher. Ein lauterer Ruf bleibt ungerichtet, ruhiges Liegenbleiben bestärkt den Eindruck, dass nichts Ernstes vorliegt, und mehr Zuschauer helfen eher nicht, weil sich dann jeder noch leichter auf die anderen verlässt. Das Prinzip gilt auch für Zeugen: die Führung übernehmen und Aufgaben verteilen („Ich kümmere mich um den Verletzten, können Sie bitte den Notruf wählen?“).","coreRule":"⚡ Aus „Kann mir jemand helfen?“ wird „Sie da, rufen Sie bitte den Notarzt“ – Verantwortung braucht einen Namen.","beleg":"Werkstück E.2.3 (Das Anti-Denkmuster: Wenn du Hilfe brauchst; Wenn du Zeuge bist)","status":"entwurf","scenario":"Ein Mann stürzt in einer belebten Fußgängerzone und kann sich nicht mehr aufrichten. Vor Schmerzen ruft er laut in die Menge: „Kann mir bitte jemand helfen?“ Dutzende Menschen gehen vorbei, einige schauen kurz hin, niemand bleibt stehen. Alle wirken ruhig.","kurz":"Ein Ruf an alle macht niemanden persönlich zuständig: Jeder kann denken, dass sicher ein anderer hilft. Wer eine Person direkt anspricht und ihr eine konkrete Bitte nennt, macht Hilfe wahrscheinlicher.","prueffrage":"Wie viele Menschen hören den Ruf, woran ist zu erkennen, dass sie ihn bemerkt haben, und was tun sie dann?","rueckmeldung":[{"option":1,"text":"Mehr Lautstärke wirkt wie die naheliegende Lösung, wenn niemand reagiert. Gehört wurde er aber offenbar, einige schauen hin. Auch ein lauterer Ruf bliebe an alle gerichtet und würde niemanden persönlich zuständig machen."},{"option":2,"text":"Dass ein lauter Ruf Passanten verunsichern kann, ist denkbar. Ruhig liegen zu bleiben würde aber den Eindruck verstärken, dass nichts Ernstes vorliegt, und die Verantwortung bliebe auf alle verteilt."},{"option":3,"text":"Mehr Zuschauer wirken wie mehr Chancen auf Hilfe. Doch je mehr Menschen da sind, desto leichter verlässt sich jeder auf die anderen. Wirksamer ist, eine einzelne Person direkt anzusprechen und ihr eine konkrete Bitte zu nennen."}],"familie":"verantwortung-benennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bundeskriminalamt Österreich (2024): Mehr Zivilcourage – 6 Tipps für den Ernstfall. Wien","oeffentlich":true,"url":"https://www.bundeskriminalamt.at/212/service/files/200_2024_broschuere_zivilcourage_a5_v20240624_ansicht.pdf","seite":"S. 7","abruf":"2026-10-12"},{"typ":"url","kurz":"Barleben, L.; O’Mahony, A. (2026): Bystander Effect. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter13.html","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"b50ef5dab3a76c3b"}},{"id":"qx-e-019","clusterId":"E","werkstueckRef":"E.2.3","stufe":3,"question":"Wie solltest du mit dieser Behauptung umgehen und warum?","options":["Die Geschichte ist als erledigt zu betrachten, denn die Prüfung der Gerichtsakten hat die Kernpunkte widerlegt; ihr weites Verbreitetsein sagt nichts über ihre Richtigkeit.","Die Geschichte bleibt gültig, denn eine Behauptung, die über Jahrzehnte in vielen Lehrbüchern wiederholt wurde, ist schon oft genug geprüft worden.","Die Geschichte bleibt gültig, denn auch wenn einzelne Details nicht stimmen, zeigt das Gesamtbild, dass die meisten Menschen im Notfall nicht helfen.","Die Geschichte ist nur teilweise widerlegt, denn solange sich die genaue Zahl der Zeugen nicht belegen lässt, ist der Kern der Behauptung ebenso wenig zu entkräften."],"correctIndex":0,"explanation":"Eine Behauptung wird nicht dadurch wahr, dass sie oft wiederholt wird. Entscheidend ist, ob sie einer Prüfung an den Quellen standhält. Die Auswertung der Gerichtsakten zeigte: Kaum jemand konnte den Angriff als Ganzes sehen, mindestens zwei Anwohner riefen die Polizei, eine Nachbarin lief hinunter und hielt die Sterbende im Arm, bis der Rettungswagen kam, und die Zahl 38 stammt aus keiner belegbaren Zählung. Die Erzählung ist damit in ihren Kernpunkten falsch. Dass sie trotzdem zur Gründungsgeschichte der Forschung darüber wurde, wann Zuschauer eingreifen, zeigt nur, wie zählebig eine eingängige Geschichte ist. Ob Menschen in Gruppen seltener helfen, muss man an anderen Belegen prüfen, etwa an kontrollierten Experimenten, nicht an dieser Erzählung.","coreRule":"⚡ Eine eingängige Geschichte ist kein Beleg – auch ein oft wiederholter Klassiker kann ein Mythos sein; prüfe die Quelle, nicht die Verbreitung.","beleg":"Werkstück E.2.3 (Einstieg); Fn. gl-e-genovese (Manning, Levine, Collins 2007, S. 555–562; Gansberg 1964, NYT)","status":"entwurf","scenario":"In einem Seminar sagt jemand: „Es ist bewiesen, dass 38 Menschen in New York einen Mord beobachtet und alle weggesehen haben. Das zeigt, wie herzlos Großstädter sind.“ Er beruft sich darauf, dass diese Geschichte in vielen Lehrbüchern steht und seit Jahrzehnten erzählt wird. Eine Nachprüfung der Gerichtsakten ergab später: Kaum jemand konnte den Angriff als Ganzes sehen, mindestens zwei Anwohner riefen die Polizei, und eine Nachbarin hielt die Sterbende im Arm, bis der Rettungswagen kam. Die Zahl 38 stammt aus keiner belegbaren Zählung.","quote":"","quoteLabel":"","kurz":"Eine Geschichte wird nicht dadurch wahr, dass sie oft erzählt wird. Maßgeblich ist die Prüfung an den Quellen, und die Gerichtsakten widerlegen die Kernpunkte: Es gab Hilfe, kaum jemand sah alles, und die Zahl 38 ist nicht belegt.","prueffrage":"Welche Teile der Geschichte bleiben stehen, wenn man nur gelten lässt, was sich an den Akten belegen lässt?","rueckmeldung":[{"option":1,"text":"Viele Lehrbücher wirken wie ein Gütesiegel. Wiederholung ist aber keine Prüfung: Als die Gerichtsakten später nachgeprüft wurden, hielten die Kernpunkte nicht stand."},{"option":2,"text":"Dass ein Gesamtbild falsche Details überstehen kann, klingt vernünftig. Hier ruht es aber auf den widerlegten Punkten, denn es gab Hilfe. Ob Menschen im Notfall helfen, lässt sich nur an anderen Belegen prüfen, etwa an Experimenten."},{"option":3,"text":"Richtig ist, dass sich die Zahl 38 nicht belegen lässt. Widerlegt sind aber auch die Kernpunkte: Kaum jemand sah den Angriff ganz, mindestens zwei riefen die Polizei, eine Nachbarin half. Belege schuldet die Behauptung, nicht ihre Kritik."}],"familie":"lehrgeschichte-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Clark, R. P. (2016): Misremembering Kitty Genovese. Poynter Institute","oeffentlich":true,"url":"https://www.poynter.org/reporting-editing/2016/misremembering-kitty-genovese/","abruf":"2026-10-12"},{"typ":"url","kurz":"Barleben, L.; O’Mahony, A. (2026): Bystander Effect. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter13.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Manning, R.; Levine, M.; Collins, A. (2007): The Kitty Genovese Murder and the Social Psychology of Helping: The Parable of the 38 Witnesses. American Psychologist 62(6), S. 555–562","oeffentlich":false,"doi":"10.1037/0003-066X.62.6.555"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"14b4942916c7414a"}},{"id":"qx-e-020","clusterId":"E","werkstueckRef":"E.2.3","stufe":4,"question":"Ein Kollege sagt zur Klimakrise: „Es gibt so viele andere, was kann ich als Einzelner schon tun?“ Welcher psychologische Mechanismus steckt am ehesten hinter diesem Gedanken?","options":["Pluralistische Ignoranz: Jeder hält das Problem insgeheim für harmlos, weil alle anderen nach außen ruhig bleiben.","Eine besonders starke Wirkung des Zuschauereffekts: Je mehr Menschen anwesend sind, desto weniger greift in einem Notfall überhaupt noch jemand ein.","Eine realistische Einschätzung: Diffusion der Verantwortung tritt nur bei Notfällen mit direkter Lebensgefahr auf und passt hier nicht.","Diffusion der Verantwortung: Bei einem riesigen Problem mit vielen Beteiligten verteilt sich das Verantwortungsgefühl, die eigene Rolle wirkt winzig."],"correctIndex":3,"explanation":"Der Satz zeigt das Muster der verteilten Verantwortung: Wenn ein Problem riesig ist und sehr viele andere ebenfalls betroffen sind, fühlt sich der Einzelne nur noch für einen winzigen Anteil zuständig und denkt, jemand anderes werde schon etwas tun. Das ist die gleiche Logik wie bei einem Unfall mit vielen Umstehenden. Die Annahme der Pluralistischen Ignoranz passt nicht, denn der Kollege hält das Problem nicht für harmlos, sondern seinen eigenen Beitrag für bedeutungslos. Auch die Behauptung, in großen Gruppen greife meist niemand mehr ein, trägt nicht: Der Zuschauereffekt beschreibt nur, dass die Wahrscheinlichkeit sinkt, dass eine einzelne Person hilft. In gefilmten Konflikten im öffentlichen Raum (219 Fälle in drei Ländern, Philpot u. a. 2020) griff in gut neun von zehn Fällen mindestens ein Umstehender ein. Und dass der Mechanismus nur bei Notfällen mit direkter Lebensgefahr auftrete, widerspricht dem Buch: Es nennt „Was kann ich als Einzelner schon tun?“ ausdrücklich als klassischen Gedanken der diffundierten Verantwortung bei großen gesellschaftlichen Problemen.","coreRule":"⚡ „Was kann ich als Einzelner schon tun?“ ist der Satz, mit dem Verantwortung verteilt wird und verschwindet.","beleg":"Werkstück E.2.3 (Anwendung & Relevanz: Bei großen gesellschaftlichen Problemen); Fn. gl-e-philpot (Philpot u. a. 2020, American Psychologist 75(1), S. 66–75)","status":"entwurf","scenario":"In einer Gesprächsrunde wird über die Klimakrise gesprochen. Ein Kollege winkt ab: „Es gibt so viele andere, was kann ich als Einzelner schon tun?“","quote":"","quoteLabel":"","kurz":"Wenn ein Problem riesig ist und viele betroffen sind, schrumpft das eigene Zuständigkeitsgefühl auf einen winzigen Anteil, und man denkt, andere werden es schon richten. Der Kollege hält die Krise nicht für harmlos, er hält nur seinen Beitrag für bedeutungslos.","prueffrage":"Ist in dem Satz von einem akuten Notfall die Rede, und was sagt der Kollege über die Gefahr selbst?","rueckmeldung":[{"option":0,"text":"Dass andere ruhig bleiben, kann tatsächlich dazu verleiten, eine Lage für harmlos zu halten. Der Kollege nennt die Krise aber nicht harmlos; er bezweifelt nur, dass sein eigener Beitrag etwas ausrichtet."},{"option":1,"text":"Hier steckt ein wahrer Kern: Mit der Zahl der Anwesenden sinkt die Chance, dass eine einzelne Person hilft. Daraus folgt aber nicht, dass überhaupt niemand mehr eingreift. In Studien zu realen Konflikten griff meist mindestens ein Umstehender ein."},{"option":2,"text":"Die klassischen Experimente dazu stellten tatsächlich Notfälle nach. Verteilte Verantwortung kann aber überall wirken, wo viele beteiligt sind und jeder denkt, die anderen kümmern sich, auch bei großen gesellschaftlichen Problemen wie dem Klima."}],"familie":"verantwortung-benennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Philpot, R.; Liebst, L. S.; Levine, M.; Bernasco, W.; Lindegaard, M. R. (2020): Would I Be Helped? Cross-National CCTV Footage Shows That Intervention Is the Norm in Public Conflicts. American Psychologist 75(1), S. 66–75 (Manuskriptfassung, Lancaster University)","oeffentlich":true,"doi":"10.1037/amp0000469","url":"https://eprints.lancs.ac.uk/id/eprint/134891/1/Would_I_be_Helped_Cross_National_CCTV_Footage_Shows_That_Intervention_Is_the_Norm_in_Public_Conflicts_Postprint.pdf","seite":"PDF-S. 2","abruf":"2026-10-12"},{"typ":"url","kurz":"Barleben, L.; O’Mahony, A. (2026): Bystander Effect. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter13.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"9e113021368ce587"}},{"id":"qx-e-021","clusterId":"E","werkstueckRef":"E.2.4","stufe":2,"question":"Mit welcher Planung sorgst du am ehesten dafür, dass die Aufmerksamkeit der Gruppe zur Tragweite der Themen passt?","scenario":"Du leitest die Budgetrunde deines Vereins. Auf der Tagesordnung stehen der Kauf eines neuen Vereinsheims für 400.000 Euro und die Farbe des Kaffeeautomaten für 300 Euro. Aus früheren Sitzungen weißt du: Über die Farbe des Automaten wird erfahrungsgemäß lange und hitzig gestritten, beim Vereinsheim herrscht meist Schweigen, und der Kauf wird nach wenigen Minuten abgenickt.","options":["Du gibst allen Tagesordnungspunkten gleich viel Zeit, damit sich kein Thema übergangen fühlt.","Du streichst die kleinen Themen aus der Tagesordnung und entscheidest sie allein, damit die Sitzung kürzer wird.","Du legst vorab für jeden Punkt ein festes Zeit-Budget fest, das sich an Kosten und Folgen des Themas orientiert.","Du lässt die Gruppe jedes Thema frei diskutieren, damit sich von selbst zeigt, welche Punkte wichtig sind."],"correctIndex":2,"explanation":"Das Muster beschrieb C. Northcote Parkinson 1957 als „Gesetz der Trivialität“, heute ist es auch als „Bikeshedding“ bekannt: Die Zeit, die eine Gruppe auf einen Punkt verwendet, verhält sich umgekehrt zur Summe, um die es geht. Ein Teil der Erklärung liegt bei den Menschen: Beim Kaffeeautomaten kann jeder mitreden und sich risikofrei einbringen, beim 400.000-Euro-Kauf schweigt man lieber, um sich nicht mit einer „dummen“ Frage zu blamieren. Ein vorab festgelegtes Zeit-Budget nach Kosten und Folgen lenkt die Aufmerksamkeit dorthin, wo viel auf dem Spiel steht. Gleiche Zeit für alle Punkte ignoriert die unterschiedliche Tragweite, denn 300 Euro und 400.000 Euro verdienen nicht gleich viel Aufmerksamkeit. Die kleinen Themen allein zu entscheiden spart zwar Zeit, löst aber das Problem nicht: Das Vereinsheim bekäme weiterhin zu wenig Aufmerksamkeit, und du nimmst dem Verein die Beteiligung. Eine freie Diskussion ohne Budget überlässt die Zeitverteilung genau den Kräften, die das Muster erzeugen: Bei einfachen Themen wird am meisten geredet, bei schwierigen am wenigsten.","coreRule":"⚡ Die Redezeit gehört dorthin, wo die Folgen liegen, nicht dorthin, wo jeder mitreden kann.","beleg":"Werkstück E.2.4 (Das Härten im Feuer: Aktivierungs-Frage und Schmiede-Übung)","status":"entwurf","kurz":"Ein vorab festgelegtes Zeit-Budget nach Kosten und Folgen lenkt die Aufmerksamkeit dorthin, wo viel auf dem Spiel steht. Ohne Planung zieht der Kaffeeautomat die Debatte an, weil jeder mitreden kann, während der 400.000-Euro-Kauf fast ohne Rückfragen durchgeht.","prueffrage":"Wie verteilte sich die Redezeit in früheren Sitzungen auf Automat und Vereinsheim, und ergab sich das von selbst oder nach Plan?","rueckmeldung":[{"option":0,"text":"Gleiche Zeit für alle klingt gerecht und niemand fühlt sich übergangen. Sie behandelt aber 300 Euro und 400.000 Euro gleich, obwohl der Kauf viel mehr Aufmerksamkeit verdient."},{"option":1,"text":"Die Sitzung würde kürzer, und das ist ein echter Vorteil. Das Vereinsheim bekäme aber weiterhin zu wenig Aufmerksamkeit, und der Verein wäre bei den kleinen Themen nicht mehr beteiligt."},{"option":3,"text":"Freie Diskussion wirkt offen und demokratisch. Sie überlässt die Zeit aber genau dem Muster, das hier das Problem ist: Über Einfaches wird am meisten geredet, über Schwieriges am wenigsten."}],"familie":"aufmerksamkeit-nach-folgen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Wikipedia: Law of triviality (Sekundärquelle)","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Law_of_triviality","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Parkinson, C. N. (1957): Parkinson's Law, and Other Studies in Administration. Boston: Houghton Mifflin, Kap. „High Finance, or The Point of Vanishing Interest“","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e2d4a7c4fdeb0f12"}},{"id":"qx-e-022","clusterId":"E","werkstueckRef":"E.2.4","stufe":3,"question":"Du leitest ein Team, das sich zwei Stunden lang über die Gestaltung des Firmenlogos auf den Kaffeetassen gestritten hat. Die Frage, ob ein Lieferant für 1,2 Millionen Euro beauftragt wird, hat die Runde dagegen in drei Minuten ohne Rückfragen durchgewunken. Gegen solche Detaildebatten ist an sich nichts einzuwenden. Woran erkennst du, dass die Diskussion hier ein echtes Problem geworden ist?","options":["Daran, dass überhaupt über Kleinigkeiten gesprochen wurde, denn jedes Detailgespräch lenkt zwangsläufig von wichtigeren Themen ab.","Daran, dass sich die Gruppe beim Logo irgendwann geeinigt hat, denn schnelle Einigkeit ist an sich schon ein Zeichen von Gruppendenken.","Daran, dass bei der Lieferantenfrage nur wenige Fachleute gesprochen haben, denn dann entscheidet ein kleiner Kreis über Wichtiges.","Daran, dass die Aufmerksamkeit völlig unproportional zur Bedeutung verteilt ist: Das Triviale bindet die Denkkraft der Gruppe, während das teure Risiko ungeprüft bleibt."],"correctIndex":3,"explanation":"Eine kurze Detaildebatte kann nützlich sein: Ein lösbares kleines Problem gibt der Gruppe ein schnelles Erfolgserlebnis, schafft Vertrauen und wärmt für schwierigere Themen auf. Schädlich wird es erst, wenn die Zeit nicht mehr im Verhältnis zur Tragweite der Themen steht. Dann ist die gemeinsame Denkkraft an Belangloses gebunden, während Entscheidungen mit hohen Kosten und möglichen Folgeschäden unbesehen durchgehen. Das Warnsignal ist also nicht, dass Details besprochen werden, sondern ein Missverhältnis: am hitzigsten bei den einfachen Themen, am ruhigsten bei den komplexen. Ob die Gruppe sich einigt oder ob Fachleute sprechen, sagt für sich noch nichts darüber aus, ob die Aufmerksamkeit richtig verteilt war.","coreRule":"⚡ Aufwärmen ist erlaubt – ein Problem wird es, wenn die Gruppe nie darüber hinauskommt.","beleg":"Werkstück E.2.4 (Das Adaptive Talent; Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Entscheidend ist das Verhältnis: zwei Stunden fürs Logo, drei Minuten ohne Rückfragen für 1,2 Millionen Euro. Eine Detaildebatte schadet erst, wenn sie die Denkkraft bindet, während das teure Risiko ungeprüft durchgeht.","prueffrage":"Was stünde auf dem Spiel, wenn das Tassenlogo misslingt, und was, wenn der falsche Lieferant den Auftrag bekommt?","rueckmeldung":[{"option":0,"text":"Detailgespräche können tatsächlich von Wichtigerem ablenken. „Jedes“ und „zwangsläufig“ tragen aber nicht: Eine kurze Debatte über Kleinigkeiten kann Vertrauen schaffen und die Gruppe für schwierigere Themen aufwärmen."},{"option":1,"text":"Schnelle Einigkeit kann manchmal ein Warnzeichen sein. Beim Logo ging es aber zwei Stunden hin und her, und eine Einigung sagt für sich noch nichts darüber, ob die Aufmerksamkeit richtig verteilt war."},{"option":2,"text":"Wenige Stimmen bei einer großen Entscheidung können ein Risiko sein. Ob Fachleute sprechen, sagt für sich aber wenig, denn auch sie können gründlich prüfen. Auffällig ist das Missverhältnis: zwei Stunden fürs Logo, drei Minuten für den Lieferanten."}],"familie":"aufmerksamkeit-nach-folgen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Wikipedia: Law of triviality (Sekundärquelle)","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Law_of_triviality","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Parkinson, C. N. (1957): Parkinson's Law, and Other Studies in Administration. Boston: Houghton Mifflin, Kap. „High Finance, or The Point of Vanishing Interest“","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"7ab056205f42fa34"}},{"id":"qx-e-023","clusterId":"E","werkstueckRef":"E.2.4","stufe":4,"question":"Du liest in einem Forum: Seit Tagen füllen Mitglieder Seite um Seite mit der Frage, ob ein gefilmter Lichtpunkt einen Bogen von 12 oder 15 Grad beschreibt. Ob die Theorie überhaupt mit der Physik vereinbar ist, fragt niemand. Welche Einordnung passt am besten zu dem, was du siehst?","options":["Die Gruppe verhandelt ausgiebig ein kleines, für alle greifbares Detail und umgeht damit die schwierige Frage, an der die ganze Theorie hängt.","Die Gruppe hat die physikalischen Widersprüche längst gründlich geprüft und gemeinsam als widerlegt verworfen, sodass nur noch Details offen sind.","Alle Mitglieder halten die Theorie privat für falsch, glauben aber, alle anderen glaubten sie, und schweigen deshalb zu den Widersprüchen.","Die Mitglieder gehen davon aus, dass andere die physikalischen Fragen schon geklärt haben, und vertrauen deshalb auf die Theorie."],"correctIndex":0,"explanation":"Hier verteilt sich die Aufmerksamkeit umgekehrt zur Bedeutung der Themen: Über das Detail kann jeder mitreden, es ist konkret, ungefährlich und bietet eine Bühne. Die physikalische Gesamtfrage ist anstrengend und riskant, denn wer sie stellt, könnte die eigene Unwissenheit preisgeben. Deshalb wird dort geschwiegen, wo es zählt. Die zweite Deutung scheitert, weil eine gründliche Prüfung irgendwo sichtbar sein müsste, im Beispiel aber gerade fehlt. Die dritte unterstellt, alle zweifelten privat; im Beispiel steht davon nichts, und das Verhalten wird durch die einfache Verteilung der Aufmerksamkeit besser erklärt. Die vierte unterstellt, andere hätten die Frage beantwortet, obwohl nirgends davon die Rede ist. Als nächsten Schritt kannst du fragen: Wie viel Diskussionszeit entfällt auf das Detail, und wie viel auf die Frage, ob das Ganze überhaupt stimmen kann?","coreRule":"⚡ Wer nur über Details streitet, die jeder versteht, umgeht oft gerade die Frage, an der alles hängt.","beleg":"Werkstück E.2.4 (Anwendung & Relevanz: In Verschwörungsgemeinschaften; Verbindungen)","status":"entwurf","scenario":"","kurz":"Über das Detail kann jeder mitreden, es ist konkret und ungefährlich. Die Frage, ob die Theorie überhaupt zur Physik passt, ist anstrengend und riskant, und genau dort, wo es zählt, wird geschwiegen. Aufmerksamkeit folgt hier der Bequemlichkeit, nicht der Bedeutung.","prueffrage":"Was müsste im Forum zu finden sein, wenn die physikalische Frage längst geklärt wäre, und findet es sich dort?","rueckmeldung":[{"option":1,"text":"Dass nur noch Details diskutiert werden, könnte nach abgeschlossener Prüfung aussehen. Eine solche Prüfung ist im Forum aber nirgends sichtbar, die Frage nach der Vereinbarkeit mit der Physik wird schlicht nicht gestellt."},{"option":2,"text":"Schweigen kann tatsächlich aus unausgesprochenem Zweifel entstehen. Für private Zweifel gibt es hier aber keinen Hinweis, und das Verhalten lässt sich schon dadurch erklären, dass das greifbare Detail leichter zu diskutieren ist."},{"option":3,"text":"Dass jemand glaubt, andere hätten die Sache längst geklärt, kommt in Gruppen vor. Hier ist es eine Zusatzannahme: Nichts deutet darauf hin, dass die Mitglieder so etwas annehmen oder dass jemand die physikalischen Fragen je beantwortet hätte."}],"familie":"aufmerksamkeit-nach-folgen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Wikipedia: Law of triviality (Sekundärquelle)","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Law_of_triviality","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Parkinson, C. N. (1957): Parkinson's Law, and Other Studies in Administration. Boston: Houghton Mifflin, Kap. „High Finance, or The Point of Vanishing Interest“","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"76123cc35accecad"}},{"id":"qx-e-024","clusterId":"E","werkstueckRef":"E.2.5","stufe":1,"question":"In einer Abteilung gilt seit Jahren die Regel, Entscheidungen erst nach drei Abstimmungsrunden zu treffen. Bei einer anonymen Umfrage stellt sich heraus: Fast alle halten die Regel privat für überflüssig, jeder dachte aber, die anderen fänden sie sinnvoll. Was beschreibt diese Lage am besten?","options":["Eine Mehrheit folgt öffentlich einer Norm, die sie privat ablehnt, weil sie fälschlich annimmt, die anderen stünden dahinter.","Eine kleine Minderheit setzt ihre Regel gegen eine Mehrheit durch, die sie offen und bewusst ablehnt.","Die Abteilung hat die Regel nach sorgfältiger Abwägung beibehalten, weil ihre Vorteile die Nachteile überwiegen.","Alle Beteiligten wissen genau, dass die Regel überflüssig ist, und täuschen einander absichtlich vor, sie sinnvoll zu finden."],"correctIndex":0,"explanation":"Typisch für diese Lage ist die Lücke zwischen privater Überzeugung und öffentlichem Verhalten. Jeder sieht nur das konforme Verhalten der anderen und deutet es fälschlich als deren echte Meinung. Das eigene Mitmachen wird dann von den anderen wiederum als Beleg gelesen, dass „alle“ die Regel stützen, und die Illusion verstärkt sich selbst. Anders als bei gewöhnlicher Konformität, wo sich eine Minderheit an eine tatsächliche Mehrheitsmeinung anpasst, passt sich hier eine Mehrheit an eine nur eingebildete Mehrheitsmeinung an. Die anonyme Umfrage ist das passende Prüfwerkzeug: Sie macht die privaten Überzeugungen sichtbar, die das öffentliche Schweigen verdeckt.","coreRule":"⚡ Wenn alle schweigen oder mitmachen, weißt du noch nicht, was sie denken. Prüfe die private Überzeugung, nicht nur das sichtbare Verhalten.","beleg":"Werkstück E.2.5 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"Eine Abteilung hält an einer umständlichen Abstimmungsregel fest. Niemand hat sie je offen kritisiert. Erst die anonyme Umfrage zeigt, dass fast alle sie ablehnen.","kurz":"Fast alle lehnen die Regel privat ab, folgen ihr aber öffentlich, weil jeder die anderen für überzeugt hält. Der Denkfehler: Konformes Verhalten wird als echte Meinung gedeutet, und das eigene Mitmachen bestätigt dann die anderen in ihrem Irrtum.","prueffrage":"Was wissen die Beteiligten über die tatsächliche Meinung der anderen, und woran würdest du das erkennen?","rueckmeldung":[{"option":1,"text":"Eine Minderheit, die ihre Regel gegen eine offene Mehrheit durchsetzt, wäre ein ganz anderes Bild. Hier lehnt niemand die Regel offen ab, und gerade die Mehrheit meint irrtümlich, die anderen stünden dahinter."},{"option":2,"text":"Eine bewusste Abwägung wäre ein plausibler Grund, eine Regel zu behalten. Die Umfrage zeigt aber, dass fast alle sie privat überflüssig finden. Beibehalten wurde sie also nicht aus Überzeugung, sondern aus dem Irrtum über die anderen."},{"option":3,"text":"Richtig ist, dass fast alle die Regel privat ablehnen und trotzdem mitmachen. Das Bild eines durchschauten Spiels, in dem alle voneinander wissen, passt aber nicht: Jeder hielt die anderen für überzeugt. Das Mitmachen beruhte auf einem Irrtum."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Schroeder, C. M.; Prentice, D. A. (1998): Exposing Pluralistic Ignorance to Reduce Alcohol Use Among College Students. Journal of Applied Social Psychology 28(23), S. 2150–2180 (Kopie Stanford SPARQ)","oeffentlich":true,"url":"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/schroeder_prentice_1998_-_exposing_pluralistic_ignorance.pdf","seite":"S. 2151–2153","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Prentice, D. A.; Miller, D. T. (1993): Pluralistic ignorance and alcohol use on campus. Journal of Personality and Social Psychology 64(2), S. 243–256","oeffentlich":false,"doi":"10.1037/0022-3514.64.2.243"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"688dbef00330e83b"}},{"id":"qx-e-025","clusterId":"E","werkstueckRef":"E.2.5","stufe":3,"question":"Eine Studie unter Studierenden eines Campus ergibt: Die meisten geben an, die dort üblichen Trinkgewohnheiten seien ihnen selbst eher unangenehm, vermuten das aber beim durchschnittlichen Kommilitonen nicht. Im Lauf eines Semesters nähern sich die befragten Männer in ihrer Haltung der vermuteten Norm an, die befragten Frauen nicht. Der Geschlechterunterschied war nicht vorhergesagt, die Auswertung beruht auf nur 50 telefonisch Befragten, und der Effekt ist statistisch knapp. Was ist die vernünftigste Schlussfolgerung?","options":["Der Befund spricht dafür, dass die Gruppe sich über die Haltung der anderen irrt; der Geschlechterunterschied ist dagegen nur vorläufig und braucht größere Stichproben.","Der Befund beweist, dass Männer grundsätzlich stärker unter Gruppendruck stehen als Frauen, denn der Unterschied zeigte sich im Lauf eines Semesters.","Der Befund ist wertlos, weil Studien mit 50 Personen nichts über Gruppenverhalten sagen und beide Teilergebnisse damit entfallen.","Der Befund zeigt, dass die Studierenden sich über ihre Gewohnheiten selbst belogen haben, denn Selbstauskünfte sind nie verlässlich."],"correctIndex":0,"explanation":"Zwei Teilbefunde tragen unterschiedlich viel. Dass Menschen die Haltung der anderen falsch einschätzen, zeigte sich in vier Studien derselben Arbeit: Die eigenen Werte streuten breit, die vermuteten Werte der anderen lagen dicht beieinander. Auch an einer anderen Universität fanden Suls und Green im Grundmuster dasselbe. Der Geschlechterunterschied im Semesterverlauf dagegen stammt aus einer kleinen Stichprobe, war nicht vorhergesagt und lag statistisch knapp an der Signifikanzgrenze. So etwas kann Zufall sein und braucht Bestätigung, bevor man daraus ein Gesetz über Männer und Frauen macht. Alles zu verwerfen, was eine kleine Studie zeigt, wäre ebenso voreilig wie zu verallgemeinern: Eine kleine Stichprobe schwächt die Sicherheit, sie macht den Befund nicht wertlos. Und Selbstauskünfte sind fehleranfällig, aber kein Beweis für Lüge; gerade dass Suls und Green das Grundmuster auch an einer anderen Universität fanden, stützt den Kernbefund.","coreRule":"⚡ Trenne gut gestützte Befunde von vorläufigen: Eine kleine Stichprobe und ein nicht vorhergesagter, knapper Unterschied verlangen Vorsicht, aber keine Verwerfung.","beleg":"Werkstück E.2.5 (Anwendung & Relevanz: Bei sozialen Normen); Fn. gl-e-prentice (Prentice & Miller 1993, S. 243–249; Vorbehalt S. 248 f.); Anmerkung anm-gl-e-prentice (Studie 1; Suls & Green 2003)","status":"entwurf","scenario":"","kurz":"Der Kernbefund, dass man die Haltung der anderen falsch einschätzt, ist breit gestützt. Der Geschlechterunterschied stammt aus einer kleinen Stichprobe, war nicht vorhergesagt und ist knapp: Das kann Zufall sein und braucht Bestätigung.","prueffrage":"Welche Schwächen nennt die Beschreibung der Studie, und betreffen sie jede ihrer Aussagen gleich stark?","rueckmeldung":[{"option":1,"text":"Dass sich der Unterschied erst im Semesterverlauf zeigte, wirkt wie eine echte Dynamik. Ein Beweis ist das nicht: Der Effekt ist knapp, beruht auf nur 50 Befragten und war nicht vorhergesagt; ein Gesetz über Männer und Frauen folgt daraus nicht."},{"option":2,"text":"Eine kleine Stichprobe macht Ergebnisse unsicherer, das stimmt. Sie macht sie aber nicht wertlos: Der Kernbefund stammt aus vier Studien und fand sich an einer anderen Universität im Grundmuster wieder. Verworfen wird hier zu viel."},{"option":3,"text":"Selbstauskünfte sind tatsächlich fehleranfällig, doch daraus folgt keine Lüge, und „nie verlässlich“ ist zu absolut. Es geht auch nicht um die eigene Haltung, sondern um die falsche Einschätzung der anderen, und die bestätigte sich auch anderswo."}],"familie":"wiederholung-abwarten","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Schroeder, C. M.; Prentice, D. A. (1998): Exposing Pluralistic Ignorance to Reduce Alcohol Use Among College Students. Journal of Applied Social Psychology 28(23), S. 2150–2180 (Kopie Stanford SPARQ)","oeffentlich":true,"url":"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/schroeder_prentice_1998_-_exposing_pluralistic_ignorance.pdf","seite":"S. 2152–2153","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Prentice, D. A.; Miller, D. T. (1993): Pluralistic ignorance and alcohol use on campus. Journal of Personality and Social Psychology 64(2), S. 243–256","oeffentlich":false,"doi":"10.1037/0022-3514.64.2.243"},{"typ":"literatur","kurz":"Suls, J.; Green, P. (2003): Pluralistic Ignorance and College Student Perceptions of Gender-Specific Alcohol Norms. Health Psychology 22(5), S. 479–486","oeffentlich":false,"doi":"10.1037/0278-6133.22.5.479"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"9dbbc1d4fbdae1d1"}},{"id":"qx-e-026","clusterId":"E","werkstueckRef":"E.2.5","stufe":2,"question":"Welches Vorgehen ist hier am sinnvollsten, um herauszufinden, ob wirklich alle anderen den Plan gut finden, ohne dich selbst zu sehr zu exponieren?","scenario":"Im Projektmeeting stellt dein Chef einen Plan vor, der deiner Ansicht nach ein klares Problem hat. Alle nicken, niemand sagt etwas. Du hältst dich für den Einzigen, der zweifelt und überlegst, was du tun sollst.","options":["Den Plan direkt und scharf kritisieren, damit sofort klar wird, dass Widerspruch in dieser Runde erlaubt ist.","Schweigend abwarten, bis jemand anderes widerspricht, denn das Schweigen zeigt, wie die anderen denken.","Per Handzeichen abstimmen lassen, damit die tatsächliche Haltung der Gruppe für alle sichtbar wird.","Deinen Zweifel als offene Frage stellen und beobachten, wie die anderen im Raum darauf reagieren."],"correctIndex":3,"explanation":"Nicken und Schweigen sind nur öffentliches Verhalten, sie verraten nicht, was die anderen privat denken. Vielleicht zweifeln mehrere und schweigen aus demselben Grund wie du: Jeder hält sich für den Einzigen. Eine offene Frage ist ein günstiger Test: Das Risiko bleibt klein, dein Zweifel kommt trotzdem auf den Tisch, und oft äußern daraufhin andere ihre Bedenken. Abwarten behandelt das Schweigen der anderen als Beweis ihrer Meinung, obwohl es genauso gut Unsicherheit und Angst vor Blamage ausdrücken kann. Eine offene Abstimmung lässt dieselbe Angst wirken, denn wer sich als Erster oder Einziger gegen den Chef stellt, geht ein großes Risiko ein. Der scharfe Angriff erhöht das Risiko für dich, ohne dass du vorher mehr über die Haltung der anderen weißt.","coreRule":"⚡ Schweigen ist kein Beweis für Zustimmung: Eine offene Frage prüft, was die anderen denken, ohne dass du gleich angreifen musst.","beleg":"Werkstück E.2.5 (Das Härten im Feuer: Der mutige Test; Aktivierungs-Frage)","status":"entwurf","kurz":"Nicken und Schweigen zeigen nur öffentliches Verhalten, nicht die private Meinung. Eine offene Frage testet billig, ob andere ähnlich zweifeln. Der Denkfehler wäre, das Schweigen der anderen schon als Zustimmung zu lesen.","prueffrage":"Was zeigt dir das Verhalten der anderen im Raum tatsächlich, und was kannst du daraus nicht ablesen?","rueckmeldung":[{"option":0,"text":"Ein scharfer Einwand bringt den Zweifel auf den Tisch und kann zeigen, dass Widerspruch erlaubt ist. Du setzt dich damit aber dem größten Risiko aus, bevor du weißt, ob andere ähnlich denken, und genau das wolltest du vermeiden."},{"option":1,"text":"Abwarten kostet dich nichts und wirkt deshalb vernünftig. Das Schweigen der anderen sagt aber wenig: Es kann Zustimmung sein, ebenso aber Unsicherheit oder Angst vor Blamage, und womöglich wartet jeder auf denselben Mut."},{"option":2,"text":"Eine Abstimmung macht Haltungen sichtbar und erscheint deshalb fair. Per Handzeichen wirkt aber dieselbe Angst: Wer sich als Erster oder Einziger gegen den Chef stellt, riskiert viel, und das Ergebnis spiegelt eher Vorsicht als echte Meinungen."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Schroeder, C. M.; Prentice, D. A. (1998): Exposing Pluralistic Ignorance to Reduce Alcohol Use Among College Students. Journal of Applied Social Psychology 28(23), S. 2150–2180 (Kopie Stanford SPARQ)","oeffentlich":true,"url":"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/schroeder_prentice_1998_-_exposing_pluralistic_ignorance.pdf","seite":"S. 2151–2153","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Prentice, D. A.; Miller, D. T. (1993): Pluralistic ignorance and alcohol use on campus. Journal of Personality and Social Psychology 64(2), S. 243–256","oeffentlich":false,"doi":"10.1037/0022-3514.64.2.243"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"05b755d1adcb79c4"}},{"id":"qx-e-027","clusterId":"E","werkstueckRef":"E.2.6","stufe":1,"question":"Ein Kind spielt gern mit einem Wellensittich. Eines Tages erschrickt es heftig, als genau dann ein Glas laut zerspringt. Nach mehreren ähnlichen Vorfällen weint das Kind schon beim bloßen Anblick des Vogels, noch bevor irgendein Geräusch zu hören ist. Wie lässt sich die Rolle des zerspringenden Glases am besten beschreiben?","options":["Es ist der Reiz, der von selbst Schreck auslöst, ohne dass das Kind etwas lernen musste; durch die Kopplung bekam der Vogel die Wirkung.","Es ist der anfangs neutrale Reiz, der erst durch die Kopplung mit dem Vogel seine Wirkung auf das Kind erhält.","Es ist der Reiz, auf den das Kind nach einigen Wiederholungen mit Angst reagiert, auch wenn nur der Vogel zu sehen ist.","Es ist die Belohnung dafür, dass das Kind den Vogel anfasst, und verstärkt dieses Verhalten bei Wiederholung."],"correctIndex":0,"explanation":"Ein Glas, das laut zerspringt, erschreckt von Natur aus; dafür muss das Kind nichts lernen. Der Vogel war zunächst neutral: Das Kind spielte gern mit ihm. Weil beides mehrfach zusammen auftrat, wurde der Vogel zum Auslöser der Angst, auch ohne Knall. Der Schreckreiz ist also der Auslöser, der von selbst wirkt, der Vogel dagegen der gelernte Auslöser. Eine Belohnung ist der Knall nicht: Er macht das Anfassen nicht wahrscheinlicher, er verknüpft den Vogel mit Angst. Wichtig für die Einschätzung: Ein einzelner Fall zeigt den Mechanismus, sagt aber nicht, ob die Angst dauerhaft bleibt oder sich wieder abschwächt.","coreRule":"⚡ Wenn ein neutraler Reiz oft genug mit einem Reiz gekoppelt wird, der von selbst eine Reaktion auslöst, löst der neutrale Reiz irgendwann allein diese Reaktion aus. Prüfe immer: Welcher Reiz wirkt von Anfang an, und welcher hat die Wirkung erst gelernt?","beleg":"Werkstück E.2.6 (Einstieg; Kernidee); Fn. gl-e-little-albert (Watson & Rayner 1920, S. 2–12). Szenario als Transfer des Albert-Experiments auf neue Situation (Kind, Vogel, Glas) gebaut; keine neuen Studien oder Zahlen.","status":"entwurf","scenario":"Ein Kind spielt gern mit einem Wellensittich. Wiederholt zerspringt im selben Moment ein Glas, das Kind erschrickt heftig. Nach einigen solchen Vorfällen weint es schon beim Anblick des Vogels, noch bevor irgendein Geräusch zu hören ist.","kurz":"Das Glas schreckt von selbst, ohne dass das Kind etwas lernen musste. Der Vogel war anfangs neutral und wurde erst durch das gemeinsame Auftreten zum Auslöser der Angst. Man verwechselt leicht, welcher Reiz von Anfang an wirkt und welcher erst gelernt wird.","prueffrage":"Wie reagierte das Kind auf den Vogel, bevor das erste Glas zersprang, und wie nach mehreren Vorfällen?","rueckmeldung":[{"option":1,"text":"Die Beschreibung passt zu einem Lernvorgang, trifft aber den Vogel: Er war anfangs neutral und gewann seine Wirkung erst durch die Kopplung. Das Glas dagegen erschreckt von Natur aus, dafür braucht es keine Verbindung."},{"option":2,"text":"Dass das Kind schon beim Anblick weint, stimmt und ist der Kern des Falls. Diese gelernte Reaktion hängt aber am Vogel, nicht am Glas: Der Knall erschreckt von Anfang an, auch ohne dass irgendetwas gelernt wurde."},{"option":3,"text":"Der Knall belohnt nichts, denn er macht das Anfassen nicht wahrscheinlicher. Er erschreckt das Kind und verknüpft dadurch den Vogel mit Angst; eine Verstärkung von Verhalten steht hier gar nicht im Mittelpunkt."}],"familie":"gefuehl-statt-argument","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Watson, J. B.; Rayner, R. (1920): Conditioned Emotional Reactions. Journal of Experimental Psychology 3(1), 1–14 (Volltext in Classics in the History of Psychology, York University)","oeffentlich":true,"doi":"10.1037/h0069608","url":"https://psychclassics.yorku.ca/Watson/emotion.htm","abruf":"2026-10-12"},{"typ":"url","kurz":"OpenStax (Rice University): Psychology 2e, Kap. 6.2 Classical Conditioning","oeffentlich":true,"url":"https://openstax.org/books/psychology-2e/pages/6-2-classical-conditioning","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"8a2839fd9b9d2241"}},{"id":"qx-e-028","clusterId":"E","werkstueckRef":"E.2.6","stufe":2,"question":"Welcher Mechanismus erklärt am besten, warum diese Werbung auch ohne ein einziges Sachargument wirken kann?","scenario":"In einem Spot sitzen lachende Freunde am Strand, ein Kind rennt jubelnd durch die Wellen, dazwischen taucht immer wieder dieselbe Limonadenflasche auf. Der Spot läuft wochenlang jeden Abend. Eine Kollegin sagt: „Dass mir die Limo sympathisch ist, liegt an ihrem Geschmack. Ich habe den Spot kaum beachtet.“","options":["Das Produkt wird wiederholt mit Reizen gekoppelt, die von selbst Freude auslösen, und löst irgendwann allein ein Wohlgefühl aus.","Die Zuschauer werden für das Zusehen belohnt, schauen den Spot deshalb immer öfter bis zum Ende an und bewerten das Produkt dadurch besser.","Der Spot baut eine frühere negative Verknüpfung mit dem Produkt Schritt für Schritt ab, bis das Produkt wieder neutral wirkt.","Die Zuschauer bewerten das Produkt nachträglich besser, weil sie es schon gekauft haben und diese Entscheidung vor sich rechtfertigen."],"correctIndex":0,"explanation":"Der Spot enthält kein Argument über die Limonade selbst. Er zeigt sie immer wieder zusammen mit Dingen, die von sich aus Freude auslösen: lachende Menschen, Sonne, ein jubelndes Kind. Nach genug Wiederholungen kann schon das Produkt allein ein angenehmes Gefühl auslösen, oft ohne dass man es bemerkt. Die anderen Erklärungen passen nicht: Es gibt keine Belohnung fürs Zusehen und keine ältere negative Verknüpfung, die abgebaut würde; und selbst wenn die Kollegin die Limo schon gekauft hat, erklärt eine nachträgliche Rechtfertigung des Kaufs nicht, wie ein Spot ohne jedes Argument Sympathie erzeugt. Dieselbe Technik funktioniert auch umgekehrt: Wer eine Person oder Gruppe wiederholt mit bedrohlicher Musik oder Angstbildern koppelt, kann Abneigung erzeugen.","coreRule":"⚡ Frag bei Werbung: Welcher Reiz soll hier welches Gefühl auf welches Produkt übertragen, und was wird dabei gar nicht argumentiert?","beleg":"Werkstück E.2.6 (Anwendung & Relevanz: In der Propaganda und Werbung; Schmiede-Übung)","status":"entwurf","kurz":"Der Spot sagt nichts über die Limonade, koppelt sie aber wiederholt mit Dingen, die von selbst Freude auslösen. So kann irgendwann schon die Flasche allein ein gutes Gefühl wecken, oft unbemerkt, auch wenn man es dem Geschmack zuschreibt.","prueffrage":"Was wüsstest du über diese Limonade, wenn du den Spot nur zusammenfasst, und was zeigt er stattdessen?","rueckmeldung":[{"option":1,"text":"Belohnung kann Verhalten tatsächlich verstärken. Im Spot wird aber nichts für das Zusehen belohnt, und von häufigerem Zuschauen ist keine Rede. Wirken kann er über das, was er immer wieder zusammen mit der Flasche zeigt."},{"option":2,"text":"Verknüpfungen lassen sich tatsächlich umlernen, auch ins Positive. Hier gibt es aber keine frühere negative Verbindung mit der Limonade, die abgebaut würde. Der Spot schafft eine positive erst neu."},{"option":3,"text":"Wer etwas gekauft hat, bewertet es oft nachträglich besser, um die Entscheidung zu stützen. Den Spot erklärt das aber nicht: Er bietet keine Argumente, sondern koppelt die Flasche mit Freude, und das kann auch ohne jeden Kauf wirken."}],"familie":"gefuehl-statt-argument","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"OpenStax (Rice University): Psychology 2e, Kap. 6.2 Classical Conditioning (Abschnitt zu Werbung)","oeffentlich":true,"url":"https://openstax.org/books/psychology-2e/pages/6-2-classical-conditioning","abruf":"2026-10-12"},{"typ":"url","kurz":"Hofmann, W.; De Houwer, J.; Perugini, M.; Baeyens, F.; Crombez, G. (2010): Evaluative conditioning in humans: a meta-analysis. Psychological Bulletin 136(3), 390–421 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1037/a0018916","url":"https://pubmed.ncbi.nlm.nih.gov/20438144/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"f577de5c34d3f839"}},{"id":"qx-e-029","clusterId":"E","werkstueckRef":"E.2.6","stufe":3,"question":"Welche Erklärung beschreibt seinen Lernprozess am sparsamsten?","options":["Sein Verhalten verändert sich, weil es Folgen hatte: Belohntes wird häufiger gezeigt, Bestraftes seltener.","Ein zuvor neutraler Reiz wurde wiederholt mit einem Reiz gekoppelt, der von sich aus eine Reaktion auslöst.","Eine zuvor erlernte Angst wurde durch wiederholte positive Erlebnisse im Forum schrittweise überschrieben.","Eine einmal erlernte Angst hat sich auf viele ähnliche Situationen im Forum ausgebreitet."],"correctIndex":0,"explanation":"Der Nutzer lernt aus den Konsequenzen seines eigenen Verhaltens: Anpassung bringt Zuspruch und Ränge (Belohnung), Abweichung bringt Ignorieren oder Tadel (Bestrafung). Das Muster heißt operante Konditionierung (Skinner). Bei der klassischen Konditionierung wird dagegen ein Reiz mit einem anderen gekoppelt, ohne dass das eigene Verhalten Folgen hätte, wie bei der Ratte und dem Lärm im Fall des „kleinen Albert“; hier gibt es weder einen solchen Auslöser noch eine Angst, die überschrieben wird oder sich ausbreitet. Entscheidend ist die Frage, ob das Verhalten selbst belohnt oder bestraft wird. Gruppen, die Abweichung bestrafen und Anpassung stark belohnen, können ihre Mitglieder so Schritt für Schritt auf Linie bringen, besonders wenn sie Zustimmung wie in einem Spiel mit Punkten und Rängen belohnen.","coreRule":"⚡ Klassisch lernt man Verknüpfungen von Reizen, operant lernt man aus den Folgen des eigenen Tuns.","beleg":"Werkstück E.2.6 (Kontext & Tiefe: Operante Konditionierung; Red Flags)","status":"entwurf","scenario":"Ein Forum vergibt Zuspruch und Ränge für Beiträge auf Gruppenlinie; abweichende Beiträge werden ignoriert oder getadelt. Ein Nutzer postet zweimal eine Meinung, die von der Linie abweicht, und wird beide Male ignoriert oder getadelt. Danach schreibt er nur noch Beiträge, die der Linie folgen und ihm Zuspruch und Ränge bringen.","quote":"","quoteLabel":"","kurz":"Der Nutzer lernt aus den Folgen seines eigenen Verhaltens: Anpassung bringt Zuspruch und Ränge, Abweichung bringt Ignorieren oder Tadel. Bei einer bloßen Reizkopplung hätte sein Handeln dagegen keine Folgen, hier entscheidet es über Belohnung und Strafe.","prueffrage":"Zeigt der Nutzer irgendwo Angst oder Rückzug, und was genau hat sich an seinen Beiträgen verändert?","rueckmeldung":[{"option":1,"text":"Zuspruch und Tadel kommen hier nicht von selbst, sondern erst nachdem er etwas geschrieben hat. Eine Kopplung zweier Reize, bei der das eigene Verhalten folgenlos bleibt, beschreibt das nicht: Sein Posten wird belohnt oder bestraft."},{"option":2,"text":"Positive Erlebnisse spielen tatsächlich eine Rolle, denn Zuspruch und Ränge belohnen sein Verhalten. Von einer früher erlernten Angst, die dabei überschrieben würde, ist aber nichts zu erkennen; es geht um die Folgen seines Postens."},{"option":3,"text":"Eine Angst, die sich auf ähnliche Situationen ausbreitet, würde eher zu Rückzug aus dem Forum führen. Der Nutzer schreibt aber gezielt angepasst weiter, und Anzeichen von Angst werden nirgends beschrieben."}],"familie":"gefuehl-statt-argument","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"OpenStax (Rice University): Psychology 2e, Kap. 6.3 Operant Conditioning","oeffentlich":true,"url":"https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning","abruf":"2026-10-12"},{"typ":"url","kurz":"Watson, J. B.; Rayner, R. (1920): Conditioned Emotional Reactions. Journal of Experimental Psychology 3(1), 1–14 (Volltext in Classics in the History of Psychology)","oeffentlich":true,"doi":"10.1037/h0069608","url":"https://psychclassics.yorku.ca/Watson/emotion.htm","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3cf93af47b96bf45"}},{"id":"qx-e-030","clusterId":"E","werkstueckRef":"E.2.6","stufe":4,"question":"Welche Erklärung für die Rückkehr der Angst ist die sparsamste?","options":["Die alte Angstverbindung wurde nie gelöscht, sondern nur von einer neuen, hemmenden Erfahrung überlagert; unter neuen Umständen und nach einem Schreck kann die Angst wieder durchbrechen.","Die Therapie war damals unvollständig, weil das Angstobjekt nur schrittweise gezeigt wurde, und muss nun in einer zweiten Runde von vorn und gründlicher wiederholt werden.","Die Angst vor Spinnen war nie erlernt, sondern angeboren; deshalb ließ sie sich durch Lernerfahrungen nur vorübergehend und scheinbar verändern.","Die neue Verknüpfung hatte die alte vollständig ersetzt; die Angst taucht nur auf, weil die Frau bewusst wieder an Spinnen gedacht und sich selbst hineingesteigert hat."],"correctIndex":0,"explanation":"Die Rückkehr der Angst an einem neuen Ort und nach einem Schreck passt dazu, dass Löschung eine Reaktion eher unterdrückt als beseitigt: Neben die ursprüngliche Verknüpfung tritt eine zweite, hemmende, und die erste bleibt im Hintergrund erhalten. Dass Angst nach einer Pause, bei einem Ortswechsel oder nach einem Schreck zurückkehren kann, ist gut beobachtet und stützt genau das. Die Annahme einer unvollständigen Therapie behauptet einen Fehler, den es nicht gegeben haben muss, und erklärt nicht, warum die Angst jahrelang weg war. Eine angeborene Angst erklärt nicht, warum sie gerade nach Umzug und Schreck zurückkehrt, und ein vollständiges Ersetzen widerspricht dem Rückfall selbst; das Hineinsteigern ist eine Zusatzannahme, für die nichts spricht. Das beschreibt einen Mechanismus und ist keine Behandlungsempfehlung für den Einzelfall.","coreRule":"⚡ Verlernen heißt meist Überlagern: Das alte Gelernte bleibt im Hintergrund erhalten. Wiederkehr nach Jahren ist deshalb kein Beweis für ein Scheitern.","beleg":"Werkstück E.2.6 (Die entscheidende Waffe: Gegenkonditionierung & Desensibilisierung); Fn. gl-e-exposition (Craske u. a. 2014, S. 10–23; Myers 2014, S. 296)","status":"entwurf","scenario":"Eine Frau hat ihre Spinnenphobie mit schrittweiser Konfrontation erfolgreich überwunden und blieb jahrelang symptomfrei. Nach einem Umzug in eine andere Stadt erschreckt sie eine Spinne im Treppenhaus, und die alte Panik ist plötzlich wieder da. Ihre Freundin meint: „Dann hat die Therapie damals eben nicht richtig gewirkt.“","quote":"","quoteLabel":"","kurz":"Eine Löschung unterdrückt die Angst eher, als sie zu beseitigen: Die alte Verknüpfung bleibt neben der neuen, hemmenden bestehen, und Schreck oder neuer Ort können sie wieder hervorbrechen lassen. Ein Therapiefehler muss dafür nicht vorliegen.","prueffrage":"Was ist über die Therapie und die Jahre danach tatsächlich bekannt, und was wird nur vermutet?","rueckmeldung":[{"option":1,"text":"Nach einem Rückfall nachzubessern, liegt nahe. Doch schrittweise Konfrontation ist ein übliches, wirksames Vorgehen, ein Therapiefehler ist nicht erkennbar, und warum die Angst jahrelang verschwunden war, bliebe unerklärt."},{"option":2,"text":"Spinnenangst ist so verbreitet, dass sie angeboren wirken kann. Das erklärt aber nicht, warum die Panik gerade nach Umzug und Schreck zurückkehrt; das passt zu einer Verknüpfung, die überlagert, aber nicht gelöscht wurde."},{"option":3,"text":"Vollständiges Ersetzen entspräche dem, was man sich von einer Therapie erhofft. Die Rückkehr der Angst spricht aber dafür, dass die alte Verknüpfung erhalten blieb, und bewusstes Hineinsteigern ist eine Zusatzannahme: Auslöser war ein Schreck."}],"familie":"gefuehl-statt-argument","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Craske, M. G.; Treanor, M.; Conway, C. C.; Zbozinek, T.; Vervliet, B. (2014): Maximizing exposure therapy: An inhibitory learning approach. Behaviour Research and Therapy 58, 10–23 (PMC-Volltext)","oeffentlich":true,"doi":"10.1016/j.brat.2014.04.006","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4114726/","abruf":"2026-10-12"},{"typ":"url","kurz":"OpenStax (Rice University): Psychology 2e, Kap. 6.2 Classical Conditioning (Extinction, Spontaneous Recovery)","oeffentlich":true,"url":"https://openstax.org/books/psychology-2e/pages/6-2-classical-conditioning","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"ca3397029b1a5c81"}},{"id":"qx-e-031","clusterId":"E","werkstueckRef":"E.2.7","stufe":1,"question":"Welche Deutung seines Verhaltens ist am besten begründet?","options":["Er war schon immer so, und die Beförderung hat nur sichtbar gemacht, was vorher verborgen war.","Verantwortung löscht bei jedem Menschen nach wenigen Monaten die Empathie aus, denn die Belege dafür sind eindeutig.","Die neue Position kann sein Verhalten mitverändert haben, sodass die Situation neben dem Charakter als Erklärung zählt.","Er hat sich bewusst für einen harten Führungsstil entschieden, weil Empathie in Führungsrollen als Schwäche gilt."],"correctIndex":2,"explanation":"Wer ein Verhalten sofort dem „wahren Charakter“ zuschreibt, übersieht leicht, was die Situation bewirkt (fundamentaler Attributionsfehler). Frank war früher zugänglich, und die Veränderung setzte nach der Beförderung ein; das macht die neue Rolle als Mitursache plausibel, beweist sie aber nicht. In Experimenten schnitten Menschen, die man sich mächtig fühlen ließ, bei der Perspektivübernahme schlechter ab, doch eines dieser Experimente (zur Einschätzung, was andere wissen) ließ sich in einer großen Wiederholung mit fast 3.000 Teilnehmenden nicht bestätigen. Dass Macht die Empathie bei jedem auslösche, geht deshalb weit über die dünne Befundlage hinaus, und für eine bewusste Entscheidung zu einem harten Führungsstil spricht in der Schilderung nichts. Am besten begründet ist die vorsichtige Annahme, dass die Situation das Verhalten begünstigen kann, die man mit weiteren Beobachtungen prüfen würde.","coreRule":"⚡ Bevor du Mächtige zum „bösen Charakter“ erklärst, frag, was die Situation aus ihnen macht, und bleib bei der Stärke der Belege vorsichtig.","beleg":"Werkstück E.2.7 (Kernidee; Kontext & Tiefe „Der Empathie-Kollaps“; Anti-Denkmuster); Fn. gl-e-macht-droge (Keltner 2016), gl-e-galinsky (Galinsky u. a. 2006; Ebersole u. a. 2016)","status":"entwurf","scenario":"Frank galt im Team lange als zugänglich und hörte anderen gut zu. Sechs Monate nach seiner Beförderung zum Abteilungsleiter fällt auf: Er unterbricht andere in Meetings, hört kaum noch zu und geht davon aus, dass seine Ideen die besten sind. Im Team heißt es: „Er hat sein wahres Gesicht gezeigt.“","kurz":"Das Verhalten zeigt sich erst seit der Beförderung. Dieser Zeitpunkt macht die neue Rolle als Mitursache plausibel, beweist sie aber nicht. „Wahrer Charakter“ greift als alleinige Erklärung zu kurz.","prueffrage":"Welche Beobachtungen über Frank stützen die Rede vom „wahren Gesicht“, und welche sprechen dagegen?","rueckmeldung":[{"option":0,"text":"Dass der Charakter mitspielt, ist denkbar. Als alleinige Erklärung passt es aber schlecht, denn das Verhalten zeigt sich erst seit der Beförderung, und die neue Rolle kann es mitgeprägt haben."},{"option":1,"text":"Experimente deuten tatsächlich auf schlechtere Perspektivübernahme bei Machtgefühl hin. „Bei jedem“, „löscht aus“ und „eindeutig“ gehen aber weit darüber hinaus: Die Befunde sprechen allenfalls von einem Dämpfen, und die Belege sind dünn."},{"option":3,"text":"Eine bewusste Entscheidung wäre möglich, doch nichts an seinem Verhalten deutet auf Planung oder ein solches Motiv hin. Die Aussage bleibt eine unbelegte Vermutung über seine Absichten."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"FORRT FLoRA Replication Atlas: Galinsky u. a. (2006), Power and Perspectives Not Taken – Replikation Many Labs 3 (Ebersole u. a. 2016), Ergebnis „failed“","oeffentlich":true,"url":"https://forrt.org/flora-replication-atlas/doi/10.1111/j.1467-9280.2006.01824.x/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Galinsky, A. D.; Magee, J. C.; Inesi, M. E.; Gruenfeld, D. H. (2006): Power and Perspectives Not Taken. Psychological Science 17(12), 1068–1074","oeffentlich":false,"doi":"10.1111/j.1467-9280.2006.01824.x"},{"typ":"url","kurz":"Pronin, E.; Gilovich, T.; Ross, L. (2004): Objectivity in the eye of the beholder: divergent perceptions of bias in self versus others. Psychological Review 111(3), 781–799 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1037/0033-295X.111.3.781","url":"https://pubmed.ncbi.nlm.nih.gov/15250784/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"dabc9a07d980f4f2"}},{"id":"qx-e-032","clusterId":"E","werkstueckRef":"E.2.7","stufe":3,"question":"Du liest in einem Artikel: „Studien beweisen, dass Macht Menschen rücksichtslos macht.“ Als Beleg wird eine Feldstudie genannt, in der Fahrer teurer Autos an Kreuzungen häufiger andere Fahrzeuge schnitten und Fußgängern häufiger die Vorfahrt nahmen als Fahrer günstiger Wagen. Was ist an diesem Beleg zu beachten?","options":["Gemessen wurde der Preis des Autos, also ein Anzeichen für soziale Schicht und nicht für Macht; zudem stützen direkte Wiederholungen den Befund nicht.","Gemessen wurde tatsächlich Macht, und der Befund gilt als gesichert, weil er auf realem Verhalten im Straßenverkehr beruht.","Gemessen wurde Macht, aber nur im Labor; die Beobachtungen mit den Autos stammen aus einer anderen, unabhängigen Untersuchung.","Gemessen wurde nichts Brauchbares, denn Verhalten im Straßenverkehr lässt sich grundsätzlich nicht wissenschaftlich untersuchen."],"correctIndex":0,"explanation":"Ein Beleg trägt eine Aussage nur, wenn er das misst, wovon die Aussage spricht. Das Auto ist hier ein Stellvertreter für soziale Schicht, und die Studie untersuchte nicht Macht, sondern soziale Schicht. Der Schluss von „Autopreis“ auf „Macht“ ist also ein Sprung. Dazu kommt: Die Feldstudie aus der Arbeitsgruppe um Dacher Keltner (Piff u. a., 2012) wurde 2023 in zwei direkten Wiederholungen nicht bestätigt. Ein Befund, der sich bei der Wiederholung nicht zeigt, ist ein wackliger Beleg. Zwei Fragen schützen vor solchen Fehlschlüssen: Was wurde tatsächlich gemessen, und hat sich das Ergebnis bei Wiederholung gezeigt?","coreRule":"⚡ Frag bei einer Studie: Was wurde wirklich gemessen, und wurde der Befund wiederholt?","beleg":"Werkstück E.2.7 (Kontext & Tiefe: Der Empathie-Kollaps); Fn. gl-e-keltner (Keltner 2016, S. 108 und 121–126; Piff u. a. 2012, PNAS 109(11), S. 4086–4091)","status":"entwurf","scenario":"Der Artikel zieht aus der Beobachtung den Schluss: „Wer Macht hat, verliert die Rücksicht auf andere.“","kurz":"Der Autopreis zeigt eher die soziale Schicht als Macht, der Schluss auf Macht ist also ein Sprung. Zudem zeigte sich der Befund in zwei direkten Wiederholungen nicht; er ist damit ein wackliger Beleg.","prueffrage":"Was genau haben die Forschenden an Autos und Fahrern festgehalten, und wurde die Beobachtung später noch einmal gemacht?","rueckmeldung":[{"option":1,"text":"Reales Verhalten zu beobachten ist ein Vorzug, belegt aber nicht, dass Macht gemessen wurde: Der Autopreis steht eher für die soziale Schicht. Auch „gesichert“ passt nicht, denn zwei direkte Wiederholungen bestätigten den Befund nicht."},{"option":2,"text":"Von einem Laborteil oder einer zweiten, unabhängigen Untersuchung ist hier nicht die Rede, es geht allein um die Feldstudie mit den Autos. Und diese erfasst nicht Macht, sondern über den Autopreis die soziale Schicht."},{"option":3,"text":"Feldbeobachtungen im Straßenverkehr sind eine übliche Forschungsmethode, daran liegt es nicht. Wacklig ist der Beleg, weil mit dem Autopreis die soziale Schicht statt Macht gemessen wurde und Wiederholungen den Befund nicht bestätigten."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Piff, P. K.; Stancato, D. M.; Côté, S.; Mendoza-Denton, R.; Keltner, D. (2012): Higher social class predicts increased unethical behavior. PNAS 109(11), 4086–4091 (PMC-Volltext)","oeffentlich":true,"doi":"10.1073/pnas.1118373109","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3306667/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Jung, M. H. u. a. (2023): Social status and unethical behavior: Two replications of the field studies in Piff et al. (2012). Journal of Experimental Psychology: General 152(5), 1368–1378","oeffentlich":false,"doi":"10.1037/xge0001333"},{"typ":"daten","kurz":"Universiteit van Amsterdam: Datensatz „Social status and unethical behavior: Two replications of the field studies in Piff et al. (2012)“ (mit Abstract)","oeffentlich":true,"doi":"10.21942/uva.24894654.v1","url":"https://dare.uva.nl/id/34307082-e88d-44ba-ad4d-340a45489827","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"2dadde159a8673f8"}},{"id":"qx-e-033","clusterId":"E","werkstueckRef":"E.2.7","stufe":4,"question":"Ein Ratgeber behauptet: „Macht wirkt im Gehirn wie Kokain – das ist gemessen.“ Als Beleg zitiert er einen Psychologen, der Macht „a dopamine high“ nennt. Wie beurteilst du die Behauptung?","options":["Die Behauptung ist belegt: Wer ein Machtgefühl erlebt, schüttet messbar Dopamin aus wie bei Kokain, das Zitat bestätigt das.","Das Zitat zeigt nur, dass jemand den Vergleich formuliert hat; dass Dopamin bei Machtgefühl tatsächlich gemessen wurde, zeigt es nicht.","Die Behauptung ist widerlegt: Macht hinterlässt im Gehirn keine messbaren Spuren und kann deshalb nichts bewirken.","Die Behauptung stimmt für Suchtverhalten, nicht aber für Empathieverlust, den eine Wiederholungsstudie widerlegt hat."],"correctIndex":1,"explanation":"Ein Zitat, in dem ein Fachmann einen bildhaften Vergleich zieht („a dopamine high“), ist keine Messung. Der zitierte Psychologe (Dacher Keltner, 2016) nennt in seinem Buch „The Power Paradox“ keine Studie, die Dopamin bei Machtgefühl gemessen hätte; der Satz „das ist gemessen“ ist deshalb unbelegt. Unbelegt heißt aber nicht widerlegt, und zwischen beidem liegt ein großer Unterschied. Andere Wirkungen, die Macht zugeschrieben werden, etwa gedämpfte Empathie oder mehr Risikobereitschaft, werden getrennt erforscht; auch dort sind die Belege dünner, als der griffige Vergleich nahelegt, und einzelne Experimente ließen sich in großen Wiederholungen nicht bestätigen. Richtig ist die vorsichtige Lesart: eine griffige These mit dünner Datenbasis.","coreRule":"⚡ Ein griffiger Vergleich ist noch kein Messergebnis.","beleg":"Werkstück E.2.7 (Kernidee); Fn. gl-e-macht-droge (Keltner 2016, Einleitung S. 7, Kap. 1 S. 40, Kap. 4 S. 117)","status":"entwurf","scenario":"","kurz":"Ein Fachmann, der Macht „a dopamine high“ nennt, zieht einen bildhaften Vergleich; gemessen wurde dabei nichts. „Das ist gemessen“ ist also unbelegt, aber nicht widerlegt: Es ist eine griffige These mit dünner Datenbasis.","prueffrage":"Welche Angaben zu Versuchspersonen, Messverfahren oder Messwerten enthält der Beleg des Ratgebers?","rueckmeldung":[{"option":0,"text":"Dass ein Fachmann den Vergleich zieht, stimmt. Seine Formulierung ist aber ein Bild und keine Messung, und die zitierte Quelle nennt keine Studie, die Dopamin bei Machtgefühl erfasst hätte."},{"option":2,"text":"Dass ein Beleg fehlt, trifft zu. Daraus folgt aber keine Widerlegung: Fehlende Messung heißt nicht, dass Macht nichts bewirkt. Unbelegt und widerlegt sind zwei verschiedene Aussagen."},{"option":3,"text":"Einzelne Experimente ließen sich in großen Wiederholungen tatsächlich nicht bestätigen. Das ist aber keine Widerlegung, und für den Suchtvergleich fehlt der Beleg ebenso. Die Belege sind insgesamt nur dünn."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"literatur","kurz":"Keltner, D. (2016): The Power Paradox: How We Gain and Lose Influence. New York: Penguin Press","oeffentlich":false,"seite":"7"},{"typ":"url","kurz":"FORRT FLoRA Replication Atlas: Galinsky u. a. (2006), Power and Perspectives Not Taken – Replikation Many Labs 3, Ergebnis „failed“","oeffentlich":true,"url":"https://forrt.org/flora-replication-atlas/doi/10.1111/j.1467-9280.2006.01824.x/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"dea83d1df7106a91"}},{"id":"qx-e-034","clusterId":"E","werkstueckRef":"E.2.7","stufe":2,"question":"In einer Zeitung steht: „Neurowissenschaftler haben bewiesen: Macht schaltet die Spiegelneuronen aus, Mächtige können das Leid anderer nicht mehr nachempfinden.“ Die zugrunde liegende Studie hat mit Magnetstimulation am Kopf gemessen, wie stark Muskeln beim Betrachten fremder Handbewegungen unwillkürlich „mitschwingen“. Wer sich mächtig fühlen sollte, zeigte eine schwächere Reaktion. Welche Übertreibung der Schlagzeile betrifft die Messebene selbst?","options":["Sie macht aus einem indirekten Muskelmaß den Beweis für abgeschaltete Nervenzellen, obwohl keine einzelne Nervenzelle untersucht wurde.","Sie macht aus einem Laborbefund eine Aussage über alle Mächtigen im Alltag, obwohl nur kurz mächtig gestimmte Teilnehmer untersucht wurden.","Sie macht aus einer einzelnen Studie einen Beweis, obwohl ein einzelner Befund erst durch Wiederholungen belastbar wird.","Sie macht aus einem Gruppenunterschied eine Wirkung der Macht, obwohl ganz andere Faktoren den Unterschied erklären könnten."],"correctIndex":0,"explanation":"Gemessen wurden Muskelantworten als indirektes Maß für das menschliche Spiegelsystem, keine einzelnen Nervenzellen. Daraus lässt sich allenfalls ein Hinweis auf geringere automatische Anteilnahme ableiten, kein Nachweis „abgeschalteter Spiegelneuronen“; einzelne Nervenzellen mit Spiegeleigenschaften wurden beim Menschen nur in einer anderen Studie mit implantierten Elektroden abgeleitet. Die übrigen Einwände treffen andere Schwächen: Die Übertragung vom Labor auf alle Mächtigen im Alltag betrifft die Verallgemeinerung, dass eine einzelne Studie noch kein Beweis ist, betrifft die Belegstärke, und der Einwand mit den „ganz anderen Faktoren“ betrifft die Ursache des Unterschieds; zudem wurde das Machtgefühl im Versuch gezielt erzeugt. Bei der Messebene selbst verspricht die Schlagzeile also etwas, das die Messung nicht hergibt: abgeschaltete Nervenzellen.","coreRule":"⚡ Ein indirektes Maß ist ein Hinweis, kein Beweis – und eine Schlagzeile darf nicht weiter reichen als das, was gemessen wurde.","beleg":"Werkstück E.2.7 (Kontext & Tiefe: Verringerte neuronale Resonanz); Fn. gl-e-hogeveen (Hogeveen u. a. 2014, S. 755–762; Mukamel u. a. 2010)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Gemessen wurde nur, wie stark Muskeln mitschwingen, also ein indirektes Maß, keine einzelne Nervenzelle. Daraus folgt allenfalls ein Hinweis auf geringere automatische Anteilnahme, nicht der Beweis „abgeschalteter Spiegelneuronen“.","prueffrage":"Wer wurde in der Studie untersucht, und wie wurde die Reaktion der Teilnehmenden erfasst?","rueckmeldung":[{"option":1,"text":"Der Einwand trifft eine echte Schwäche: Kurz mächtig gestimmte Teilnehmer sind kein Querschnitt aller Mächtigen. Diese Schwäche betrifft aber die Verallgemeinerung vom Labor auf den Alltag, nicht das, was die Messung selbst hergibt."},{"option":2,"text":"Dass eine einzelne Studie noch kein Beweis ist, stimmt, und „bewiesen“ ist tatsächlich zu stark. Das betrifft aber die Belegstärke, nicht die Messebene: Dort wird aus einem indirekten Muskelmaß ein Befund über abgeschaltete Nervenzellen."},{"option":3,"text":"Bei Gruppenvergleichen ist der Gedanke an andere Faktoren oft berechtigt. Hier wurde das Machtgefühl aber gezielt im Versuch erzeugt. Vor allem betrifft der Einwand die Ursache des Unterschieds, nicht das, was die Messung selbst hergibt."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Hogeveen, J.; Inzlicht, M.; Obhi, S. S. (2014): Power changes how the brain responds to others. Journal of Experimental Psychology: General 143(2), 755–762 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1037/a0033477","url":"https://pubmed.ncbi.nlm.nih.gov/23815455/","abruf":"2026-10-12"},{"typ":"url","kurz":"Mukamel, R.; Ekstrom, A. D.; Kaplan, J.; Iacoboni, M.; Fried, I. (2010): Single-neuron responses in humans during execution and observation of actions. Current Biology 20(8), 750–756 (PMC-Volltext)","oeffentlich":true,"doi":"10.1016/j.cub.2010.02.045","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2904852/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"45a31c0954a94a15"}},{"id":"qx-e-035","clusterId":"E","werkstueckRef":"E.3.1","stufe":1,"question":"Was unterscheidet die Aussage des Politikers von der Zeitungsmeldung?","options":["Der Politiker ordnet das Ereignis in eine Geschichte mit Opfern, Gegnern und Retter ein und gibt ihm so eine Bedeutung, die die Fakten allein nicht liefern.","Der Politiker hält sich eng an die geprüften Tatsachen, während die Zeitung das Ereignis bewusst verzerrt, um Leser zu beeinflussen.","Der Politiker fasst die Lage wie ein wissenschaftliches Modell zusammen, das sich bei neuen Daten laufend anpassen und überprüfen lässt.","Der Politiker erfindet das Ereignis, um Wähler zu täuschen, während die Zeitung die Wahrheit ohne jede Einordnung wiedergibt."],"correctIndex":0,"explanation":"Die Meldung nennt ein Ereignis: 300 Entlassungen. Der Politiker fügt eine Deutung hinzu, mit Tätern („skrupellose Manager“), Opfern („die einfachen Leute“) und einem Retter („nur wir“). Das ist ein Narrativ: eine Geschichte, die Ereignisse in einen Ursache-Wirkungs-Zusammenhang mit Helden, Gegnern und Moral bringt, ihnen so Bedeutung verleiht und oft gleich eine Handlungsanweisung mitliefert. Die Entlassungen sind real, die Rollenverteilung ist eine Zutat der Geschichte. Deshalb lohnt die Frage, welche anderen Geschichten dieselben Fakten erklären könnten und welche Fakten diese Geschichte auslässt.","coreRule":"⚡ Fakten sagen, was geschah; ein Narrativ sagt, was es bedeutet. Prüfe deshalb immer, welche Deutung zu den Fakten hinzugefügt wurde und welche anderen möglich wären.","beleg":"Werkstück E.3.1 (Kernidee: Definition Narrativ; Kontext & Tiefe: Beispiel Fakt vs. Narrativ)","status":"entwurf","scenario":"Eine Tageszeitung meldet: „Ein Konzern entlässt 300 Beschäftigte.“ Ein Politiker sagt dazu im Wahlkampf: „Wieder opfern skrupellose Manager die einfachen Leute für ihren Profit, und nur wir stellen uns schützend vor sie.“","quote":"","quoteLabel":"","kurz":"Die Meldung nennt nur das Ereignis, der Politiker erzählt dazu eine Geschichte mit Tätern, Opfern und einem Retter. Die Entlassungen sind real, die Rollenverteilung kommt erst durch die Deutung hinzu und wird leicht mit der Tatsache verwechselt.","prueffrage":"Welcher Teil der Reaktion lässt sich in der Meldung wiederfinden, und welcher kommt erst von dem, der spricht?","rueckmeldung":[{"option":1,"text":"Dass der Politiker bei den Fakten bleibt, wirkt plausibel, weil das Ereignis stimmt. Doch „skrupellos“, „opfern“ und „nur wir“ sind Wertung und Rollenverteilung, und für eine Verzerrung durch die knappe Meldung gibt es keinen Anhaltspunkt."},{"option":2,"text":"Auch ein Modell deutet Daten, deshalb klingt der Vergleich nicht abwegig. Ein Modell lässt sich aber an Daten überprüfen und anpassen. Die Aussage des Politikers legt dagegen Gut und Böse fest und fordert zum Handeln auf."},{"option":3,"text":"Wahlkampfreden wird schnell Täuschung unterstellt. Hier sind die 300 Entlassungen aber real: Erfunden ist nichts, hinzugefügt wird die Deutung. Ob die Zeitung ganz ohne Einordnung berichtet, lässt sich aus einer Zeile ohnehin nicht sagen."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dahlstrom, M. F. (2014): Using narratives and storytelling to communicate science with nonexpert audiences. PNAS 111(Suppl. 4) (PMC-Volltext)","oeffentlich":true,"doi":"10.1073/pnas.1320645111","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4183170/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"a463097e22d39da9"}},{"id":"qx-e-036","clusterId":"E","werkstueckRef":"E.3.1","stufe":2,"question":"Ein Kollege wendet ein: „Das ist doch Verschwendung. Wer Schuhe verkaufen will, sollte zeigen, was die Schuhe können.“ Wie lässt sich die Strategie der Marke am besten erklären?","scenario":"Du siehst einen Spot nach dem anderen für eine Sportmarke: Läufer im Morgengrauen, ein Mädchen, das nicht aufgibt, am Ende ein Logo. Von den Schuhen erfährst du fast nichts.","options":["Die Marke verkauft eine Geschichte vom Menschen, der über sich hinauswächst. Wer die Schuhe kauft, kann sich als Teil dieser Geschichte fühlen.","Die Marke setzt auf Sachinformation zu Material und Preis, weil Menschen Produkte vor allem nach rationalen Kriterien auswählen.","Die Marke spricht das langsame, logische Denken an, weil lange Argumentationsketten Käufer nachhaltiger binden als Geschichten.","Die Marke lenkt Käufer mit unwichtigen Details ab, damit sie das Wesentliche am Produkt übersehen und trotzdem kaufen."],"correctIndex":0,"explanation":"Der Spot erzählt, was die Marke bedeuten soll: Held, Hindernis, Überwindung. Das ist ein Narrativ, und Narrative sind weit einprägsamer und motivierender als abstrakte Sachinformationen. Käufer erwerben dann nicht nur ein Produkt, sondern die Zugehörigkeit zu einer Geschichte. Dass kaum Schuhe zu sehen sind, ist deshalb kein Fehler, sondern Absicht. Die Sachinformation-These erklärt den Spot nicht, denn es kommen weder Material noch Preis vor. Dass gerade lange Argumentationsketten stärker binden als Geschichten, ist nicht plausibel, und der Spot enthält auch keine solche Kette. Und von unwichtigen Details lenkt der Spot nicht ab, denn er zeigt gar keine Details, sondern eine geschlossene Erzählung. Ein Test für solche Fälle: Frag, welche Geschichte ein Produkt mitverkauft und wer darin der Held ist.","coreRule":"⚡ Wer fragt, welche Geschichte ein Produkt mitverkauft, durchschaut die Werbung besser.","beleg":"Werkstück E.3.1 (Anwendung & Relevanz: Im Marketing)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Der Spot erzählt, was die Marke bedeuten soll: Held, Hindernis, Überwindung. Solche Geschichten prägen sich besser ein als Sachinformationen, und wer kauft, erwirbt auch die Zugehörigkeit dazu. Dass kaum Schuhe zu sehen sind, ist Absicht.","prueffrage":"Was genau bekommst du in diesen Spots zu sehen und zu hören, und was davon ließe sich in einer Produktbeschreibung wiederfinden?","rueckmeldung":[{"option":1,"text":"Manche Käufer entscheiden tatsächlich nach Material und Preis. Die Spots erklärt das aber nicht: Von Material und Preis ist darin keine Rede, über die Schuhe erfährt man fast nichts."},{"option":2,"text":"Argumente können überzeugen, das ist unbestritten. Im Spot gibt es aber gar keine Argumentationskette, und dass Ketten stärker binden als Geschichten, ist nicht plausibel."},{"option":3,"text":"Werbung lenkt mitunter tatsächlich ab. Hier passt das nicht: Der Spot zeigt keine Details, sondern eine geschlossene Erzählung, und eine Täuschungsabsicht lässt sich daraus nicht ableiten."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Mar, R. A.; Li, J.; Nguyen, A. T. P.; Ta, C. P. (2021): Memory and comprehension of narrative versus expository texts: A meta-analysis. Psychonomic Bulletin & Review 28(3), 732–749 (PMC-Volltext)","oeffentlich":true,"doi":"10.3758/s13423-020-01853-1","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8219577/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dahlstrom, M. F. (2014): Using narratives and storytelling to communicate science with nonexpert audiences. PNAS 111(Suppl. 4) (PMC-Volltext)","oeffentlich":true,"doi":"10.1073/pnas.1320645111","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4183170/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"50912ef0eee8e3bf"}},{"id":"qx-e-037","clusterId":"E","werkstueckRef":"E.3.1","stufe":3,"question":"Welche Beobachtung zeigt am deutlichsten, dass eine Geschichte nicht mehr der Deutung der Wirklichkeit dient, sondern sie ersetzt?","options":["Die Geschichte kennt Helden und Gegner, denn jede Erzählung mit klarem Gut und Böse ist schon für sich eine Manipulation.","Belegte Gegenbeispiele werden nicht geprüft, sondern als Angriff abgetan, denn die Treue zur Geschichte zählt dort mehr als die Treue zu den Tatsachen.","Die Geschichte erreicht nur eine Gruppe und keine anderen Kulturen, denn dann fehlt ihr die gemeinsame Basis für Zusammenarbeit.","Die Geschichte malt ein Bild der Zukunft aus, denn jede Vision einer besseren Zukunft dient vor allem der Täuschung der Gläubigen."],"correctIndex":1,"explanation":"Eine Geschichte ist zunächst ein Werkzeug: Sie ordnet Ereignisse zu einem Zusammenhang, stiftet Sinn und ermöglicht Zusammenarbeit zwischen Menschen, die sich nicht kennen. Das ist nützlich und kein Fehler. Gefährlich wird sie, wenn sie die Wirklichkeit nicht mehr deutet, sondern ersetzt: Dann gelten Tatsachen, die nicht ins Bild passen, als feindliche Propaganda und werden nicht mehr geprüft. Das Merkmal ist also der Umgang mit widersprechenden Belegen. Klare Rollen von Held und Gegner kommen in fast jeder wirksamen Geschichte vor, auch in harmlosen, und sind höchstens ein Warnsignal, aber noch kein Beweis. Dass eine Geschichte nur eine Gruppe erreicht, sagt über ihren Wahrheitsgehalt nichts. Und eine Zukunftsvision gehört zu jeder erfolgreichen Geschichte und macht sie nicht schon zur Täuschung.","coreRule":"⚡ Eine Geschichte wird gefährlich, wenn sie die Wahrheit nicht mehr deutet, sondern ersetzt.","beleg":"Werkstück E.3.1 (Der Kipppunkt; Red Flags; Kontext & Tiefe)","status":"entwurf","scenario":"Eine Bewegung erzählt ihren Anhängern eine Geschichte von einem Kampf zwischen „dem Volk“ und „den Eliten“. Die Geschichte erklärt für die Mitglieder Vergangenheit, Gegenwart und Zukunft. Du beobachtest vier Dinge an dieser Bewegung.","kurz":"Entscheidend ist, wie eine Geschichte mit widersprechenden Belegen umgeht. Wird Unpassendes nur noch als Angriff abgetan, ersetzt sie die Wirklichkeit. Helden, Gegner und Zukunftsbilder haben dagegen fast alle wirksamen Geschichten.","prueffrage":"Welche der beobachteten Eigenschaften hätte auch ein harmloses Märchen, und welche nicht?","rueckmeldung":[{"option":0,"text":"Helden und Gegner kommen in fast jeder wirksamen Geschichte vor, auch in harmlosen, etwa in Märchen oder Sportberichten. Klare Rollen können höchstens ein Warnsignal sein, belegen aber noch keine Manipulation."},{"option":2,"text":"Eine Geschichte, die nur eine Gruppe verbindet, kann dennoch stimmen oder nicht stimmen. Die Reichweite sagt nichts darüber, ob sie die Wirklichkeit deutet oder ersetzt."},{"option":3,"text":"Zukunftsbilder gehören zu fast jeder erfolgreichen Geschichte, auch zu ehrlichen. Dass sie Hoffnung wecken, macht sie noch nicht zur Täuschung; entscheidend ist, wie die Geschichte mit Widersprüchen zur Wirklichkeit umgeht."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Smith, D. u. a. (2017): Cooperation and the evolution of hunter-gatherer storytelling. Nature Communications 8, 1853 (PMC-Volltext)","oeffentlich":true,"doi":"10.1038/s41467-017-02036-8","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5717173/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dahlstrom, M. F. (2014): Using narratives and storytelling to communicate science with nonexpert audiences. PNAS 111(Suppl. 4) (PMC-Volltext)","oeffentlich":true,"doi":"10.1073/pnas.1320645111","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4183170/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Harari, Y. N. (2013): Eine kurze Geschichte der Menschheit (Sapiens). München: DVA","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"e7c49f948981d7fc"}},{"id":"qx-e-038","clusterId":"E","werkstueckRef":"E.3.1","stufe":4,"question":"Du liest in einem populären Geschichtsbuch: „Vor genau 70.000 Jahren löste eine plötzliche kognitive Revolution die Fähigkeit des Menschen aus, an gemeinsame Geschichten zu glauben, und erklärt damit alles Spätere.“ Welche Rückfrage prüft diese Aussage am besten?","options":["Gibt es Funde, die symbolisches Verhalten schon deutlich vor 70.000 Jahren zeigen und eher für eine allmähliche Entwicklung sprechen?","Hat sich das Buch besonders gut verkauft und halten deshalb viele Menschen die Aussage für richtig?","Ist die Jahreszahl 70.000 nicht exakt belegbar und spielten gemeinsame Geschichten dann keine Rolle?","Wurde das Buch für ein breites Publikum geschrieben und ist die Aussage deshalb vermutlich falsch?"],"correctIndex":0,"explanation":"Eine Behauptung mit einer genauen Zahl und einem „plötzlichen“ Wendepunkt lässt sich an Befunden prüfen. Hier gibt es Hinweise dagegen: Die Archäologinnen Sally McBrearty und Alison Brooks argumentieren für eine allmähliche Entwicklung symbolischen Verhaltens, und Funde aus der Höhle von Blombos in Südafrika werden auf 75.000 bis 100.000 Jahre datiert. Die Rückfrage nach früheren Funden prüft also genau den Punkt, an dem die Aussage angreifbar ist. Verkaufszahlen und Reichweite sagen nichts über die Richtigkeit, und dass ein Werk ein breites Publikum anspricht, macht es noch nicht falsch. Auch eine umstrittene Jahreszahl widerlegt nicht den Kerngedanken, dass gemeinsame Geschichten Kooperation unter Fremden ermöglichen; dieser hängt nicht an der genauen Zahl.","coreRule":"⚡ Prüfe bei einer eingängigen Zahl in einer großen Erzählung, ob Befunde dagegensprechen. Eine umstrittene Zahl entwertet nicht automatisch den Kerngedanken.","beleg":"Werkstück E.3.1 (Kontext & Tiefe); Fn. gl-e-harari (Harari 2011/2013; McBrearty & Brooks; Blombos)","status":"entwurf","scenario":"Ein Bekannter hält eine Aussage aus einem populären Geschichtsbuch für die Erklärung unserer ganzen Kultur. Du willst herausfinden, wie belastbar diese Aussage ist.","kurz":"Eine genaue Zahl und ein „plötzlicher“ Wendepunkt lassen sich an Funden prüfen. Findet sich symbolisches Verhalten deutlich früher, spricht das gegen den Umbruch. Beliebtheit eines Buchs dagegen sagt nichts über seine Richtigkeit.","prueffrage":"Welche Wörter machen den Satz besonders angreifbar, und womit ließe sich jedes davon überprüfen?","rueckmeldung":[{"option":1,"text":"Dass sich ein Buch gut verkauft, gibt der Aussage einen Anschein von Gewicht. Verkaufszahlen und Reichweite sagen aber nichts darüber, ob sie stimmt; viele Leserinnen und Leser können sich ebenso irren."},{"option":2,"text":"Eine genaue Jahreszahl lässt sich tatsächlich kaum belegen. Selbst eine umstrittene Zahl widerlegt aber nicht den Gedanken, dass gemeinsame Geschichten Zusammenarbeit unter Fremden ermöglichen; der hängt nicht an der Zahl."},{"option":3,"text":"Populäre Bücher vereinfachen manchmal, deshalb ist Nachprüfen sinnvoll. Ein breites Publikum macht eine Aussage aber nicht falsch; ob sie trägt, zeigt sich an den Befunden, nicht am Leserkreis."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"McBrearty, S.; Brooks, A. S. (2000): The revolution that wasn't: a new interpretation of the origin of modern human behavior. Journal of Human Evolution 39(5), 453–563 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1006/jhev.2000.0435","url":"https://pubmed.ncbi.nlm.nih.gov/11102266/","abruf":"2026-10-12"},{"typ":"url","kurz":"Henshilwood, C. S.; d'Errico, F.; Watts, I. (2009): Engraved ochres from the Middle Stone Age levels at Blombos Cave, South Africa. Journal of Human Evolution 57(1), 27–47 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1016/j.jhevol.2009.01.005","url":"https://pubmed.ncbi.nlm.nih.gov/19487016/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Harari, Y. N. (2013): Eine kurze Geschichte der Menschheit (Sapiens). München: DVA","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1577bafd9ba2c4ed"}},{"id":"qx-e-039","clusterId":"E","werkstueckRef":"E.3.2","stufe":1,"question":"Welche Erwiderung auf diesen Einwand trifft zu?","options":["Der Wert ist rein subjektiv, denn er steckt in jedem einzelnen Kopf und verschwindet, sobald dieser Mensch aufhört, daran zu glauben.","Der Wert ist objektiv, denn Scheine und Münzen sind greifbare Dinge und existieren unabhängig davon, was Menschen darüber denken.","Der Wert ist keine Einbildung des Einzelnen, sondern beruht auf dem gemeinsamen Glauben vieler und zeigt sich in den Folgen, die er für alle hat.","Der Wert ist eine bloße Fantasie, denn was nur im Denken existiert, hat keine Wirkung auf das, was Menschen tatsächlich tun."],"correctIndex":2,"explanation":"Der Einwand verwechselt zwei Dinge: „nur im Denken“ und „nur im Denken eines Einzelnen“. Der Wert des Geldes hängt nicht an einer einzelnen Person, sondern an der Übereinkunft von Millionen. Deshalb kann ihn niemand allein wegdenken: Wer als Einziger aufhört, an den Euro zu glauben, ist nicht erleuchtet, sondern pleite. Ein Schimpanse zeigt, wie viel am geteilten Glauben hängt: Für ihn ist der Schein nur ein Stück Papier, er tauscht ihn nicht gegen Bananen. Gleichzeitig ist der Wert nicht objektiv wie die Schwerkraft, denn er würde verschwinden, wenn eine kritische Masse von Menschen aufhört, an ihn zu glauben. Solche Dinge nennt man intersubjektiv: Sie existieren durch gemeinsamen Glauben und wirken trotzdem real.","coreRule":"⚡ Intersubjektiv real ist, was nur durch den gemeinsamen Glauben vieler existiert – und trotzdem handfeste Folgen hat. „Nur im Kopf“ heißt nicht „nur im Kopf eines Einzelnen“ und auch nicht „wirkungslos“.","beleg":"Werkstück E.3.2 (Kernidee; Kontext & Tiefe: Drei Arten von Realität)","status":"entwurf","scenario":"Im Gespräch über Geld sagt jemand: „Geld ist doch nur bedrucktes Papier und ein Stück Metall. Der Wert existiert nur in unseren Köpfen, also ist er Einbildung. Wenn ich selbst nicht daran glaube, kann es mir egal sein.“","kurz":"„Nur im Denken“ heißt nicht „nur im Denken eines Einzelnen“. Der Wert hängt an der Übereinkunft von Millionen und lässt sich deshalb nicht allein wegdenken: Wer als Einziger nicht mehr an den Euro glaubt, ist pleite.","prueffrage":"Was geschieht mit jemandem, der als Einziger in seiner Stadt aufhört, Geld anzunehmen?","rueckmeldung":[{"option":0,"text":"Dass der Wert am Glauben hängt und nicht wie die Schwerkraft objektiv ist, stimmt. Er steckt aber nicht im einzelnen Kopf, sondern in der Übereinkunft vieler, deshalb verschwindet er nicht, wenn eine Person aufhört, daran zu glauben."},{"option":1,"text":"Scheine und Münzen sind tatsächlich greifbar, doch der Wert ist nicht das Papier selbst. Er hängt am gemeinsamen Glauben und würde verschwinden, wenn sehr viele aufhören, daran zu glauben. Für einen Schimpansen bleibt der Schein nur Papier."},{"option":3,"text":"Dass der Wert nur im Denken existiert, stimmt. Daraus folgt aber nicht, dass er ohne Wirkung wäre: Gemeinsamer Glaube bestimmt, was Menschen tauschen, kaufen und besitzen. Die Folgen sind real, auch wenn der Wert nicht im Stoff steckt."}],"familie":"gemeinsamer-glaube","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Social Ontology (2018, überarbeitet 2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/social-ontology/","abruf":"2026-10-12"},{"typ":"url","kurz":"Beran, M. J.; Parrish, A. E. (2021): Non-human primate token use shows possibilities but also limitations for establishing a form of currency. Philosophical Transactions of the Royal Society B 376(1819), 20190675 (PMC-Volltext)","oeffentlich":true,"doi":"10.1098/rstb.2019.0675","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7815425/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Harari, Y. N. (2013): Eine kurze Geschichte der Menschheit (Sapiens). München: DVA","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"6fb5884b2cb5c331"}},{"id":"qx-e-040","clusterId":"E","werkstueckRef":"E.3.2","stufe":2,"question":"Welche Erklärung für den Wertverlust ist am stimmigsten?","options":["Der Wert des Geldes beruht auf dem gemeinsamen Vertrauen vieler Menschen; schwindet dieses Vertrauen breit, bricht der Wert zusammen, auch wenn die Scheine gleich bleiben.","Der Wert des Geldes hängt vom Material und Gebrauchswert des Papiers ab; bei starker Inflation werden die Scheine schlechter und sind deshalb weniger wert.","Der Wert des Geldes ist eine rein persönliche Einschätzung jedes Einzelnen; jeder kann ihn für sich beliebig ändern, ohne dass dies andere betrifft.","Der Wert des Geldes ist eine objektive Größe wie die Schwerkraft; Schwankungen entstehen nur durch Messfehler bei den Behörden und Zentralbanken."],"correctIndex":0,"explanation":"Geld hat keinen Wert, der im Papier steckt; es ist nur so viel wert, wie andere dafür hergeben, und das hängt am breiten Vertrauen, dass es weiter angenommen wird. Ausgelöst wird eine Hyperinflation meist durch massive Geldschöpfung, etwa wenn ein Staat seine Ausgaben über die Notenpresse bezahlt; schwindet dann das Vertrauen, beschleunigt das den Verfall, obwohl die Scheine physisch dieselben bleiben. Die Erklärung über das Papier scheitert genau daran: Das Papier ist vorher und nachher dasselbe. Eine rein private Einschätzung erklärt den Absturz ebenso wenig, denn wer als Einziger nicht mehr an die Währung glaubt, ändert an ihrem Wert nichts, solange andere sie annehmen. Und anders als die Schwerkraft, die wirkt, egal was wir glauben, hängt der Geldwert vom Verhalten der Menschen ab, sonst könnte er nicht innerhalb weniger Tage kollabieren.","coreRule":"⚡ Was nur auf gemeinsamem Glauben ruht, kann zerbrechen, wenn der Glaube bricht. Die Veränderung muss dann im Verhalten der Menschen gesucht werden, nicht im Material.","beleg":"Werkstück E.3.2 (Kontext & Tiefe: Intersubjektive Realität; Red Flags; Anwendung & Relevanz: In der Wirtschaft)","status":"entwurf","scenario":"Eine Währung verliert in einer Hyperinflation fast über Nacht ihren Wert, obwohl sich die Geldscheine physisch nicht verändern. Kollegin A sagt: „Da muss das Papier selbst schlechter geworden sein.“ Kollege B sagt: „Nein, das hat mit dem Papier nichts zu tun.“","kurz":"Der Wert von Geld steckt nicht im Papier, sondern im breiten Vertrauen, dass andere es annehmen. Bricht dieses Vertrauen weg, fällt der Wert, während die Scheine unverändert bleiben. Wer ihn im Material sucht, übersieht das.","prueffrage":"Was genau hat sich an den Geldscheinen selbst zwischen vorher und nachher verändert, und wie schnell ist der Wert gefallen?","rueckmeldung":[{"option":1,"text":"Wert wirkt wie eine Eigenschaft des Dings selbst, deshalb liegt der Blick aufs Material nahe. Die Scheine sind aber vorher und nachher dieselben, also kann ihre Beschaffenheit den plötzlichen Absturz nicht erklären."},{"option":2,"text":"Daran stimmt, dass der Wert an Überzeugungen hängt. Er ist aber keine private Einschätzung: Wer allein nicht mehr an die Währung glaubt, ändert für andere nichts; erst wenn sehr viele das Vertrauen verlieren, bewegt sich der Wert."},{"option":3,"text":"Die Schwerkraft wirkt, egal was wir glauben; der Geldwert dagegen hängt vom Verhalten der Menschen ab, sonst könnte er nicht in wenigen Tagen kollabieren. Mit Messfehlern der Behörden lässt sich ein solcher Absturz nicht erklären."}],"familie":"gemeinsamer-glaube","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Deutscher Bundestag: Hyperinflation in Deutschland 1923 (Reihe „100 Jahre Weimar“)","oeffentlich":true,"url":"https://www.bundestag.de/parlament/geschichte/100-jahre-weimar/hyperinflation-970722","abruf":"2026-10-12"},{"typ":"url","kurz":"Agur, I.; Capelle, D.; Dell'Ariccia, G.; Sandri, D. (2022): Should Monetary Finance Remain Taboo? IMF Blog, 22.02.2022","oeffentlich":true,"url":"https://www.imf.org/en/Blogs/Articles/2022/02/22/should-monetary-finance-remain-taboo","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"82679e55640e997c"}},{"id":"qx-e-041","clusterId":"E","werkstueckRef":"E.3.2","stufe":3,"question":"Welche Rückfrage prüft die Behauptung des Kollegen am besten?","options":["Was geschähe mit dem Modell, wenn alle Beteiligten morgen aufhörten, sich an seine Regeln zu halten?","Wie viele Beteiligte halten das Modell derzeit für richtig und befolgen seine Regeln?","Wie lange gilt das Modell schon, und hat es sich in dieser Zeit im Alltag bewährt?","Welche anerkannten Fachleute vertreten das Modell, und wie sicher klingen sie dabei?"],"correctIndex":0,"explanation":"Ein Naturgesetz gilt unabhängig davon, was wir glauben: Wer nicht mehr an die Schwerkraft glaubt, fällt trotzdem. Ein Wirtschaftsmodell dagegen besteht aus gemeinsamen Regeln, Verträgen und Erwartungen. Es wirkt nur, solange genügend Menschen mitmachen, und es kann sich ändern, wenn sie ihr Verhalten ändern. Die Rückfrage, ob es noch bestünde, wenn alle morgen aufhörten mitzumachen, trennt diese beiden Fälle. Wie viele Menschen das Modell befolgen, wie alt es ist oder wer es vertritt, sagt nur etwas darüber, wie fest es verankert ist, nicht darüber, ob es von der Zustimmung der Beteiligten abhängt. Der Fehler des Kollegen liegt darin, ein von Menschen geschaffenes Gefüge für unveränderlich zu halten. Das führt zu Dogmatismus, weil Verbesserungen gar nicht erst gesucht werden. Umgekehrt wäre es auch falsch, das Modell für beliebig änderbar zu halten: Wer allein aussteigt, ändert nichts, sondern trägt nur selbst die Folgen.","coreRule":"⚡ Frag bei einer „Naturgesetz“-Behauptung: Gilt sie auch, wenn alle morgen nicht mehr daran glauben?","beleg":"Werkstück E.3.2 (Der Kipppunkt; Anti-Denkmuster)","status":"entwurf","scenario":"In einer Teamsitzung über die Preisgestaltung sagt ein Kollege: „Dieses Wirtschaftsmodell ist wie ein Naturgesetz – daran kann man nichts ändern.“ Das Modell beruht auf Regeln, Verträgen und Erwartungen, auf die sich viele Menschen eingestellt haben.","quote":"","quoteLabel":"","kurz":"Ein Naturgesetz gilt auch, wenn niemand mehr daran glaubt, ein Wirtschaftsmodell nur, solange genügend Menschen mitmachen. Der Fehler des Kollegen ist, ein von Menschen getragenes Gefüge für unveränderlich zu halten.","prueffrage":"Woraus besteht das Modell im Einzelnen, und wer hat diese Regeln, Verträge und Erwartungen hervorgebracht?","rueckmeldung":[{"option":1,"text":"Dass viele Beteiligte mitmachen, zeigt, wie fest das Modell verankert ist. Es klärt aber nicht, ob das Modell von ihrer Zustimmung abhängt, und genau darum geht es bei der Behauptung."},{"option":2,"text":"Eine lange Geltung spricht für Beständigkeit und Verankerung. Auch ein altes Modell kann aber ganz auf Regeln und Erwartungen beruhen; das Alter sagt nichts darüber, ob es sich ändern lässt."},{"option":3,"text":"Anerkannte Fachleute und ihr sicherer Ton wirken beruhigend. Sie sagen aber nichts darüber, ob das Modell von menschlichem Mitmachen abhängt, und das müsste die Rückfrage klären."}],"familie":"gemeinsamer-glaube","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Social Ontology (2018, überarbeitet 2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/social-ontology/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Harari, Y. N. (2013): Eine kurze Geschichte der Menschheit (Sapiens). München: DVA","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"9be69e6886d2aa0b"}},{"id":"qx-e-042","clusterId":"E","werkstueckRef":"E.3.2","stufe":4,"question":"Ein Beitrag behauptet: „Schimpansen verstehen Geld. Sie tauschen Marken gegen Futter, also nutzen sie Geld genau wie wir.“ Welche Frage prüft diese Behauptung am besten?","options":["Haben die Tiere nur gelernt, was belohnt wird, oder teilen sie auch eine Vorstellung davon, dass die Marken Wert haben?","Wie oft pro Stunde tauschen die Tiere ihre Marken im Durchschnitt gegen Futter ein?","Wie schneiden Schimpansen bei Intelligenztests im Vergleich zu anderen Tierarten ab?","Schmeckt den Tieren das Futter aus dem Automaten besser als das Futter in ihrem Käfig?"],"correctIndex":0,"explanation":"Der Schluss „tauscht Marken gegen Futter, also nutzt Geld“ verwechselt gelerntes Tauschen mit Geld. Nach Beran & Parrish (2021) lernen Primaten, Marken als Platzhalter für Futter zu schätzen, nutzen sie aber nicht so, wie Menschen Währung nutzen. Beim Geld kommt etwas hinzu: Es hat Wert, weil Millionen Menschen sich gemeinsam vorstellen, dass ein Stück Papier Wert hat. Genau das prüft die Frage, ob die Tiere nur gelernt haben, was belohnt wird, oder ob sie auch eine geteilte Wertvorstellung haben. Die übrigen Fragen betreffen Häufigkeit, Intelligenz oder Geschmack und sagen nichts darüber, ob mehr als gelerntes Tauschen vorliegt. Schimpansen lernen den Markentausch übrigens schon seit den 1930er-Jahren, ohne damit Teil unseres Geldsystems zu sein.","coreRule":"⚡ Tauschen können ist noch kein Geld: Dazu gehört die geteilte Geschichte über seinen Wert.","beleg":"Werkstück E.3.2 (Einstieg: Die unmögliche Banane); Fn. gl-e-marken (Beran & Parrish 2021; Wolfe 1936)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"1f6b04564b6fa704","vermerk":"Prüfpult"},"scenario":"In einem Versuch lernen Schimpansen, Marken in einen Automaten zu stecken und dafür Futter zu bekommen. Ein Beitrag zieht daraus den Schluss, die Tiere seien Teil unseres Geldsystems.","quote":"","quoteLabel":"","kurz":"Marken gegen Futter zu tauschen ist gelerntes Verhalten und noch kein Geld. Geld gilt, weil viele gemeinsam an seinen Wert glauben, und der Fehler liegt darin, Belohnungslernen mit dieser geteilten Vorstellung gleichzusetzen.","prueffrage":"Was tun die Tiere mit den Marken, wenn gerade kein Automat in der Nähe ist oder ein anderes Tier eine Marke anbietet?","rueckmeldung":[{"option":1,"text":"Eine hohe Tauschrate wirkt wie ein Beleg für echten Gebrauch. Sie zeigt aber nur, wie gut der Tausch eingeübt ist, und sagt nichts darüber, ob mehr als gelerntes Verhalten dahintersteckt."},{"option":2,"text":"Schimpansen gelten als klug, und das scheint zu einem Geldverständnis zu passen. Ihr Abschneiden in Intelligenztests sagt aber nichts darüber, ob sie mit den Marken eine geteilte Wertvorstellung verbinden."},{"option":3,"text":"Ob das Futter besser schmeckt, betrifft nur die Belohnung selbst. Es sagt nichts darüber, ob die Marken als Wert verstanden werden oder die Tiere bloß gelernt haben, was Futter bringt."}],"familie":"gemeinsamer-glaube","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Beran, M. J.; Parrish, A. E. (2021): Non-human primate token use shows possibilities but also limitations for establishing a form of currency. Philosophical Transactions of the Royal Society B 376(1819), 20190675 (PMC-Volltext)","oeffentlich":true,"doi":"10.1098/rstb.2019.0675","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7815425/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Wolfe, J. B. (1936): Effectiveness of token-rewards for chimpanzees. Comparative Psychology Monographs 12(5) (zitiert nach Beran & Parrish)","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1f6b04564b6fa704"}},{"id":"qx-e-043","clusterId":"E","werkstueckRef":"E.3.3","stufe":1,"question":"Eine Freundin sagt: „Ich habe keine Ideologie, ich bin einfach nur objektiv und pragmatisch. Wer anderer Meinung ist, folgt eben einer Ideologie.“ Welche Antwort trifft den Denkfehler am besten?","options":["Wer sich für objektiv hält, hat meist bereits geprüft, dass seine Überzeugungen keiner Weltsicht entspringen. Der Satz ist deshalb gut begründet.","Auch wer sich für rein pragmatisch hält, bringt Grundannahmen darüber mit, was gerecht ist oder was Probleme verursacht. Die Annahme, keine zu haben, macht sie nur unsichtbar.","Wer sich pragmatisch nennt, bildet seine Urteile ausschließlich aus Einzelfällen. Ein geschlossenes Überzeugungssystem mit Grundannahmen kann er deshalb gar nicht entwickeln.","Wer sich objektiv nennt, ist offen für andere Meinungen und folgt deshalb keiner Weltsicht. Der Satz verrät also keinen Denkfehler, sondern eine nüchterne Haltung."],"correctIndex":1,"explanation":"Eine Ideologie ist ein zusammenhängendes System aus Überzeugungen und Werten, das erklärt, wie die Welt ist, und zugleich sagt, wie sie sein sollte. Solche Grundannahmen hat praktisch jeder, etwa darüber, was gerecht ist oder woher Leid kommt. Die Annahme, es gebe keine Ideologie, ist selbst Teil einer Ideologie, meist der dominanten, unsichtbaren der eigenen Kultur. Wer sich für ideologiefrei hält, übersieht also seine eigene Brille und erkennt sie nur bei anderen. Der Fehler liegt darin, die eigene Brille für das Fehlen einer Brille zu halten. Gute Gegenfrage: „Welche Annahmen über Gerechtigkeit und Ursachen stecken in meiner Position?“","coreRule":"⚡ Wer glaubt, keine Weltsicht zu haben, hat trotzdem eine, und gerade diese bleibt ihm unsichtbar.","beleg":"Werkstück E.3.3 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Wer sich für ideologiefrei hält, bringt trotzdem Grundannahmen mit, etwa darüber, was gerecht ist oder woher Probleme kommen. Der Fehler: die eigene Brille für das Fehlen einer Brille zu halten und sie nur bei anderen zu erkennen.","prueffrage":"Woran misst die Freundin, was „objektiv“ oder „pragmatisch“ ist, und würde jemand mit anderen Werten denselben Maßstab wählen?","rueckmeldung":[{"option":0,"text":"Sich selbst zu prüfen ist sinnvoll, und wer sich für objektiv hält, wirkt, als hätte er das getan. Das Gefühl von Objektivität ist aber noch keine Prüfung, und gerade die eigenen Grundannahmen bleiben dabei meist unsichtbar."},{"option":2,"text":"Pragmatisch zu urteilen klingt nach reiner Erfahrung ohne Theorie. Doch schon die Auswahl der Einzelfälle und die Frage, was als Problem oder als gerecht zählt, setzen Grundannahmen voraus. Ganz ohne sie kommt praktisch niemand aus."},{"option":3,"text":"Nüchtern und offen zu sein ist eine gute Haltung, aber sie ist hier gar nicht im Spiel: Die Freundin erklärt alle anderen pauschal zu Ideologen. Und auch wer offen ist, urteilt auf Grundlage von Annahmen, die er nur selten bemerkt."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"},{"typ":"url","kurz":"Scherr, K. (2007): The End of the End of Ideology. APS Observer (Bericht über J. T. Jost)","oeffentlich":true,"url":"https://www.psychologicalscience.org/observer/the-end-of-the-end-of-ideology","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"304c2f40f2bd4f6c"}},{"id":"qx-e-044","clusterId":"E","werkstueckRef":"E.3.3","stufe":2,"question":"Was ist hier die klügste nächste Gesprächsstrategie?","scenario":"Dein Onkel sieht die Welt durch eine feste politische Überzeugung. Auf jede Statistik, die du ihm zeigst, antwortet er: „Das ist doch Propaganda“ – und wechselt das Thema. Du hast ihm schon mehrere Studien und Quellen vorgelegt, ohne dass sich etwas bewegt hat.","options":["Noch mehr Fakten und Quellen vorlegen, bis die schiere Menge der Belege seine Haltung überwältigt.","Seine Haltung als ideologisch verblendet benennen, damit er seine Scheuklappen erkennt und umdenkt.","Fragen, woran er verlässliche Quellen erkennt und welche Belege ihn umstimmen könnten.","Das Gespräch beenden, weil Menschen mit festen Überzeugungen grundsätzlich nicht erreichbar sind."],"correctIndex":2,"explanation":"Wer feste Überzeugungen hat, bewertet neue Informationen durch den Rahmen, den er schon mitbringt. Passt ein Fakt nicht hinein, wird er als Propaganda, Ausnahme oder irrelevant abgetan. Mehr Fakten desselben Typs ändern daran nichts, denn der Rahmen entscheidet, was überhaupt als Beleg zählt. Deshalb lohnt es sich, zuerst über die Spielregeln zu sprechen: Was zählt für ihn als verlässliche Quelle? Was müsste passieren, damit er seine Meinung ändert? Ihn als „verblendet“ zu etikettieren, greift die Person an, statt den Rahmen zum Thema zu machen, und liefert ihm einen Grund, dich als Gegner statt als Gesprächspartner zu sehen. Das Gespräch abzubrechen unterstellt, dass niemand mit einer festen Weltsicht erreichbar ist. Das ist eine Verallgemeinerung, die sich nicht belegen lässt.","coreRule":"⚡ Wenn Fakten abprallen, sprich über den Rahmen, nicht nur über die Daten.","beleg":"Werkstück E.3.3 (Anwendung & Relevanz: In der Politik; Kontext & Tiefe: Sich selbst immunisiert)","status":"entwurf","kurz":"Wer feste Überzeugungen hat, wertet Fakten durch seinen Rahmen, der entscheidet, was überhaupt als Beleg zählt. Mehr Belege desselben Typs ändern daran wenig; erst die Frage nach seinen Spielregeln macht den Rahmen selbst zum Thema.","prueffrage":"Was hat dein Onkel auf deine bisherigen Quellen jeweils geantwortet, und was haben diese Antworten gemeinsam?","rueckmeldung":[{"option":0,"text":"Fakten bleiben wichtig, und eine breite Beleglage wirkt solide. Nur hat dein Onkel schon mehrere Quellen als „Propaganda“ abgetan, und weiteren vom selben Typ dürfte es genauso ergehen: Sein Rahmen entscheidet, was überhaupt zählt."},{"option":1,"text":"Dass sein Rahmen das eigentliche Hindernis ist, trifft zu. Das Etikett „verblendet“ greift aber die Person an, statt den Rahmen zum Thema zu machen, und gibt ihm einen Grund, dich als Gegner zu sehen."},{"option":3,"text":"Das Gespräch wirkt festgefahren, und eine Pause kann sinnvoll sein. Die Begründung trägt aber nicht: Dass feste Überzeugungen grundsätzlich unerreichbar machen, lässt sich nicht belegen, und die bisherigen Versuche haben nur einen Weg erprobt."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Kahan, D. M. (2013): Ideology, motivated reasoning, and cognitive reflection. Judgment and Decision Making 8(4), 407–424","oeffentlich":true,"url":"https://dlab.sauder.ubc.ca/sjdm/journal/13/13313/jdm13313.html","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"f6bbcf7e75025f06"}},{"id":"qx-e-045","clusterId":"E","werkstueckRef":"E.3.3","stufe":3,"question":"Welche Beobachtung zeigt am deutlichsten, dass ihre Weltanschauung zum starren Dogma geworden ist?","options":["Die Weltanschauung bietet eine klare Diagnose, eine Zukunftsvision und eine Strategie und bringt ihre Mitglieder dadurch zum gemeinsamen Handeln.","Die Weltanschauung gibt ihren Mitgliedern ein starkes Gefühl von Zugehörigkeit und stiftet dadurch eine gemeinsame Identität.","Die Weltanschauung wird von sehr vielen Menschen geteilt und entfaltet dadurch eine große politische Wirkung in der Gesellschaft.","Widersprechende Belege werden als Beweis für die Verblendung der Kritiker gewertet, und kein denkbares Ereignis könnte die Überzeugung erschüttern."],"correctIndex":3,"explanation":"Erklärung, Handlungsimpuls und Zusammenhalt sind normale Leistungen jeder Weltanschauung, auch einer gesunden; sie sagen nichts darüber, ob man noch aus Gegenbelegen lernen kann. Auch große Verbreitung ist kein Warnzeichen, denn viele richtige und nützliche Ideen finden breite Zustimmung. Entscheidend ist die Frage, ob die Überzeugung noch widerlegbar ist. Wenn jeder Einwand zum Beweis für die Bösartigkeit oder Verblendung des Kritikers umgedeutet wird und es kein denkbares Ereignis gibt, das etwas ändern würde, dient die Weltanschauung nicht mehr dem Verständnis der Welt. Dann zählt die Treue zur eigenen Lehre mehr als das, was die Wirklichkeit zeigt.","coreRule":"⚡ Eine Weltanschauung wird starr, wenn nichts mehr sie widerlegen darf.","beleg":"Werkstück E.3.3 (Red Flags; Der Kipppunkt; Das Adaptive Talent)","status":"entwurf","scenario":"Eine Gruppe vertritt eine Weltanschauung, die große Fragen erklärt und ihren Mitgliedern Zusammenhalt gibt. Ein Mitglied legt ihr eine Studie vor, die einer ihrer Kernannahmen widerspricht. Die Gruppe antwortet: „Solche Studien werden von unseren Gegnern bezahlt. Wer sie ernst nimmt, ist blind für die Wahrheit.“ Auf Nachfrage räumt sie ein, dass es kein denkbares Ergebnis gäbe, das ihre Überzeugung ins Wanken brächte.","kurz":"Entscheidend ist, ob die Überzeugung noch widerlegbar ist. Wird jeder Einwand zum Beweis für die Verblendung des Kritikers und könnte kein denkbares Ergebnis etwas ändern, zählt die Treue zur Lehre mehr als das, was die Wirklichkeit zeigt.","prueffrage":"Was hat die Gruppe mit der vorgelegten Studie selbst gemacht, bevor sie antwortete?","rueckmeldung":[{"option":0,"text":"Diagnose, Vision und Strategie machen eine Gruppe handlungsfähig und sind ein Merkmal jeder Weltanschauung, auch einer gesunden. Ob man noch aus Gegenbelegen lernen kann, sagt das nicht."},{"option":1,"text":"Zugehörigkeit und gemeinsame Identität sind normale Leistungen, die auch gesunde Weltanschauungen erbringen. Sie zeigen nicht, ob die Überzeugung noch durch Belege erschütterbar wäre."},{"option":2,"text":"Viele richtige und nützliche Ideen finden breite Zustimmung, große Verbreitung ist also kein Warnzeichen. Und politische Wirkung sagt nichts darüber, ob die Überzeugung noch widerlegbar ist."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"ebdcc8598e23846a"}},{"id":"qx-e-046","clusterId":"E","werkstueckRef":"E.3.3","stufe":4,"question":"Eine Kollegin sagt im Team: „Ich habe keine Ideologie, ich bin rein pragmatisch.“ Welche Erwiderung nimmt ihre Aussage ernst und bleibt zugleich logisch tragfähig?","options":["„Auch wer nur auf das Funktionierende schaut, legt vorher fest, was als funktionierend zählt. Dahinter steckt eine Weltsicht, die oft unsichtbar bleibt, weil alle um uns herum sie teilen.“","„Das stimmt, solange du dich an keine Partei bindest, denn eine Weltsicht entsteht erst durch eine formale Mitgliedschaft in einer Organisation.“","„Das stimmt für dich, denn deine naturwissenschaftliche Ausbildung macht dein Urteil frei von Wertvorstellungen und damit unabhängig von jeder Weltsicht.“","„Das ist nur eine Ausrede, denn wer so spricht, verbirgt in der Regel bewusst eine extreme politische Überzeugung vor den anderen im Raum.“"],"correctIndex":0,"explanation":"Jeder Mensch hat eine Ideologie, auch wer glaubt, rein „objektiv“ oder „pragmatisch“ zu sein. Die Annahme, es gebe gar keine, ist selbst Teil einer Ideologie, meist der dominanten, unsichtbaren Ideologie der eigenen Kultur. Das lässt sich so begründen: „Pragmatisch“ zu sein beantwortet nicht die Frage, woran man Erfolg misst, etwa an Kosten, an Gerechtigkeit, an Freiheit oder an Geschwindigkeit. Was als „funktionierend“ gilt, setzt also eine Gewichtung voraus, und die gehört zu einer Weltsicht, auch wenn sie sich nicht so anfühlt. Gerade die Weltsicht, die alle in der Umgebung teilen, fällt nicht mehr auf und wird mit „neutral“ verwechselt. Die übrigen Erwiderungen scheitern an derselben Stelle: Sie setzen voraus, dass sich eine Weltsicht nur an äußeren Merkmalen wie einer Parteibindung oder einer Ausbildung festmachen lässt, oder sie unterstellen der Kollegin Absicht. Dabei ist ihr die eigene Brille schlicht nicht bewusst. Hilfreich ist die Frage, wie jemand mit einer ganz anderen Weltsicht die Lage beurteilen würde und woran er Erfolg messen würde.","coreRule":"⚡ Die unsichtbarste Brille ist die, die alle um dich herum auch tragen.","beleg":"Werkstück E.3.3 (Kontext & Tiefe; Anti-Denkmuster): „Eine Ideologie hat jeder, auch wenn er glaubt, rein ‚objektiv‘ oder ‚pragmatisch‘ zu sein.“","status":"entwurf","scenario":"In einer Besprechung über ein neues Förderprogramm wird heftig gestritten. Die Kollegin hält sich heraus und sagt: „Ich habe keine Ideologie, ich bin rein pragmatisch. Ich schaue nur, was funktioniert.“","quote":"Eine Ideologie hat jeder, auch wenn er glaubt, rein „objektiv“ oder „pragmatisch“ zu sein.","quoteLabel":"Merksatz:","kurz":"Wer „pragmatisch“ sagt, hat noch nicht geklärt, woran er Erfolg misst, etwa an Kosten, Gerechtigkeit oder Tempo. Diese Gewichtung gehört zu einer Weltsicht, die man selbst oft nicht bemerkt, weil sie im Umfeld alle teilen.","prueffrage":"Woran würde jemand mit ganz anderen Prioritäten bei diesem Programm merken, dass es „funktioniert“?","rueckmeldung":[{"option":1,"text":"Eine Parteibindung ist leicht zu erkennen, daher wirkt sie wie ein brauchbares Kriterium. Eine Weltsicht hat man aber auch ohne jede Mitgliedschaft, und so bestätigt die Erwiderung die Aussage der Kollegin, statt sie zu prüfen."},{"option":2,"text":"Eine naturwissenschaftliche Ausbildung schult das Prüfen, legt aber nicht fest, woran Erfolg gemessen wird; diese Gewichtung bleibt eine Wertung. Von einer solchen Ausbildung der Kollegin ist zudem nirgends die Rede."},{"option":3,"text":"Manchmal verbirgt tatsächlich jemand Überzeugungen, aber hier fehlt dafür jeder Anhaltspunkt. Die Kollegin muss nichts verbergen, ihr ist die eigene Brille einfach nicht bewusst. Eine unterstellte Absicht nimmt ihre Aussage nicht ernst."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"},{"typ":"url","kurz":"Pronin, E.; Gilovich, T.; Ross, L. (2004): Objectivity in the eye of the beholder: divergent perceptions of bias in self versus others. Psychological Review 111(3), 781–799 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1037/0033-295X.111.3.781","url":"https://pubmed.ncbi.nlm.nih.gov/15250784/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3b64a6fbd86560d0"}},{"id":"qx-e-047","clusterId":"E","werkstueckRef":"E.3.4","stufe":1,"question":"Welche Schlussfolgerung ist am besten begründet?","options":["Die Kinder waren schon vorher begabter, denn der Test hat ihre Talente erkannt und die Lehrkräfte haben sie danach gezielt gefördert.","Die Kinder haben zusätzlichen Förderunterricht bekommen, denn die Schulleitung hat sie bevorzugt und ihnen mehr Lernzeit eingeräumt.","Die Kinder stammten aus Familien mit höherem Bildungsstand, denn solche Familien fördern ihre Kinder zu Hause deutlich stärker.","Die Kinder hatten Lehrkräfte mit höheren Erwartungen, denn die Auswahl war zufällig und nur die Erwartung unterschied sich."],"correctIndex":3,"explanation":"Die Kinder wurden per Los gezogen, ihre angeblichen Testergebnisse waren erfunden. Die einzige Variable, die sich geändert hatte, war die Erwartungshaltung der Lehrkräfte. Eine bessere Begabung, ein anderer Familienhintergrund oder zusätzlicher Förderunterricht werden nirgends genannt und lassen sich daher nicht als Ursache begründen. Als Wirkweg gilt das Verhalten der Lehrkräfte, das sich aus ihrer Erwartung ergeben kann: wärmerer Umgang, anspruchsvollere Aufgaben, klarere Rückmeldungen, mehr Gelegenheit zur Beteiligung. So kann eine bloße Erwartung selbst zur Ursache dessen werden, was sie vorhersagt. Vorsicht bei der Größenordnung: Im ursprünglichen Experiment von Rosenthal und Jacobson lag der Zuwachs bei rund zwölf statt acht IQ-Punkten, und der Vorsprung zeigte sich fast nur in der ersten und zweiten Klasse. Spätere Forschung findet solche Effekte meist klein und wenig dauerhaft. Die Schlussfolgerung betrifft deshalb die Ursache des Unterschieds, nicht ein großes, sicheres Ausmaß.","coreRule":"⚡ Wenn die Gruppen per Zufall gebildet wurden, bleibt als Ursache nur, was sich zwischen ihnen tatsächlich unterscheidet, hier die Erwartung.","beleg":"Werkstück E.3.4 (Einstieg: Die akademischen Überflieger); Fn. gl-e-rosenthal (Rosenthal & Jacobson 1966/1968)","status":"entwurf","scenario":"Ein Schulleiter lässt an einer Grundschule alle Kinder einen IQ-Test schreiben. Danach teilt er den Lehrkräften vertraulich mit, welche 20 % der Kinder laut Test im kommenden Jahr besonders stark aufblühen werden. Tatsächlich hat er die Namen per Los gezogen. Am Jahresende haben diese Kinder im Schnitt mehr dazugewonnen als ihre Mitschüler.","kurz":"Die Namen wurden gelost, und nur die Erwartung der Lehrkräfte unterschied sich; deshalb ist sie die am besten begründete Ursache, nicht eine echte Begabung. Wie groß solche Effekte sind, ist eine andere Frage: Meist fallen sie klein aus.","prueffrage":"Was wusste der Schulleiter über die Kinder, deren Namen er den Lehrkräften nannte?","rueckmeldung":[{"option":0,"text":"Dass die Lehrkräfte die Kinder danach gezielt gefördert haben, ist gut vorstellbar. Aber der Test hat nichts erkannt: Die Namen wurden gelost, die Ergebnisse waren erfunden. Für einen Begabungsvorsprung der Gelosten gibt es daher keinen Anhaltspunkt."},{"option":1,"text":"Zusätzliche Lernzeit würde den Vorsprung gut erklären, doch davon ist nirgends die Rede: Der Schulleiter hat nur Namen genannt. Was sich nachweislich unterschied, war allein die Erwartung der Lehrkräfte."},{"option":2,"text":"Der Familienhintergrund beeinflusst Lernerfolge tatsächlich oft stark. Hier wurde aber per Los gezogen, daher sind die Familien der ausgewählten Kinder im Schnitt nicht anders als die der übrigen. Der Unterschied lässt sich damit nicht erklären."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies. Personality and Social Psychology Review 9(2), 131–155 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1207/s15327957pspr0902_3","url":"https://pubmed.ncbi.nlm.nih.gov/15869379/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies. Personality and Social Psychology Review 9(2) (Verlagsfassung)","oeffentlich":false,"seite":"134"},{"typ":"doi","kurz":"Rosenthal, R.; Jacobson, L. (1966): Teachers' Expectancies: Determinants of Pupils' IQ Gains. Psychological Reports 19(1), 115–118","oeffentlich":false,"doi":"10.2466/pr0.1966.19.1.115"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"57c5538e8731500e"}},{"id":"qx-e-048","clusterId":"E","werkstueckRef":"E.3.4","stufe":2,"question":"Welche Erklärung dafür, dass sich Fehler und Lustlosigkeit häufen, ist am sparsamsten und lässt sich am besten prüfen?","scenario":"Ein neuer Abteilungsleiter hält sein Team für wenig fähig. Er prüft jede Kleinigkeit nach und vergibt keine eigenständigen Aufgaben. Nach einigen Monaten häufen sich Fehler und Lustlosigkeit, und er sagt: „Ich habe es ja gewusst.“","options":["Seine Erwartung hat sein Verhalten geprägt, das Team reagierte mit Unsicherheit und Fehlern, die seine Erwartung scheinbar bestätigen.","Das Team hat sich auf eine gemeinsame Sicht geeinigt und ist deshalb für jede Kritik unempfänglich geworden, was die Fehler erklärt.","Die Fehler zeigen, dass seine Einschätzung der Mitarbeiter von Anfang an richtig war und seine Urteilskraft verlässlich ist.","Die Mitarbeiter reden sich ein, dass ihnen die Aufgaben ohnehin nicht liegen, und leisten deshalb weniger als zuvor."],"correctIndex":0,"explanation":"Der Manager misstraut seinem Team, kontrolliert es engmaschig und überträgt keine Verantwortung. Wer so behandelt wird, wird oft unsicher und demotiviert und macht mehr Fehler, was die ursprüngliche Erwartung scheinbar bestätigt. So kann ein sich selbst verstärkender Kreislauf aus Überzeugung, Handlung, Selbstbild und Gegenhandlung entstehen (Golem-Effekt). Seine Aussage „Ich habe es ja gewusst“ taugt nicht als Beweis, denn die Fehler können Folge seines Verhaltens sein. Prüfen ließe sich das, indem man klärt, ob die Fehler schon vor seinem Kontrollverhalten auftraten oder erst danach, oder indem er probeweise Verantwortung überträgt und beobachtet, ob sich die Leistung ändert. Die anderen Erklärungen brauchen zusätzliche, unbelegte Annahmen: eine Gruppeneinigung, über die nichts gesagt wird, eine unabhängig bestätigte Fähigkeit des Managers oder einen Gedankengang der Mitarbeiter, von dem das Szenario nichts erwähnt. Wichtig bleibt: Dass Erwartungen Leistungen beeinflussen können, zeigt sich im Klassenzimmer, die Effekte sind aber meist klein und wenig dauerhaft, und oft sagen Erwartungen Leistungen nur deshalb voraus, weil sie zutreffen. Deshalb braucht es einen Vergleich, bevor man sicher urteilt.","coreRule":"⚡ Wer von anderen wenig erwartet, bekommt oft genau das – und hält es für die Bestätigung. Prüfe darum, ob die Fehler vor oder nach dem eigenen Verhalten auftraten.","beleg":"Werkstück E.3.4 (Kontext & Tiefe: Kreislauf, Golem-Effekt; Anwendung & Relevanz: In der Führung & im Management)","status":"entwurf","kurz":"Am sparsamsten ist: Wer eng kontrolliert wird und keine Verantwortung bekommt, wird oft unsicher und lustlos, und die Fehler können dann Folge des Misstrauens sein, statt es zu belegen. „Ich habe es ja gewusst“ beweist deshalb nichts.","prueffrage":"Waren die Fehler und die Lustlosigkeit schon da, bevor er mit der Kontrolle begann, oder erst danach?","rueckmeldung":[{"option":1,"text":"Eine Gruppe kann sich tatsächlich auf eine gemeinsame Sicht einigen. Von einer solchen Einigung oder von abprallender Kritik ist aber nirgends die Rede; die Erklärung braucht eine Annahme, die nichts stützt."},{"option":2,"text":"Die Fehler als Bestätigung seines Urteils zu lesen, wirkt schlüssig. Doch so beweist alles seine Sicht, auch das, was sein eigenes Verhalten auslöst. Ob er die Fähigkeiten richtig einschätzt, bleibt offen."},{"option":3,"text":"Dass Selbstbild und Leistung zusammenhängen, ist plausibel. Dass sich die Mitarbeiter etwas einreden, wird aber nirgends berichtet; das wäre eine Zusatzannahme, und sein Verhalten als möglicher Auslöser bliebe außen vor."}],"familie":"erwartung-erfuellt-sich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies. Personality and Social Psychology Review 9(2), 131–155 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1207/s15327957pspr0902_3","url":"https://pubmed.ncbi.nlm.nih.gov/15869379/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"cd242c582dcad02c"}},{"id":"qx-e-049","clusterId":"E","werkstueckRef":"E.3.4","stufe":3,"question":"Welche Einschätzung des Forschungsstands ist angemessen?","options":["Der Effekt ist belegt, aber meist klein und wenig dauerhaft; dass er die Intelligenz tatsächlich verändert, ist offen, und Erwartungen treffen oft einfach zu.","Der Effekt ist belegt und meist deutlich; dass er die Intelligenz steigert, gilt als weitgehend geklärt, und Erwartungen treffen eher selten zu.","Der Effekt ist umstritten; spätere Studien fanden ihn kaum, die Ergebnisse von 1966 gelten als überholt, und Erwartungen spielen keine nennenswerte Rolle.","Der Effekt ist nur in Grundschulen belegt; bei Erwachsenen dürfte er verschwinden, weil vor allem junge Menschen empfänglich sind, und Erwartungen treffen eher selten zu."],"correctIndex":0,"explanation":"Die Behauptung „beweist, dass … allein durch Erwartungen steigern“ geht weit über die Datenlage hinaus. Spätere Forschung bestätigt, dass Lehrererwartungen Schülerleistungen beeinflussen können, findet die Effekte aber meist klein und wenig dauerhaft. Ob dadurch die Intelligenz selbst steigt, ist ungeklärt. Dazu kommt: Lehrererwartungen sagen Leistungen oft deshalb voraus, weil sie zutreffen, nicht weil sie sich erfüllen. Schon die Originalstudie spricht gegen eine große, allgemeine Wirkung: Der Vorsprung stammte fast ganz aus den ersten beiden Klassen und zeigte sich in höheren Klassen nicht. Wer sauber urteilt, hält deshalb beides auseinander: Dass es selbsterfüllende Prophezeiungen im Klassenzimmer gibt, ist belegt, aber meist klein; dass sie die Intelligenz verändern, ist offen.","coreRule":"⚡ „Erwartungen wirken“ ist belegt – „Erwartungen machen klüger“ ist es nicht.","beleg":"Werkstück E.3.4 (Hinweis zur Beleglage); Fn. gl-e-rosenthal (Jussim & Harber 2005, S. 131, 134 f., 140, 142 f.)","status":"entwurf","scenario":"In einem Lehrbuch steht: „Rosenthals Studie von 1966 beweist, dass Lehrer die Intelligenz ihrer Schüler allein durch Erwartungen steigern können.“ Du liest nach: In der Originalstudie erhielten zufällig ausgewählte Kinder („Überflieger“) einen Zuwachs von rund zwölf statt acht IQ-Punkten, und dieser Vorsprung zeigte sich fast nur in der ersten und zweiten Klasse. Spätere Untersuchungen fanden selbsterfüllende Prophezeiungen im Klassenzimmer zwar immer wieder, aber meist klein und oft nicht von Dauer. Außerdem schätzen Lehrkräfte die Leistungen ihrer Schüler oft schon vorab recht treffend ein.","kurz":"Der Effekt ist belegt, aber meist klein und wenig dauerhaft; ob er die Intelligenz selbst verändert, ist offen. „Beweist“ und „allein“ gehen weit über die Daten hinaus, zumal Erwartungen Leistungen oft deshalb vorhersagen, weil sie zutreffen.","prueffrage":"Wie groß war der Vorsprung der „Überflieger“ gegenüber den übrigen Kindern in IQ-Punkten, und in welchen Klassen trat er auf?","rueckmeldung":[{"option":1,"text":"Dass es den Effekt gibt, stimmt. Er fiel aber meist klein aus, und ob dadurch die Intelligenz selbst steigt, ist ungeklärt. Auch dass Erwartungen selten zutreffen, passt nicht: Sie treffen oft einfach zu."},{"option":2,"text":"Die Skepsis gegenüber der großen Behauptung ist berechtigt. Doch spätere Untersuchungen fanden selbsterfüllende Prophezeiungen immer wieder, nur meist klein; eine überzogene Deutung macht den Befund nicht wertlos."},{"option":3,"text":"Dass der Vorsprung fast nur in den ersten beiden Klassen auftrat, stimmt. Über Erwachsene folgt daraus aber nichts, und Erwartungen treffen nicht selten, sondern oft einfach zu."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies. Personality and Social Psychology Review 9(2), 131–155 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1207/s15327957pspr0902_3","url":"https://pubmed.ncbi.nlm.nih.gov/15869379/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies. Personality and Social Psychology Review 9(2) (Verlagsfassung)","oeffentlich":false,"seite":"134"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"7bd8f9f3b838e4ed"}},{"id":"qx-e-050","clusterId":"E","werkstueckRef":"E.3.4","stufe":4,"question":"Wie sicher darfst du aus diesem Befund sein, und welche Schlussfolgerung ist angemessen?","options":["Die Schlussfolgerung ist gesichert, denn ein plausibler Mechanismus genügt als Beleg dafür, dass er in jeder Gruppe wirkt, in der das Stereotyp verbreitet ist.","Der Mechanismus ist plausibel, für diese Gruppe aber nicht belegt; die Studie spricht dagegen und zeigt Effekte bei anderen Gruppen.","Die Studie widerlegt den Einfluss von Stereotypen vollständig, denn bei einer Gruppe ließ sich der erwartete Effekt nicht nachweisen.","Die Schlussfolgerung bleibt richtig, denn ein Befund aus einer einzelnen Studie darf nicht gegen eine schlüssige Argumentation gewichtet werden."],"correctIndex":1,"explanation":"Die Argumentation ist logisch glatt, aber sie behauptet einen Effekt, den man messen kann, und die Messung stützt ihn für diese Gruppe nicht: Bei Mädchen in Mathematik wirkten Lehrererwartungen in der großen Studie nicht stärker als bei Jungen, bei afroamerikanischen Schülern und bei leistungsschwachen Kindern aus ärmeren Familien dagegen deutlich stärker. Damit ist weder bewiesen, dass der Effekt überall wirkt, noch, dass es ihn nirgends gibt. Das Gesamtbild nennen die Autoren für diese Gruppenbefunde „mixed“; ob Stereotype so einen Golem-Effekt im großen Stil auslösen, ist offen. Ein einleuchtender Mechanismus liefert eine Hypothese, keinen Beleg; ob und bei wem er greift, entscheiden die Daten.","coreRule":"⚡ Ein einleuchtender Mechanismus ist noch kein belegter Effekt in jeder Gruppe.","beleg":"Werkstück E.3.4 (Anwendung & Relevanz: Im Umgang mit sozialen Stereotypen); Fn. gl-e-rosenthal (Jussim & Harber 2005)","status":"entwurf","scenario":"In einer Diskussion heißt es: „Stereotype sind negative Erwartungen. Negative Erwartungen verschlechtern Leistungen. Also verschlechtert das Stereotyp ‚Mädchen sind schlecht in Mathe' die Mathematikleistungen von Mädchen.“ Du kennst eine große Studie zu Lehrererwartungen: Bei Mädchen in Mathematik wirkten die Erwartungen nicht stärker als bei Jungen. Deutlich stärker wirkten sie bei afroamerikanischen Schülern und bei leistungsschwachen Kindern aus ärmeren Familien.","kurz":"Ein einleuchtender Mechanismus ist eine Hypothese, kein Beleg: Bei Mädchen in Mathematik wirkten Erwartungen in der großen Studie nicht stärker als bei Jungen, bei anderen Gruppen dagegen deutlich. Aus Plausibilität allein folgt also nicht, dass der Effekt hier greift.","prueffrage":"Was ließe sich an Leistungsdaten von Mädchen und Jungen messen, wenn der behauptete Effekt tatsächlich bestünde?","rueckmeldung":[{"option":0,"text":"Dass der Mechanismus plausibel klingt, stimmt. Plausibel heißt aber nicht belegt: Ob er in einer Gruppe wirkt, zeigen erst Messungen, und die Studie fand bei Mädchen in Mathematik keinen stärkeren Effekt als bei Jungen."},{"option":2,"text":"Für Mädchen in Mathematik stützt die Studie den Effekt tatsächlich nicht. Ein fehlender Nachweis in einer Gruppe widerlegt aber nichts vollständig: Bei anderen Gruppen wirkten Erwartungen sogar deutlich stärker."},{"option":3,"text":"Eine einzelne Studie ist nicht das letzte Wort, und die Frage bleibt offen. Eine schlüssige Argumentation ersetzt aber keine Messung, wenn sie einen messbaren Effekt behauptet; hier spricht die Messung für diese Gruppe nicht dafür."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies. Personality and Social Psychology Review 9(2), 131–155 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1207/s15327957pspr0902_3","url":"https://pubmed.ncbi.nlm.nih.gov/15869379/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies. Personality and Social Psychology Review 9(2) (Verlagsfassung)","oeffentlich":false,"seite":"142 f."}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"f8fe4a0d89dbed21"}},{"id":"qx-e-051","clusterId":"E","werkstueckRef":"E.3.5","stufe":1,"question":"Eine Kommentatorin sagt: „Vor zwanzig Jahren hätte kein Politiker einen Vorschlag wie diesen öffentlich gemacht, heute wird er in Talkshows ernsthaft diskutiert. Dabei hat sich an den Argumenten kaum etwas geändert.“ Welche Schlussfolgerung passt am besten zu dieser Beobachtung?","options":["Der Rahmen des öffentlich Akzeptablen hat sich verschoben; die Idee ist diskutierbar geworden, ohne dass die Mehrheit sie befürwortet.","Die Mehrheit der Bevölkerung hat die Idee inzwischen überprüft und für überzeugend befunden, deshalb wird sie nun in Talkshows diskutiert.","Die Argumente für die Idee waren schon immer stark, deshalb war ihre Durchsetzung nur eine Frage der Zeit.","Die Talkshows haben die Idee populär gemacht, deshalb teilt jetzt die Mehrheit der Zuschauer diese Position."],"correctIndex":0,"explanation":"Die Beobachtung sagt nur, dass die Idee heute besprochen wird, nicht dass sie überzeugt oder mehrheitsfähig geworden ist. Politische Veränderung entsteht oft nicht dadurch, dass man die Wähler überzeugt, sondern dadurch, dass sich das „Fenster der Akzeptanz“ (das Overton-Fenster, benannt nach Joseph P. Overton) langsam verschiebt: Eine Idee kann also vom Undenkbaren zum Diskutablen werden, ohne dass die Mehrheit sie schon befürwortet. Wer aus „wird diskutiert“ auf „wird mehrheitlich befürwortet“ oder „war schon immer richtig“ schließt, verwechselt Sagbarkeit mit Zustimmung bzw. Wahrheit.","coreRule":"⚡ Dass etwas diskutiert wird, heißt nicht, dass es überzeugt hat. Prüfe, ob sich die Argumente geändert haben oder nur das, was als sagbar gilt.","beleg":"Werkstück E.3.5 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Dass eine Idee heute besprochen wird, zeigt nur, dass sie sagbar geworden ist, nicht dass sie überzeugt. Das „Fenster der Akzeptanz“ kann sich verschieben, ohne dass die Mehrheit die Idee schon befürwortet.","prueffrage":"Was hat sich laut Kommentatorin in zwanzig Jahren verändert, und was ist gleich geblieben?","rueckmeldung":[{"option":1,"text":"Gerade weil die Argumente laut Kommentatorin gleich geblieben sind, bleibt offen, wer sich warum umentschieden haben soll. Von Talkshows zu einer überzeugten Mehrheit führt keine belegte Brücke."},{"option":2,"text":"Daran stimmt, dass sich die Argumente laut Kommentatorin kaum geändert haben. Wie stark sie sind, sagt die Beobachtung aber nicht, und aus „wird heute diskutiert“ folgt weder, dass sie gut sind, noch dass die Durchsetzung unvermeidlich war."},{"option":3,"text":"Medien können beeinflussen, was als sagbar gilt. Dass die Zuschauer die Position deshalb mehrheitlich teilen, ist aber eine zusätzliche Behauptung, für die die Beobachtung nichts hergibt."}],"familie":"sagbarkeit-verschiebt-sich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Mackinac Center for Public Policy: The Overton Window","oeffentlich":true,"url":"https://www.mackinac.org/OvertonWindow","abruf":"2026-10-12"},{"typ":"url","kurz":"Lehman, J. G. (2023): The legacy of the Overton Window. Mackinac Center for Public Policy, Blog, 30.06.2023","oeffentlich":true,"url":"https://www.mackinac.org/blog/2023/the-legacy-of-the-overton-window","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1757f7494af97618"}},{"id":"qx-e-052","clusterId":"E","werkstueckRef":"E.3.5","stufe":2,"question":"In einer Gesellschaft, in der Rauchen überall normal ist, gilt ein Rauchverbot in Innenräumen zunächst als politisch undenkbar. Jahre später schlägt eine gemäßigte Gruppe vor: „Vielleicht nicht überall, aber in Krankenhäusern.“ Dieser Vorschlag findet breite Zustimmung. Was erklärt das am besten?","options":["Die Mehrheit war der Idee schon immer zugeneigt und hat nur auf einen mutigen Politiker gewartet.","Hartnäckige Verfechter rückten die Idee vom Undenkbaren zum Radikalen, sodass der Kompromiss nun gemäßigt wirkt.","Krankenhäuser sind rechtlich besondere Orte, an denen Regeln unabhängig von der öffentlichen Meinung durchgesetzt werden.","Radikale Ideen scheitern in der Politik fast immer, deshalb ist ein Kompromiss das Einzige, was durchsetzbar ist."],"correctIndex":1,"explanation":"Politische Ideen gelten nicht aus sich heraus als „radikal“ oder „vernünftig“, sondern immer relativ zu dem, was eine Gesellschaft gerade für akzeptabel hält. Das Overton-Fenster beschreibt diese Bandbreite des öffentlich Akzeptablen. Es kann dazu beitragen, dass eine zuvor undenkbare Forderung wiederholt vorgetragen wird, Studien erscheinen und Medien das Thema aufgreifen: Die Idee rückt dann von „undenkbar“ zu „radikal“. Erst dadurch wirkt ein abgeschwächter Vorschlag wie ein vernünftiger Mittelweg. Zugleich verschiebt sich das Fenster meist durch den langsamen Wandel von Werten und Normen. Niemand muss dafür über Nacht überzeugt werden: Verschoben hat sich der Rahmen dessen, was als akzeptable Meinung gilt. Die anderen Erklärungen halten der Prüfung nicht stand. Eine heimliche Mehrheit erklärt nicht, warum die Idee vorher als karrierebeendend galt. Eine rechtliche Sonderstellung würde nicht erklären, warum der Vorschlag gerade jetzt ankommt und nicht schon früher. Und dass Radikales immer scheitert, widerspricht der Beobachtung, dass eine ursprünglich undenkbare Idee Jahre später gängige Politik werden kann.","coreRule":"⚡ Ein „vernünftiger Kompromiss“ ist oft nur deshalb vernünftig, weil der Rahmen des Akzeptablen sich vorher verschoben hat.","beleg":"Werkstück E.3.5 (Einstieg: Die Debatte, die niemand wollte; Kernidee)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Was als gemäßigt gilt, hängt davon ab, was eine Gesellschaft gerade für akzeptabel hält. Wird das Undenkbare hartnäckig vertreten, kann es zum Radikalen werden, und der abgeschwächte Vorschlag wirkt dann wie ein vernünftiger Mittelweg.","prueffrage":"Wie wurde der Krankenhaus-Vorschlag früher eingeschätzt, und was hat sich zwischen damals und heute verändert?","rueckmeldung":[{"option":0,"text":"Eine stille Mehrheit würde die späte Zustimmung einfach erklären, nicht aber, warum die Idee vorher als undenkbar galt. Verschoben hat sich eher der Rahmen dessen, was man öffentlich vertreten kann."},{"option":2,"text":"Krankenhäuser schützen Kranke, das ist ein guter Grund für strenge Regeln dort. Doch warum kommt der Vorschlag erst Jahre später an? Eine Sonderstellung gab es auch vorher; sie erklärt den Zeitpunkt der Zustimmung nicht."},{"option":3,"text":"Kompromisse haben es in der Politik oft leichter. Dass Radikales „fast immer“ scheitert, passt aber nicht dazu, dass anfangs Undenkbares später gängige Politik werden kann, und erklärt nicht, warum der Kompromiss erst jetzt gemäßigt wirkt."}],"familie":"sagbarkeit-verschiebt-sich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Mackinac Center for Public Policy: The Overton Window","oeffentlich":true,"url":"https://www.mackinac.org/OvertonWindow","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"9b09af12c3896d1e"}},{"id":"qx-e-053","clusterId":"E","werkstueckRef":"E.3.5","stufe":3,"question":"Zwei Beobachter diskutieren über das Overton-Fenster, ein Modell dafür, was in der Öffentlichkeit als akzeptable Meinung gilt. Beobachterin A sagt: „Das Modell zeigt, dass solche Verschiebungen dessen, was gesagt werden darf, gefährlich sind.“ Beobachter B sagt: „Das Modell zeigt, dass solche Verschiebungen gesellschaftlichen Fortschritt bedeuten.“ Wie lässt sich der Denkfehler beider am besten auflösen?","options":["Das Modell beschreibt nur, dass sich Grenzen verschieben; ob das gut oder schlecht ist, hängt von Richtung und Inhalt der Idee ab.","Das Modell ist für die Bewertung einzelner Ideen ungeeignet, weil es Verschiebungen nur beschreibt und deshalb keine Aussage über einzelne Ideen erlaubt.","Das Modell zeigt, dass sich Ideen mit genügend Ausdauer als Mehrheitsmeinung durchsetzen, und damit sind beide Aussagen gleichermaßen widerlegt.","Das Modell bildet ab, wie viele Menschen eine Idee unterstützen, und die Richtung einer Verschiebung lässt sich daher aus der Zustimmung ablesen."],"correctIndex":0,"explanation":"Das Overton-Fenster ist ein neutrales Modell zur Beschreibung von sozialem Wandel: Es sagt, welche Ideen gerade als akzeptabel gelten und wie sich das ändern kann, aber nicht, ob eine Verschiebung wünschenswert ist. Die Gefahr liegt nicht im Modell, sondern in der Richtung der Verschiebung. Dieselbe Mechanik trug das Frauenwahlrecht und Umweltschutzgesetze in den Mainstream, sie dient aber auch extremistischen Bewegungen, die ihre fremdenfeindlichen oder autoritären Ideen als „akzeptabel“ oder „vernünftig“ erscheinen lassen wollen. A schließt von „Verschiebung möglich“ auf „Verschiebung gefährlich“, B auf „Verschiebung gut“. Beides überspringt die Bewertung des Inhalts und der Richtung.","coreRule":"⚡ Ein Modell beschreibt, wie sich etwas verändert, nicht ob es gut ist – bewerten musst du Richtung und Inhalt der Veränderung.","beleg":"Werkstück E.3.5 (Der Kipppunkt; Anwendung & Relevanz)","status":"entwurf","scenario":"Das Overton-Fenster beschreibt, welche Ideen zu einem bestimmten Zeitpunkt als akzeptabel gelten. Früher undenkbare Ideen wie das Frauenwahlrecht, Umweltschutzgesetze oder Rauchverbote in öffentlichen Gebäuden wanderten über Jahrzehnte in den Mainstream. Extremistische Bewegungen versuchen ebenfalls, ihre Positionen schrittweise als „akzeptabel“ oder „vernünftig“ erscheinen zu lassen.","kurz":"Das Modell beschreibt nur, dass sich Grenzen verschieben können, nicht ob das gut ist. Der Fehler liegt im Sprung von „Verschiebung möglich“ zu „gefährlich“ oder „Fortschritt“; entscheidend sind Inhalt und Richtung der Idee.","prueffrage":"Wie würden A und B das Frauenwahlrecht beurteilen, und wie die Vorstöße extremistischer Bewegungen?","rueckmeldung":[{"option":1,"text":"Dass das Modell nichts bewertet, stimmt. Daraus folgt aber nicht, dass es zu einzelnen Ideen schweigt: Es zeigt, wie sie akzeptabel werden können. Die Bewertung muss nur von außen kommen, aus Inhalt und Richtung."},{"option":2,"text":"Dass sich Ideen verbreiten können, ist im Modell angelegt. Es sagt aber nicht, dass sich jede mit Ausdauer durchsetzt, und selbst dann bliebe offen, ob das gut ist. A und B setzen beide eine Bewertung an die Stelle der Beschreibung."},{"option":3,"text":"Beim Fenster geht es darum, was als sagbar und akzeptabel gilt, nicht um Zustimmungszahlen. Selbst hohe Zustimmung würde nichts darüber sagen, ob die Richtung gut oder schlecht ist: Auch extremistische Ideen sollen „vernünftig“ erscheinen."}],"familie":"sagbarkeit-verschiebt-sich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Mackinac Center for Public Policy: The Overton Window","oeffentlich":true,"url":"https://www.mackinac.org/OvertonWindow","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"d70548d20569b695"}},{"id":"qx-e-054","clusterId":"E","werkstueckRef":"E.3.5","stufe":4,"question":"Ein Artikel behauptet: „Joseph Overton hat die sechs Stufen von ‚undenkbar‘ bis ‚Politik‘ entwickelt, und Politiker verschieben das Fenster gezielt selbst.“ Du findest dazu eine Quelle, in der sein Kollege Joseph Lehman (selbst Mitarbeiter des Thinktanks, in dem Overton arbeitete) Overtons Rolle beschreibt. Lehman schreibt: Overton habe das Konzept Mitte der 1990er-Jahre entwickelt, Lehman selbst habe es nach Overtons Tod benannt und formalisiert; Overton habe dazu nie eine Arbeit veröffentlicht, und der Thinktank zeige das Fenster heute ohne die sechs Stufen. Politiker verschöben es nur selten selbst, meist wandle es sich durch den langsamen Wandel von Werten und Normen. Was ist die am besten begründete Schlussfolgerung für den Artikel?","options":["Die Behauptung ist in beiden Teilen überzogen: Die Sechs-Stufen-Skala lässt sich Overton nicht als eigener Wortlaut zuschreiben, und dass Politiker das Fenster gezielt verschieben, ist eher die Ausnahme.","Die Behauptung ist im Kern richtig, denn wer ein Konzept entwickelt, hat auch seine gebräuchliche Form geprägt, und Politiker steuern Wertewandel in der Regel selbst.","Die Behauptung ist falsch, weil das Modell eigentlich von Lehman stammt: Er hat es lange vor Overtons Tod ausgearbeitet und danach bekannt gemacht.","Die Behauptung lässt sich nicht beurteilen, solange nicht geklärt ist, ob der Thinktank mit seiner heutigen Darstellung ohne Stufen nicht einfach nur Overton widerspricht."],"correctIndex":0,"explanation":"Die Quelle stammt von einem direkten Kollegen Overtons und beschreibt dessen Rolle nüchtern: Overton entwickelte das Konzept Mitte der 1990er-Jahre, Lehman benannte und formalisierte es erst nach Overtons Tod, und Overton hat dazu nie eine Arbeit veröffentlicht. Die beliebte Sechs-Stufen-Skala ist Overtons eigener Wortlaut nicht, sondern eine spätere, gebräuchliche Ausarbeitung; auch der Thinktank selbst zeigt das Fenster heute ohne diese Stufen. Beim zweiten Teil gilt: Politiker können das Fenster mitunter selbst verschieben, aber das ist selten; meist wandeln sich Werte und Normen langsam, und Lehman nennt als Hebel Thinktank-Forschung, Analyse und Debatte. Der Artikel schreibt Overton also die Skala als eigenes Werk zu und überschätzt die Rolle der Politiker. Ihn deshalb ganz zu verwerfen oder ihn für unbeurteilbar zu halten, wäre jedoch ebenfalls unbegründet: Die Quelle liefert genug, um beide Teile einzuordnen.","coreRule":"⚡ Prüfe bei einem bekannten Modell, wie viel davon vom Urheber stammt und wie viel später dazugekommen ist.","beleg":"Werkstück E.3.5 (Kontext & Tiefe); Fn. gl-e-overton (Lehman 2023, Mackinac Center)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Laut Overtons Kollegen Lehman entwickelte Overton das Konzept, die Sechs-Stufen-Skala ist aber nicht sein eigener Wortlaut, und Politiker verschieben das Fenster nur selten selbst. Der Artikel überzieht also beide Teile seiner Behauptung.","prueffrage":"Wer hat laut Quelle wann was zum Konzept beigetragen, und wer verschiebt das Fenster nach Lehmans Darstellung meistens?","rueckmeldung":[{"option":1,"text":"Dass Overton das Konzept entwickelt hat, stimmt. Daraus folgt aber nicht, dass die Sechs-Stufen-Form von ihm stammt: Die kam laut Quelle später dazu. Auch Politiker steuern den Wertewandel selten selbst; meist verändern sich Werte und Normen langsam."},{"option":2,"text":"Lehman hat das Konzept tatsächlich benannt und formalisiert. Das geschah aber erst nach Overtons Tod, und entwickelt hat die Idee Overton selbst. Den Artikel deshalb als falsch zu verwerfen, geht über das hinaus, was die Quelle hergibt."},{"option":3,"text":"Die Quelle eines direkten Kollegen genügt für eine Einordnung. Dass der Thinktank das Fenster heute ohne Stufen zeigt, widerspricht Overton nicht, denn er hat dazu nichts veröffentlicht; es passt dazu, dass die Skala nicht sein Wortlaut ist."}],"familie":"zitat-am-original-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Lehman, J. G. (2023): The legacy of the Overton Window. Mackinac Center for Public Policy, Blog, 30.06.2023","oeffentlich":true,"url":"https://www.mackinac.org/blog/2023/the-legacy-of-the-overton-window","abruf":"2026-10-12"},{"typ":"url","kurz":"Mackinac Center for Public Policy: The Overton Window","oeffentlich":true,"url":"https://www.mackinac.org/OvertonWindow","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0aca52ea3d4893dd"}},{"id":"qx-e-055","clusterId":"E","werkstueckRef":"E.3.6","stufe":1,"question":"Eine Freundin sagt: „Ich habe es genau gesehen, ich weiß, was passiert ist. Meine Augen haben doch einfach aufgezeichnet, was da war.“ Welche Antwort trifft die Lage am besten?","options":["Wahrnehmung ist eine Vermutung des Gehirns aus lückenhaften Sinnesdaten und Erwartungen, und im Dämmerlicht kann die Erwartung gewinnen.","Wer etwas klar sieht, das gar nicht da ist, muss psychisch krank sein, denn nur dann täuscht die Wahrnehmung.","Das Bild wurde ihr von außen eingegeben, etwa durch Suggestion, denn ohne fremden Einfluss sieht man nichts Falsches.","Das Auge nimmt die Umgebung wie eine Kamera auf, und das Gehirn spielt sie nur leicht verrauscht wieder ab, ohne etwas zu ergänzen."],"correctIndex":0,"explanation":"Das Gehirn arbeitet als Vorhersagemaschine: Es erstellt ständig Modelle dessen, was es zu sehen erwartet, und die Sinnesdaten dienen vor allem dazu, diese Vorhersagen zu korrigieren. Sind die Daten mehrdeutig (Dämmerung, ein menschenähnlicher Umriss), gewinnt oft die Erwartung. Dazu muss weder eine Krankheit noch fremder Einfluss im Spiel sein: Schon der blinde Fleck im Sehfeld zeigt, dass das Gehirn Lücken unbemerkt mit der Umgebung auffüllt. Das Gefühl von Klarheit sagt deshalb nichts darüber, ob die Wahrnehmung stimmt. Wahrnehmung ist keine passive Aufzeichnung, sondern eine „kontrollierte Halluzination“: eine beste Vermutung des Gehirns, die mit den Sinnesdaten abgeglichen wird.","coreRule":"⚡ Wir sehen nicht, was da ist, sondern die beste Vermutung unseres Gehirns darüber. Wie sicher sich eine Wahrnehmung anfühlt, sagt nichts darüber, ob sie stimmt.","beleg":"Werkstück E.3.6 (Kernidee; Kontext & Tiefe); Fn. gl-e-halluzination (Grush 2004, S. 393; Seth 2016)","status":"entwurf","scenario":"Beim Spaziergang im Dämmerlicht erschrickt jemand vor einem „Mann“ am Wegrand. Beim Näherkommen ist es ein Busch. Hinterher beharrt die Person darauf, sie habe die ganze Zeit klar einen Menschen gesehen.","kurz":"Wahrnehmung ist eine Vermutung des Gehirns aus lückenhaften Daten und Erwartungen, keine Aufzeichnung. Der Fehler liegt darin, Klarheit mit Richtigkeit zu verwechseln: Im Dämmerlicht kann die Erwartung gewinnen.","prueffrage":"Was war im Dämmerlicht tatsächlich zu erkennen, bevor die Person näher kam?","rueckmeldung":[{"option":1,"text":"Dass hier eine Täuschung vorliegt, stimmt. Krankhaft ist sie aber nicht: Solche Fehlwahrnehmungen können bei jedem Menschen entstehen, wenn die Sinnesdaten mehrdeutig sind, etwa in der Dämmerung."},{"option":2,"text":"Suggestion kann Wahrnehmung tatsächlich beeinflussen, doch hier deutet nichts auf fremden Einfluss hin. Auch ganz ohne ihn ergänzt das Gehirn Mehrdeutiges selbst, etwa einen Umriss in der Dämmerung zu einem Menschen."},{"option":3,"text":"Das ist die Kameravorstellung, die die Freundin selbst äußert. Das Gehirn spielt nicht nur ab, es sagt voraus und füllt Lücken auf, etwa beim blinden Fleck. Das Ergänzen läuft unbemerkt ab, ein „Rauschen“ allein erklärt den Busch als Mann nicht."}],"familie":"erinnerung-ist-rekonstruktion","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Powers, A. R.; Kelley, M.; Corlett, P. R. (2016): Hallucinations as Top-Down Effects on Perception. Biological Psychiatry: CNNI 1(5) (Autorenmanuskript frei in PMC5469545)","oeffentlich":true,"doi":"10.1016/j.bpsc.2016.04.003"},{"typ":"url","kurz":"Seth, A. K. (2016): The real problem. Aeon, 2.11.2016","oeffentlich":true,"url":"https://aeon.co/essays/the-hard-problem-of-consciousness-is-a-distraction-from-the-real-one"},{"typ":"doi","kurz":"Grush, R. (2004): The emulation theory of representation. Behavioral and Brain Sciences 27(3)","oeffentlich":false,"doi":"10.1017/S0140525X04000093"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"958aa4be3e55322e"}},{"id":"qx-e-056","clusterId":"E","werkstueckRef":"E.3.6","stufe":2,"question":"Welche Schlussfolgerung ist am besten begründet?","options":["Ihre Beschwerden sind echt; die Einzelheiten der Entführung stammen aber vermutlich aus Suggestion und bekannten Bildern, mit denen das Gehirn Lücken füllte.","Ihre Beschwerden sind echt; deshalb müssen auch die Einzelheiten der Entführung tatsächlich so geschehen sein, wie sie berichtet.","Ihre Beschwerden sind vorgetäuscht; die Einzelheiten der Entführung hat sie vermutlich bewusst erfunden, um Aufmerksamkeit zu bekommen.","Ihre Beschwerden sind echt; die Lebhaftigkeit der Erinnerung zeigt, dass die Einzelheiten der Entführung zuverlässig stimmen müssen."],"correctIndex":0,"explanation":"Hier greifen drei Dinge ineinander: echte Symptome, ein realer, furchteinflößender Zustand (Schlafparalyse: wach sein, sich nicht bewegen können, oft mit Halluzinationen) und ein Rahmen, der falsche Erinnerungen begünstigt. Die Erwartung des Therapeuten, die Hypnose und die bekannten Bilder aus Filmen und Büchern liefern dem Gehirn das Material, um die unzusammenhängenden Sinnesfetzen zu einer stimmigen Geschichte zu verbinden. Das Gehirn ruft dann nicht eine Erinnerung ab, sondern erzeugt sie. Echte Symptome beweisen nicht, dass die berichtete Ursache stimmt: Angst und Schlaflosigkeit treten auch dann auf, wenn die Erinnerung konstruiert ist. Auch Lebhaftigkeit und Emotionalität sagen wenig über Wahrheit; starke Gefühle können Erinnerungen festigen, aber ebenso anfälliger für Verzerrung machen. Auch eine bewusste Erfindung ist die schlechtere Erklärung: Die Symptome sind echt, und die Erinnerungen sind für die Betroffenen real und emotional echt. In der Laborstudie von Clancy u. a. (2002) bildeten Menschen mit „wiedergefundenen“ Entführungserinnerungen im Gedächtnistest häufiger falsche Erinnerungen als eine Vergleichsgruppe.","coreRule":"⚡ Dass sich eine Erinnerung echt anfühlt, beweist nicht, dass sie echt ist.","beleg":"Werkstück E.3.6 (Einstieg: Das Zeugnis des Entführten); Fn. gl-e-clancy (Clancy u. a. 2002, S. 455–461; Clancy 2005)","status":"entwurf","scenario":"Eine Frau berichtet, sie sei nachts von kleinen grauen Wesen an Bord eines Raumschiffs gebracht und dort untersucht worden. Sie leidet unter echter Angst und Schlaflosigkeit, und die Erinnerung fühlt sich für sie sehr lebhaft und real an. Details fielen ihr erst in Sitzungen bei einem Therapeuten unter Hypnose ein, der zuvor gesagt hatte, genau solche Erlebnisse seien bei ihren Beschwerden häufig. In Filmen und Büchern kennt sie das Motiv schon lange. Außerdem erwacht sie manchmal nachts bei vollem Bewusstsein und kann sich minutenlang nicht bewegen.","kurz":"Die Beschwerden sind echt, doch sie belegen nicht, dass die berichtete Ursache stimmt. Schlafparalyse, die Erwartung des Therapeuten, Hypnose und bekannte Bilder können dem Gehirn das Material liefern, aus dem es eine stimmige, aber konstruierte Erinnerung formt.","prueffrage":"Wann und unter welchen Umständen sind die Einzelheiten der Erinnerung zum ersten Mal aufgetaucht?","rueckmeldung":[{"option":1,"text":"Dass Angst und Schlaflosigkeit echt sind, steht außer Frage. Sie treten aber auch auf, wenn die Erinnerung konstruiert ist, und sagen deshalb nichts darüber, ob die berichtete Ursache wirklich geschah."},{"option":2,"text":"Bewusstes Erfinden ist die schwächere Erklärung: Angst und Schlaflosigkeit sind echt, und die Erinnerung ist für die Betroffene real. Schlafparalyse, Suggestion und bekannte Bilder können die Einzelheiten ohne jede Täuschungsabsicht erklären."},{"option":3,"text":"Eine sehr lebhafte, emotionale Erinnerung fühlt sich wahr an, sagt über ihre Richtigkeit aber wenig. Starke Gefühle können Erinnerungen festigen, sie aber auch leichter verzerrbar machen."}],"familie":"erinnerung-ist-rekonstruktion","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Clancy, S. A.; McNally, R. J.; Schacter, D. L.; Lenzenweger, M. F.; Pitman, R. K. (2002): Memory distortion in people reporting abduction by aliens. Journal of Abnormal Psychology 111(3)","oeffentlich":false,"doi":"10.1037/0021-843X.111.3.455"},{"typ":"doi","kurz":"Bhalerao, V. u. a. (2024): Recent Insights Into Sleep Paralysis: Mechanisms and Management. Cureus 16(7), e65413","oeffentlich":true,"doi":"10.7759/cureus.65413"},{"typ":"doi","kurz":"Murphy, G. u. a. (2023): Lost in the mall again. Memory 31(6)","oeffentlich":true,"doi":"10.1080/09658211.2023.2198327"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"43c5f81f93dab3a0"}},{"id":"qx-e-057","clusterId":"E","werkstueckRef":"E.3.6","stufe":3,"question":"Wie ordnest du den Wert dieser Aussage ein?","options":["Sehr sichere Aussagen sind unter sauberen Umständen meist unzuverlässig, weil das Gedächtnis bei jedem Abruf neu geschrieben wird.","Sehr sichere Aussagen sind unter sauberen Umständen treffsicher, bei unfairen Gegenüberstellungen oder späterer Beeinflussung nicht.","Sehr sichere Aussagen sind auch bei unfairen Gegenüberstellungen meist zuverlässig, weil Sicherheit das beste Anzeichen für Treffsicherheit ist.","Sehr sichere Aussagen sind unter sauberen Umständen eher bei Kindern zuverlässig, weil Erwachsene durch Erwartungen und Vorurteile stärker beeinflusst werden."],"correctIndex":1,"explanation":"Beides ist belegt: In den USA waren falsche Augenzeugen-Identifizierungen an rund zwei Dritteln der später per DNA-Test aufgehobenen Fehlurteile beteiligt (Innocence Project: 69 % von 375 Entlastungen). Das hat Reformen bei Gegenüberstellungen angestoßen. Unter sauberen Bedingungen, also bei erster, unbeeinflusster Gegenüberstellung und sofort festgehaltener Sicherheit, sind sehr sichere Identifizierungen laut Wixted und Wells (2017) aber bemerkenswert treffsicher. Unzuverlässig werden sie vor allem durch unfaire Gegenüberstellungen und spätere Beeinflussung. Der Verteidiger schließt von „das Gedächtnis ist formbar“ auf „jede Aussage ist wertlos“, doch aus einer Schwäche folgt nicht, dass sie unter allen Bedingungen gleich stark wirkt. Der Wert einer sicheren Aussage hängt von den Umständen ab, unter denen sie zustande kam. Zur Frage der Kinder: Laut Wixted und Wells (2017), einer Quelle in den Fußnoten des Buchs, kann der Zusammenhang zwischen Sicherheit und Treffsicherheit bei Kindern bis etwa 13 Jahren schwächer sein. Das macht Aussagen von Kindern nicht zuverlässiger, und Erwachsene sind unter sauberen Bedingungen gerade treffsicher. Die Annahme, nur Kinder seien zuverlässig, ist deshalb falsch.","coreRule":"⚡ Nicht nur wie sicher ein Zeuge ist, sondern unter welchen Bedingungen er sich festgelegt hat, zählt.","beleg":"Werkstück E.3.6 (Anwendung & Relevanz: In der Justiz); Fn. gl-e-dna (Innocence Project, abgerufen 06.10.2026); Fn. gl-e-wixted (Wixted & Wells 2017, S. 10, 19, 39)","status":"entwurf","scenario":"Ein Zeuge ist sich seiner Identifizierung des Täters „hundertprozentig“ sicher. Er hat sich schon bei der ersten Gegenüberstellung festgelegt, kein Ermittler hat ihn dabei beeinflusst, und seine Sicherheit wurde sofort festgehalten. Der Verteidiger entgegnet: „Das Gedächtnis ist ohnehin konstruiert, also ist jede Zeugenaussage wertlos.“","kurz":"Der Wert einer sicheren Aussage hängt von den Umständen ab: Erste, unbeeinflusste Gegenüberstellung und sofort festgehaltene Sicherheit sprechen für Treffsicherheit. Die Formbarkeit des Gedächtnisses macht nicht jede Aussage unter allen Bedingungen wertlos.","prueffrage":"Unter welchen Umständen kam die Identifizierung zustande, und was spricht in diesem Fall für oder gegen Beeinflussung?","rueckmeldung":[{"option":0,"text":"Dass das Gedächtnis formbar ist, stimmt. Daraus folgt aber nicht, dass saubere, sofort festgehaltene Aussagen meist falsch sind: Unter solchen Bedingungen sind sehr sichere Identifizierungen gerade bemerkenswert treffsicher."},{"option":2,"text":"Sicherheit kann ein gutes Zeichen sein, aber nur unter sauberen Umständen. Nach unfairen Gegenüberstellungen oder späterer Beeinflussung kann sich auch eine falsche Erinnerung sehr sicher anfühlen."},{"option":3,"text":"Bei Kindern kann der Zusammenhang zwischen Sicherheit und Treffsicherheit sogar schwächer sein. Erwachsene sind unter sauberen Bedingungen gerade treffsicher; entscheidend sind die Umstände, nicht das Alter."}],"familie":"erinnerung-ist-rekonstruktion","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Innocence Project: DNA Exonerations in the United States (1989–2020)","oeffentlich":true,"url":"https://innocenceproject.org/dna-exonerations-in-the-united-states/","abruf":"2026-10-06"},{"typ":"doi","kurz":"Wixted, J. T.; Wells, G. L. (2017): The Relationship Between Eyewitness Confidence and Identification Accuracy: A New Synthesis. Psychological Science in the Public Interest 18(1)","oeffentlich":false,"doi":"10.1177/1529100616686966"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"87e4f02982505fb9"}},{"id":"qx-e-058","clusterId":"E","werkstueckRef":"E.3.6","stufe":4,"question":"Du siehst in einem Video einen Mund, der „GA“ formt, hörst aber den Ton „BA“ und nimmst „DA“ wahr. Schließt du die Augen, hörst du klar „BA“. Eine Freundin schließt daraus: „Dann hört mein Gehirn eben immer genau das, was der Mund zeigt.“ Was folgt aus der Beobachtung wirklich?","options":["Das Gehirn verrechnet Bild und Ton zu einer gemeinsamen Wahrnehmung; die Täuschung fällt je nach Person und Video unterschiedlich stark aus, bei manchen bleibt sie ganz aus.","Das Gehirn übernimmt immer das, was der Mund zeigt; die Täuschung tritt deshalb bei allen Menschen und in jedem Video gleich stark auf.","Das Gehirn bevorzugt meist den Ton gegenüber dem Bild; wer „DA“ hört, hat sich verhört, und die Täuschung fällt deshalb bei allen Menschen und in jedem Video gleich schwach aus.","Das Gehirn bildet zwei getrennte Wahrnehmungen, die sich erst später im Gedächtnis zu einer verbinden; die Täuschung tritt deshalb bei allen Menschen und in jedem Video gleich verzögert auf."],"correctIndex":0,"explanation":"Die Beobachtung enthält zwei Hinweise. Erstens: Wahrgenommen wird „DA“, obwohl weder das Bild („GA“) noch der Ton („BA“) diese Silbe liefert. Wäre es immer das Bild, würdest du „GA“ wahrnehmen, wäre es immer der Ton, „BA“. Das spricht dafür, dass das Gehirn beide Sinnesdaten zu einem Kompromiss verrechnet, statt einfach eine Quelle abzulesen. Zweitens: Bei geschlossenen Augen hörst du klar „BA“. Der Ton selbst hat sich also nicht verändert; das Bild hat die Wahrnehmung mitgeformt. Auch die Behauptung, die Wahrnehmung entstehe erst später im Gedächtnis, passt nicht dazu: Der Effekt entsteht dadurch, dass Sinnesdaten bei der Wahrnehmung verrechnet werden, nicht durch eine spätere Verknüpfung im Gedächtnis. Dazu kommt eine Einschränkung, die der Befund selbst liefert: In einer Studie mit 165 Erwachsenen lag die Täuschungsrate je Person zwischen 0 und 100 % und je Video zwischen 17 und 58 % (Basu Mallick u. a. 2015). Ein Effekt, der so stark streut, darf nicht als Naturgesetz für alle behandelt werden. Wer ihn ohne diese Einschränkung verallgemeinert, überzieht den Befund.","coreRule":"⚡ Wahrnehmung ist keine Aufzeichnung: Das Gehirn verrechnet mehrere Sinnesdaten zu einem Ergebnis, und wie stark das wirkt, unterscheidet sich von Mensch zu Mensch.","beleg":"Werkstück E.3.6 (Die Schmiede-Übung); Fn. gl-e-mcgurk (McGurk & MacDonald 1976; Basu Mallick u. a. 2015, S. 1299–1307)","status":"entwurf","scenario":"Ein Experiment zur Wahrnehmung: Bild und Ton passen absichtlich nicht zusammen. Viele Menschen nehmen dabei eine Silbe wahr, die weder im Bild noch im Ton vorkommt. Bei geschlossenen Augen verschwindet der Effekt. Wie stark die Täuschung ausfällt, ist von Person zu Person und von Video zu Video sehr verschieden; manche erleben sie nie.","kurz":"Wahrgenommen wird „DA“, das weder im Bild („GA“) noch im Ton („BA“) steckt; das Gehirn verrechnet also beide Eindrücke. Wie stark die Täuschung ausfällt, schwankt aber je nach Person und Video, manche erleben sie nie.","prueffrage":"Was würdest du hören, wenn nur eine der beiden Quellen die Wahrnehmung bestimmte, und was hörst du tatsächlich?","rueckmeldung":[{"option":1,"text":"Dass das Bild mitwirkt, zeigt der Wegfall des Effekts bei geschlossenen Augen. Entschiede aber immer der Mund, würdest du „GA“ wahrnehmen, nicht „DA“; zudem streut der Effekt stark, manche erleben ihn nie."},{"option":2,"text":"Der Ton ist tatsächlich beteiligt, bei geschlossenen Augen hört man klar „BA“. „DA“ ist aber kein zufälliges Verhören, sondern Folge der Verrechnung mit dem Bild, und gleich schwach bei allen ist der Effekt nicht: Er streut stark."},{"option":3,"text":"Eine spätere Verknüpfung im Gedächtnis könnte „DA“ zwar erklären, doch die Verrechnung geschieht schon bei der Wahrnehmung. Ein bei allen gleich verzögerter Effekt widerspricht zudem der starken Streuung."}],"familie":"erinnerung-ist-rekonstruktion","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Basu Mallick, D.; Magnotti, J. F.; Beauchamp, M. S. (2015): Variability and stability in the McGurk effect. Psychonomic Bulletin & Review 22(5) (frei in PMC4580505)","oeffentlich":true,"doi":"10.3758/s13423-015-0817-4"},{"typ":"doi","kurz":"McGurk, H.; MacDonald, J. (1976): Hearing Lips and Seeing Voices. Nature 264","oeffentlich":false,"doi":"10.1038/264746a0"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"0bf8d374710e73f4"}},{"id":"qx-e-059","clusterId":"E","werkstueckRef":"E.3.7","stufe":1,"question":"Welche Antwort auf die Behauptung ist am wirksamsten?","options":["Sie zählt Punkt für Punkt auf, welche Aussagen des Redners nicht stimmen, und beendet ihren Beitrag, sobald der letzte Fehler genannt ist.","Sie erklärt: „Der Feind ist keine Bande, sondern unsere Unachtsamkeit. Lasst uns gemeinsam Nachbarschaftsrunden einrichten, Schlösser nachrüsten und aufeinander achten.“","Sie wiederholt die Behauptung des Redners mehrmals in eigenen Worten, damit alle sie noch einmal hören und selbst als unplausibel erkennen.","Sie hält dagegen: „Es gibt gar keine Bedrohung. Wer sich fürchtet, überreagiert und sollte sich beruhigen, statt dem Redner nachzulaufen.“"],"correctIndex":1,"explanation":"Eine reine Widerlegung zerstört die Geschichte des Redners, lässt aber eine Leere zurück: Die Angst bleibt, und das Gehirn füllt die Lücke oft wieder mit der vertrauten Erklärung. Wirksamer ist eine wahre Alternative, die die Lücke schließt, das Bedürfnis nach Sicherheit ernst nimmt und den Menschen eine aktive Rolle gibt. Genau das leistet die Antwort mit den Nachbarschaftsrunden: Sie bleibt bei den Fakten, benennt eine bessere Erklärung und zeigt, was die Gemeinschaft selbst tun kann. Auch die übrigen Antworten schließen die Lücke nicht und gehen auf die Angst nicht ein: Sie liefern weder eine bessere Erklärung noch eine aktive Rolle für die Menschen.","coreRule":"⚡ Wer eine falsche Geschichte nur zerstört, lässt eine Lücke; fülle sie mit der wahren, die Handlungsmacht gibt.","quote":"Was ist die wahre, aber ebenso fesselnde und ermächtigende Geschichte, die ich an ihrer Stelle erzählen kann?","quoteLabel":"Denkfrage:","beleg":"Werkstück E.3.7 (Einstieg: Die Brandstifter und der Gärtner; Kernidee; Kontext & Tiefe; Härten im Feuer: Aktivierungs-Frage)","status":"entwurf","scenario":"In einer Kleinstadt häufen sich Einbrüche. Auf einer Bürgerversammlung behauptet ein Redner: „Das sind organisierte Banden von außerhalb! Nur wenn ihr mir folgt und meine Wachtruppe bezahlt, seid ihr sicher.“ Viele nicken, denn die Geschichte gibt ihrer Angst einen klaren Schuldigen. Die Polizeistatistik zeigt: Die meisten Einbrüche geschahen durch offene Fenster und unverschlossene Türen, die Täter waren überwiegend Gelegenheitstäter aus der Gegend. Eine Anwohnerin meldet sich zu Wort.","kurz":"Nur zu widerlegen, lässt die Angst ohne Erklärung zurück, und die vertraute Schuldzuweisung füllt die Lücke dann oft wieder. Die Anwohnerin bleibt bei den Fakten, bietet eine bessere Erklärung und gibt der Gemeinschaft etwas Konkretes zu tun.","prueffrage":"Womit verlassen die Zuhörenden den Saal, wenn die Anwohnerin fertig ist, und was davon hilft ihnen gegen die Einbrüche?","rueckmeldung":[{"option":0,"text":"Die Fehler des Redners aufzuzeigen ist richtig und nötig. Danach steht aber nur noch die Angst im Raum, ohne Ersatzerklärung und ohne Handlungsmöglichkeit, und genau in diese Lücke kann die alte Geschichte oft zurückkehren."},{"option":2,"text":"Erneutes Hören soll Klarheit schaffen, doch ohne Gegenbeleg oder Alternative wird die Behauptung vor allem noch einmal verbreitet. Wiederholung kann sie sogar vertrauter wirken lassen. Die Angst bleibt ohne Antwort."},{"option":3,"text":"In der Absicht, nicht dem Redner nachzulaufen, steckt ein wahrer Kern. Die Bedrohung ist aber real, sie geht nur überwiegend von Gelegenheitstätern aus, und wer die Angst als Überreaktion abtut, nimmt sie nicht ernst."}],"familie":"luecke-fuellen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Lewandowsky, S.; Cook, J.; Ecker, U. K. H. u. a. (2020): The Debunking Handbook 2020","oeffentlich":true,"doi":"10.17910/b7.1182"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"35fe170dcbe30d79"}},{"id":"qx-e-060","clusterId":"E","werkstueckRef":"E.3.7","stufe":2,"question":"Dein Freund hält Kondensstreifen am Himmel für „Chemtrails“, mit denen heimlich etwas versprüht wird. Welche Reaktion hat die beste Aussicht, seine Meinung tatsächlich zu verändern?","options":["Ihm erklären, wie Kondensstreifen entstehen und warum sie je nach Luftfeuchtigkeit unterschiedlich lange bleiben.","Ihm klar sagen, dass es „Chemtrails“ nicht gibt, und diese Aussage bei jedem neuen Argument von ihm wiederholen.","Ihm eine Liste mit den Fehlern in seinen Quellen schicken und ihn bitten, die Behauptung aufzugeben.","Das Thema vermeiden, damit er sich nicht als Außenseiter fühlt, und hoffen, dass er es mit der Zeit vergisst."],"correctIndex":0,"explanation":"Wer nur widerspricht oder Fehler aufzählt, nimmt dem Freund eine Erklärung weg, ohne eine neue anzubieten. Gerade das Rätsel, das ihn beschäftigt (warum bleiben manche Streifen stundenlang, andere nicht?), bleibt dann offen, und das Gehirn füllt solche Lücken oft mit der alten, vertrauten Behauptung. Forschung zum Richtigstellen von Falschinformationen (Lewandowsky u. a., 2020) zeigt: Eine sachliche Alternativerklärung, die die Lücke schließt, wirkt besser als ein bloßes Dementi. Für Kondensstreifen liefert diese Alternativerklärung die Atmosphärenphysik. Dass ein Widerspruch den Irrtum sogar verstärkt, kommt zwar nur selten vor, doch auch ohne diesen Effekt bleibt das Dementi schwächer als die Erklärung. Das Thema zu vermeiden lässt die Lücke ebenfalls offen: Die Behauptung trifft dann auf niemanden, der ihr etwas Besseres entgegensetzt.","coreRule":"⚡ Wer eine Behauptung widerlegen will, braucht mehr als ein Nein: Eine bessere, nachprüfbare Erklärung füllt die Lücke, die sonst die alte Behauptung wieder füllt.","beleg":"Werkstück E.3.7 (Anwendung & Relevanz: Verschwörungsmythen; Red Flags; Kontext & Tiefe, Fn. gl-e-luecke: Lewandowsky u. a. 2020, Debunking Handbook; Backfire-Effekt selten)","status":"entwurf","scenario":"Du stehst mit einem Freund draußen, am Himmel ziehen sich weiße Streifen. Er sagt: „Siehst du? Die sprühen da was aus. Warum bleiben manche Streifen stundenlang und andere verschwinden sofort?“","kurz":"Wer nur widerspricht, lässt seine Frage offen, und diese Lücke füllt oft die alte Idee. Wie Kondensstreifen entstehen und warum sie je nach Luftfeuchtigkeit verschieden lange bleiben, beantwortet genau diese Frage und wirkt deshalb besser als ein Dementi.","prueffrage":"Was genau hat dein Freund gefragt, als ihr die Streifen am Himmel gesehen habt?","rueckmeldung":[{"option":1,"text":"Die Aussage stimmt, und klar zu widersprechen ist legitim. Sie lässt aber seine Frage unbeantwortet, warum manche Streifen so lange bleiben. Wiederholung füllt diese Lücke nicht, ein Dementi bleibt schwächer als eine Erklärung."},{"option":2,"text":"Quellen zu prüfen ist grundsätzlich sinnvoll. Eine Fehlerliste nimmt ihm aber nur etwas weg und bietet nichts an, das erklärt, was er am Himmel sieht. Damit bleibt seine Frage offen, und die Bitte, aufzugeben, stößt ins Leere."},{"option":3,"text":"Rücksicht auf seine Gefühle ist ein guter Gedanke. Doch die Lücke bleibt dann offen, und die Behauptung trifft auf niemanden, der ihr etwas Besseres entgegensetzt."}],"familie":"luecke-fuellen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Lewandowsky, S.; Cook, J.; Ecker, U. K. H. u. a. (2020): The Debunking Handbook 2020","oeffentlich":true,"doi":"10.17910/b7.1182"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"2141f18d6ada8d0c"}},{"id":"qx-e-061","clusterId":"E","werkstueckRef":"E.3.7","stufe":3,"question":"Was folgt aus diesem Befund für die Planung einer Richtigstellung?","options":["Die Erzählform bringt für sich genommen keinen Vorteil; entscheidend ist, wie gut die Richtigstellung die Lücke im Weltbild mit einer Erklärung füllt.","Die Erzählform bringt einen klaren Vorteil, weil Geschichten Menschen emotional erreichen und deshalb jede Richtigstellung wirksamer machen.","Die Erzählform sollte vermieden werden, weil Geschichten den Irrtum meist zusätzlich verstärken und das Gerücht damit festigen.","Die Erzählform ist nur bei jungen Zielgruppen sinnvoll, weil Erwachsene auf sachliche Texte grundsätzlich immer besser ansprechen."],"correctIndex":0,"explanation":"Aus dem Befund folgt: Wenn eine erzählte und eine sachliche Richtigstellung gleich viel erklären, wirken sie ähnlich gut. Der Mitarbeiter schließt also von „Geschichte“ auf „wirksamer“, ohne dass das belegt ist. Wirksam ist eine sachliche Alternativerklärung, die die entstandene Lücke füllt; ohne sie greift das Gehirn oft wieder zur vertrauten Falschinformation. Dass Richtigstellungen den Irrtum sogar verstärken (Backfire-Effekt), kommt dagegen nur selten vor. Und eine pauschale Aussage über Altersgruppen trägt der Befund nicht. Die Geschichtenform kann Aufmerksamkeit und Merkbarkeit unterstützen, ersetzt aber nie die erklärende Substanz.","coreRule":"⚡ Frage bei einer Richtigstellung zuerst, welche Erklärung die Lücke füllt, nicht, wie spannend sie erzählt ist.","beleg":"Werkstück E.3.7 (Kontext & Tiefe); Fn. gl-e-erzaehlform (Ecker, Butler, Hamby 2020, Abstract); Fn. gl-e-luecke (Lewandowsky u. a. 2020, PDF-S. 9 und 12)","status":"entwurf","scenario":"Eine Gesundheitsbehörde will ein hartnäckiges Gerücht über einen Impfstoff richtigstellen. Ein Mitarbeiter schlägt vor: „Wir packen die Richtigstellung in eine spannende Geschichte, dann wirkt sie von selbst besser als ein nüchterner Text.“ In drei vorregistrierten Experimenten mit zusammen 2.279 Teilnehmenden zeigte sich: Erzählte Richtigstellungen wirkten nicht besser als sachlich formulierte, sofern beide gleich viel erklärten.","kurz":"Bei gleicher Erklärleistung wirken erzählte und sachliche Richtigstellungen ähnlich gut. Der Fehler liegt im Schluss von „Geschichte“ auf „wirksamer“. Entscheidend ist eine Erklärung, die die Lücke im Weltbild füllt.","prueffrage":"Was wurde in den drei Experimenten miteinander verglichen, und welcher Unterschied zeigte sich dabei?","rueckmeldung":[{"option":1,"text":"Geschichten können tatsächlich Aufmerksamkeit wecken und gut im Gedächtnis bleiben. Aber bei gleich viel Erklärung zeigte sich kein Vorteil der Erzählform; dass sie jede Richtigstellung wirksamer macht, belegt der Befund nicht."},{"option":2,"text":"Ein Nachteil der Erzählform zeigte sich in den Experimenten gar nicht, nur fehlte ein Vorteil. Dass Richtigstellungen den Irrtum sogar verstärken, kommt zudem nur selten vor und taugt nicht als Faustregel gegen Geschichten."},{"option":3,"text":"Über Altersgruppen sagt der Befund nichts, daher lässt sich daraus keine Regel für Junge oder Erwachsene ableiten. Dass sachliche Texte bei Erwachsenen „grundsätzlich immer“ besser ankommen, wäre zudem eine viel zu absolute Aussage."}],"familie":"luecke-fuellen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Ecker, U. K. H.; Butler, L. H.; Hamby, A. (2020): You don't have to tell a story! Cognitive Research: Principles and Implications 5, Art. 64","oeffentlich":true,"doi":"10.1186/s41235-020-00266-x"},{"typ":"doi","kurz":"Lewandowsky, S.; Cook, J.; Ecker, U. K. H. u. a. (2020): The Debunking Handbook 2020","oeffentlich":true,"doi":"10.17910/b7.1182"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"9546701582c74b1d"}},{"id":"qx-e-062","clusterId":"E","werkstueckRef":"E.3.7","stufe":4,"question":"Du willst eine verbreitete Falschmeldung bekämpfen. Weil sachliche Richtigstellungen kaum durchdringen, überlegst du, eine mitreißende Heldengeschichte zu erfinden, die zwar nicht ganz stimmt, aber wirkt. Wie beurteilst du diesen Plan?","options":["Der Plan ist vertretbar: Der gute Zweck rechtfertigt das Mittel, solange die erfundene Geschichte besser wirkt als die Falschmeldung.","Der Plan ist ein Fehler: Wer eine Lüge mit einer anderen bekämpft, ersetzt das eine Problem durch ein neues und gibt die Wahrheitsverpflichtung auf.","Der Plan ist ratsam: Eine Gegengeschichte hat nur dann Wirkung, wenn sie frei erfunden und damit emotionaler ist als die Wahrheit.","Der Plan ist unbedenklich: Eine kurze, erfundene Geschichte schadet nicht, solange das Publikum sie nicht überprüft."],"correctIndex":1,"explanation":"Eine Gegenerzählung soll Menschen eine bessere Erklärung anbieten, die die entstandene Lücke füllt, und diese Erklärung muss auf der Wahrheit beruhen. Sie muss immer der Wahrheit und der intellektuellen Redlichkeit verpflichtet bleiben. Wer eine falsche, aber emotional ansprechende Geschichte konstruiert, um eine andere falsche Erzählung zu bekämpfen, überschreitet den Kipppunkt von der Nützlichkeit zur Gefahr: Er benutzt genau die Methode, die er bekämpfen wollte. Ein guter Zweck macht ein unredliches Mittel nicht gültig, denn ob eine Aussage stimmt, hängt nicht davon ab, wofür man sie einsetzt. Die bessere Lösung ist eine wahre Geschichte, die fesselt: mit einer klaren Erklärung, einer aktiven Rolle für die Zuhörenden und einer Erzählung, die mit den Fakten übereinstimmt.","coreRule":"⚡ Gegen Lügen hilft keine bessere Lüge – nur eine wahre Geschichte, die auch fesselt.","beleg":"Werkstück E.3.7 (Der Kipppunkt; Kontext & Tiefe: Komponenten)","status":"entwurf","scenario":"","kurz":"Eine Gegenerzählung soll die entstandene Lücke mit einer besseren Erklärung füllen, und die muss auf der Wahrheit beruhen. Wer eine Falschmeldung mit einer Erfindung bekämpft, benutzt genau die Methode, die er bekämpfen wollte.","prueffrage":"Worin unterscheidet sich die geplante Heldengeschichte von der Falschmeldung, die sie bekämpfen soll?","rueckmeldung":[{"option":0,"text":"Wirkung ist ein berechtigtes Anliegen. Ob eine Aussage stimmt, hängt aber nicht davon ab, wofür man sie einsetzt, und ein guter Zweck macht ein unredliches Mittel nicht gültig."},{"option":2,"text":"Eine Gegengeschichte braucht tatsächlich Anschaulichkeit und eine Erklärung, die die Lücke füllt. Dafür muss sie aber nicht erfunden sein: Auch eine wahre Geschichte kann fesseln, etwa mit klarer Erklärung und einer aktiven Rolle für die Zuhörenden."},{"option":3,"text":"Ob eine Aussage stimmt, hängt nicht davon ab, ob jemand sie nachprüft. Eine erfundene Geschichte bleibt unredlich, auch wenn sie unbemerkt bleibt, und sie wäre genau das Mittel, das man der Falschmeldung vorwirft."}],"familie":"luecke-fuellen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Lewandowsky, S.; Cook, J.; Ecker, U. K. H. u. a. (2020): The Debunking Handbook 2020","oeffentlich":true,"doi":"10.17910/b7.1182"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"88924737b6241ca3"}},{"id":"qx-e-063","clusterId":"E","werkstueckRef":"E.4.1","stufe":1,"question":"Was ist an dieser Schlussfolgerung fehlerhaft?","options":["Sie schließt aus der Nutzung einer Mechanik durch eine Gruppe, dass die Mechanik selbst den Hass hervorbringt, und übersieht, dass dieselbe Mechanik auch harmlose Inhalte tragen kann.","Sie unterstellt, dass Belohnungen überhaupt keinen Einfluss auf das Verhalten von Menschen haben und deshalb auch bei der Bindung an eine Gruppe keine Rolle spielen können.","Sie übersieht, dass Punkte und Ränge nur in Videospielen vorkommen und deshalb in Online-Gruppen oder Foren gar nicht eingesetzt werden können.","Sie geht davon aus, dass extremistische Gruppen ihre Mitglieder ausschließlich mit Argumenten überzeugen und deshalb keinerlei Spielmechaniken nutzen müssen."],"correctIndex":0,"explanation":"Eine Mechanik ist ein Werkzeug, kein Inhalt. Punkte, Ränge und Gemeinschaft motivieren Menschen, egal wofür: In Lern- und Fitness-Apps fördern sie nützliche Gewohnheiten, in einer extremistischen Gruppe binden sie Mitglieder an eine hasserfüllte Ideologie. Der Fehler liegt nicht in der Mechanik, sondern darin, wofür sie eingesetzt wird. Wer von „wird dort benutzt“ auf „ist die Ursache“ schließt, verwechselt Mittel und Zweck. Richtig wäre die Frage, ob die Belohnung eine Gruppe bindet, die Menschen schrittweise an immer radikalere Inhalte gewöhnt, ohne dass sie es merken.","coreRule":"⚡ Eine Mechanik, die Menschen bindet, ist noch kein Beleg für schädliche Absichten: Entscheidend ist, wofür sie eingesetzt wird und wohin sie führt.","beleg":"Werkstück E.4.1 (Einstieg; Kernidee; Das Adaptive Talent)","status":"entwurf","scenario":"In einer Diskussion über Online-Radikalisierung sagt jemand: „Die Gruppe benutzt Punkte, Ränge und Belohnungen, um ihre Mitglieder zu binden. Also sind diese Spielmechaniken selbst der Grund für Hass und Gewalt. Wer solche Mechaniken einsetzt, verbreitet Extremismus.“ Dieselben Mechaniken stecken auch in Lern-Apps, Fitness-Apps und Videospielen.","kurz":"Dass eine Gruppe Punkte und Ränge nutzt, macht diese Mechanik nicht zur Ursache des Hasses: Sie ist ein Werkzeug, das auch in Lern- und Fitness-Apps Gutes trägt. Der Fehler ist, Mittel und Zweck zu verwechseln.","prueffrage":"Wo kommen Punkte, Ränge und Belohnungen sonst noch vor, und was bewirken sie dort?","rueckmeldung":[{"option":1,"text":"Dass Belohnungen Verhalten beeinflussen, stimmt: Sie motivieren Menschen. Das bestreitet die Schlussfolgerung auch nicht; sie schließt vielmehr von der Nutzung durch eine Gruppe darauf, dass die Mechanik selbst den Hass verursacht."},{"option":2,"text":"Punkte und Ränge sind nicht auf Videospiele beschränkt: Lern- und Fitness-Apps nutzen sie ebenso, und auch viele Foren vergeben Ränge. Der Fehler liegt woanders, nämlich im Schluss von der Nutzung auf die Ursache."},{"option":3,"text":"Die Schlussfolgerung nimmt gerade an, dass die Gruppe Spielmechaniken einsetzt, sonst gäbe es nichts zu kritisieren. Mit der Frage, ob Mitglieder durch Argumente überzeugt werden, hat der Fehler nichts zu tun; er liegt im Schluss von „wird benutzt“ auf „ist die Ursache“."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Schlegel, L. (2020): Jumanji Extremism? How games and gamification could facilitate radicalization processes. Journal for Deradicalization 23","oeffentlich":true,"url":"https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/359","seite":"PDF-S. 5, 13, 15","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Nocun, K.; Lamberty, P. (2020): Fake Facts. Wie Verschwörungstheorien unser Denken bestimmen. Quadriga","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"df4eba2239260ea1"}},{"id":"qx-e-064","clusterId":"E","werkstueckRef":"E.4.1","stufe":2,"question":"Was ist die sparsamste Erklärung dafür, dass der Nutzer beim nächsten Mal noch schärfer postet?","scenario":"In einem Forum bekommt ein Nutzer für einen besonders zugespitzten, „witzigen“ Beitrag hunderte Likes und neue Follower. Davor hatte er eher sachlich geschrieben und kaum Resonanz bekommen. Beim nächsten Mal wird er noch schärfer.","options":["Er hat durch die Likes erkannt, dass seine zugespitzte Haltung in der Sache stimmt, und will sie deshalb deutlicher vertreten.","Die Zustimmung wirkt wie Punkte: Für Zuspitzung gibt es Anerkennung, für Sachlichkeit nicht, also wiederholt und steigert er, was sich lohnt.","Er wurde von anderen Mitgliedern gezielt angeleitet, immer extremere Beiträge zu schreiben, um in der Gruppe aufzusteigen.","Er ist von Anfang an radikal gewesen und hat sich nur bisher nicht getraut, seine wahre Meinung offen zu zeigen."],"correctIndex":1,"explanation":"Likes und neue Follower sind sofortiges, sichtbares Feedback. Verhalten, das belohnt wird, wird wiederholt und oft gesteigert. Das erklärt den Verlauf allein aus dem, was bekannt ist: sachlich gab es wenig Resonanz, zugespitzt gab es viel. Die anderen Erklärungen brauchen zusätzliche Annahmen, für die es keinen Hinweis gibt: dass die Zustimmung etwas über die Richtigkeit aussagt (Beliebtheit ist kein Wahrheitsbeleg), dass jemand den Nutzer gezielt anleitet, oder dass er schon immer radikal war. Das heißt nicht, dass der Nutzer nichts meint; es heißt, dass sein Verhalten auch ohne Überzeugungswandel erklärbar ist.","coreRule":"⚡ Frag bei einer Community: Wofür gibt es hier Punkte – und wofür gibt es sie nicht? Wer die Belohnung kennt, versteht oft das Verhalten, ohne eine Gesinnung unterstellen zu müssen.","beleg":"Werkstück E.4.1 (Kontext & Tiefe (Die Analyse), Aufzählpunkt „Punkte & Sozialer Status“)","status":"entwurf","kurz":"Sachlich gab es kaum Resonanz, zugespitzt hunderte Likes und Follower: Dieses Feedback wirkt wie eine Belohnung, und belohntes Verhalten wird wiederholt und oft gesteigert. Annahmen über seine Haltung oder fremde Anleitung braucht es dafür nicht.","prueffrage":"Was ist über den Nutzer tatsächlich bekannt, und was wird über ihn nur vermutet?","rueckmeldung":[{"option":0,"text":"Likes zeigen, was gut ankommt, nicht, was stimmt: Beliebtheit ist kein Wahrheitsbeleg. Auf einen Meinungswandel deutet auch nichts hin; die Zustimmung erklärt sein Verhalten schon als Belohnung."},{"option":2,"text":"Gruppendruck und gezielte Anleitung kommen in Online-Gemeinschaften durchaus vor. Hier gibt es aber keinen Hinweis darauf, und der Verlauf ist auch ohne eine solche Annahme erklärbar."},{"option":3,"text":"Dass er schon immer radikal war und sich nur nicht traute, ist denkbar, aber eine unbelegte Vermutung über sein Inneres. Dass er nach sachlichen Beiträgen ohne Echo und Applaus für Zuspitzung schärfer wird, lässt sich ohne diese Annahme erklären."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Brady, W. J.; McLoughlin, K.; Doan, T. N.; Crockett, M. J. (2021): How social learning amplifies moral outrage expression in online social networks. Science Advances 7(33)","oeffentlich":true,"doi":"10.1126/sciadv.abe5641","abruf":"2026-10-12"},{"typ":"doi","kurz":"Lindström, B. u. a. (2021): A computational reward learning account of social media engagement. Nature Communications 12, 1311","oeffentlich":true,"doi":"10.1038/s41467-020-19607-x","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0015c34230f79b3f"}},{"id":"qx-e-065","clusterId":"E","werkstueckRef":"E.4.1","stufe":3,"question":"Wie lässt sich am besten beurteilen, ob eine Online-Gemeinschaft mit Punkten und Rängen schädlich ist?","options":["Wofür die Punkte vergeben werden und ob das Streben nach Rang in reale Belästigung, Hass oder Gewalt außerhalb des Forums mündet.","Ob das Forum überhaupt Ranglisten und Belohnungen einsetzt, denn jede Form von Rangordnung begünstigt Radikalisierung zwangsläufig.","Ob die Mitglieder eine enge und loyale Gemeinschaft bilden, denn Zugehörigkeit zu einer Gruppe ist selbst schon eine Gefahr für die Gesellschaft.","Ob deine Freundin in kurzer Zeit sehr viel Zeit im Forum verbringt, denn die Dauer der Nutzung ist der entscheidende Risikofaktor für Radikalisierung."],"correctIndex":0,"explanation":"Punkte, Ränge und Gemeinschaft sind an sich neutral: Dieselben Mechanismen motivieren in Lern- und Fitness-Apps und sind dort nützlich. Entscheidend ist, wofür sie eingesetzt werden. Warnzeichen sind, wenn Ansehen von Extremität oder Provokation abhängt, wenn es einen Pfad von harmloseren zu immer radikaleren Inhalten gibt oder wenn Kritik als Angriff von „Spielverderbern“ abgetan wird. Kritisch wird es, wenn der „Highscore“ in der Gruppe zu Belästigung, Hass oder Gewalt im echten Leben führt. Die Alternativen verwechseln ein Merkmal, das auch in harmlosen Gemeinschaften vorkommt (Ranglisten, Zusammenhalt, viel Zeit), mit dem eigentlichen Schadenskriterium. Wer so schließt, müsste auch Sportvereine, Chöre und Lernplattformen für gefährlich halten.","coreRule":"⚡ Nicht die Spielmechanik ist das Problem, sondern wofür sie eingesetzt wird.","beleg":"Werkstück E.4.1 (Der Kipppunkt; Das Adaptive Talent; Red Flags)","status":"entwurf","scenario":"Eine Freundin erzählt dir von einem Online-Forum, in dem man für gute Beiträge Punkte sammelt und in Ränge aufsteigt. Sie ist begeistert. Du fragst dich, ob das harmlos ist oder ob du sie warnen solltest.","quote":"","quoteLabel":"","kurz":"Punkte, Ränge und Zusammenhalt sind für sich neutral und nützen auch in Lern-Apps. Entscheidend ist, wofür sie vergeben werden und ob daraus Belästigung, Hass oder Gewalt im echten Leben folgt. Wer schon die Mechanik für gefährlich hält, verwechselt Merkmal und Schaden.","prueffrage":"Was postet deine Freundin dort konkret, und wie reagieren die anderen darauf?","rueckmeldung":[{"option":1,"text":"Ranglisten fallen leicht auf, weil sie nach Wettbewerb aussehen. Dieselbe Mechanik steckt aber auch in Lern- und Fitness-Apps, ohne dort zu schaden; zwangsläufig führt sie nirgends zu Radikalisierung. Es zählt, wofür der Rang vergeben wird."},{"option":2,"text":"Starker Zusammenhalt kann ein Warnzeichen sein, etwa wenn Kritik als Angriff abgetan wird. Zugehörigkeit allein ist aber keine Gefahr, sonst wären auch Sportvereine und Chöre bedenklich. Maßgeblich ist, was die Gruppe tut und fördert."},{"option":3,"text":"Viel Zeit im Forum fällt sofort ins Auge und wirkt wie ein klares Signal. Wer begeistert dabei ist, verbringt aber auch in harmlosen Gemeinschaften viele Stunden, und die Dauer sagt nichts über den Inhalt. Aufschlussreich ist, was dort belohnt wird."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Schlegel, L. (2020): Jumanji Extremism? How games and gamification could facilitate radicalization processes. Journal for Deradicalization 23","oeffentlich":true,"url":"https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/359","seite":"PDF-S. 5, 15","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Nocun, K.; Lamberty, P. (2020): Fake Facts. Wie Verschwörungstheorien unser Denken bestimmen. Quadriga","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"f5fd98fba3c6ed8b"}},{"id":"qx-e-066","clusterId":"E","werkstueckRef":"E.4.1","stufe":4,"question":"Du liest die Schlagzeile: „Spiel macht Menschen immun gegen Fake News!“ Dahinter steckt eine Studie mit 196 Teilnehmenden einer Online-Plattform. Eine Gruppe spielte eine Viertelstunde lang ein Spiel, in dem man selbst Falschmeldungen verbreitet und dabei Manipulationstechniken kennenlernt, die Vergleichsgruppe spielte Tetris. Direkt danach bewerteten beide Gruppen erfundene Beiträge. Die Spielgruppe erkannte die Manipulationstechniken besser. Was darfst du aus diesem Ergebnis folgern?","options":["Der Effekt wurde nur direkt nach dem Spiel gemessen; Dauer und Verhalten im Netz bleiben offen.","Der Schutz hält über Jahre an, weil Spielen ein grundlegender menschlicher Lernmechanismus ist.","Die Teilnehmenden teilen künftig weniger Falschmeldungen, weil wer Techniken erkennt, auch danach handelt.","Der Effekt gilt für alle Internetnutzenden, weil die Stichprobe von der Online-Plattform repräsentativ war."],"correctIndex":0,"explanation":"Die Spielgruppe schnitt direkt nach dem Spiel besser ab als die Tetris-Gruppe. Mehr trägt die Messung aber nicht: Es wurde nur unmittelbar nach dem Spiel gemessen, und zwar an erfundenen Beiträgen. Ob das Erkennen nach Wochen noch funktioniert und ob Menschen im echten Netz anders handeln, wurde nicht geprüft. Zudem stammen die 196 Personen aus einer Online-Plattform und sind nach Angabe der Autoren wohl nicht repräsentativ. Ein Schluss von „erkennt Techniken in einem Test“ auf „teilt weniger Falschmeldungen“, auf „ist dauerhaft geschützt“ oder auf „gilt für alle Nutzenden“ geht über die Datenlage hinaus. Der Vergleich mit der Tetris-Gruppe spricht zugleich gegen einen reinen Zufallsbefund.","coreRule":"⚡ Prüfe bei jeder Studienschlagzeile, was genau gemessen wurde und wann: Ein Effekt direkt nach der Intervention sagt nichts über Dauer oder Verhalten im Alltag.","beleg":"Werkstück E.4.1 (Verbindungen: Kognitive Immunisierung); Fn. gl-e-badnews (Basol, Roozenbeek, van der Linden 2020, S. 1–3 und 6)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Gemessen wurde nur direkt nach dem Spiel, an erfundenen Beiträgen. Dass die Spielgruppe dort besser abschnitt, ist belegt; Dauer und Verhalten im echten Netz sind offen. Wer „erkennt im Test“ zu „ist geschützt“ ausbaut, geht über die Daten hinaus.","prueffrage":"Wie sah die Aufgabe aus, an der der Erfolg des Spiels gemessen wurde, und wer hat sie bearbeitet?","rueckmeldung":[{"option":1,"text":"Die Studie sagt nichts über Jahre aus, denn gemessen wurde direkt nach dem Spiel. Auch die Begründung mit einem „grundlegenden Lernmechanismus“ ist eine Zusatzannahme, die in den Daten nicht vorkommt."},{"option":2,"text":"Dass die Spielgruppe Techniken besser erkannte, ist belegt. Gemessen wurde aber das Bewerten erfundener Beiträge, nicht das Teilen im echten Netz. Ob aus Erkennen anderes Handeln wird, wurde nicht geprüft."},{"option":3,"text":"Eine Online-Plattform liefert bequem Teilnehmende, aber keine Stichprobe, die für alle Internetnutzenden steht. Nach Angabe der Autoren ist sie wohl nicht repräsentativ, daher lässt sich der Effekt nicht auf alle übertragen."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Basol, M.; Roozenbeek, J.; van der Linden, S. (2020): Good News about Bad News: Gamified Inoculation Boosts Confidence and Cognitive Immunity Against Fake News. Journal of Cognition 3(1)","oeffentlich":true,"doi":"10.5334/joc.91"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"8aca53a4530219dd"}},{"id":"qx-e-067","clusterId":"E","werkstueckRef":"E.4.2","stufe":1,"question":"Welche Frage bringt am schnellsten ans Licht, womit sich dieses Angebot finanziert?","options":["Wie viele Nutzer hat die App schon, und wie schnell wächst sie?","Wer bezahlt dem Unternehmen Geld, und was bekommt er dafür?","Wie gut sind die Bewertungen der App im App-Store?","Welche Inhalte werden auf der App am häufigsten angeschaut?"],"correctIndex":1,"explanation":"Ein Unternehmen mit hohen Kosten muss Einnahmen haben. Wenn die Nutzer nichts zahlen, muss das Geld von jemand anderem kommen. Beim bekanntesten Geschäftsmodell solcher Gratisdienste sind das Werbetreibende, die für die Aufmerksamkeit der Nutzer bezahlen. Für die Plattform sind dann nicht die Nutzer die Kunden, sondern ihre Aufmerksamkeit und ihr vorhersagbares Verhalten die Ware. Die Frage nach Zahlungsströmen deckt das Geschäftsmodell auf, und aus dem Geschäftsmodell folgt, worauf der Dienst ausgelegt ist: Das Design zielt auf maximale Verweildauer, denn gebundene Aufmerksamkeit wird an Werbetreibende verkauft. Nutzerzahlen, Bewertungen und beliebte Inhalte sagen etwas über Erfolg und Geschmack, aber nichts darüber, woher das Geld kommt.","coreRule":"⚡ Frag bei jedem Gratisdienst: Wer bezahlt hier – und was bekommt er dafür?","beleg":"Werkstück E.4.2 (Kernidee; Kontext & Tiefe: Das Geschäftsmodell; Du bist nicht der Kunde)","status":"entwurf","scenario":"Eine neue Video-App ist komplett kostenlos, ohne Abo und ohne Bezahlfunktionen. Trotzdem beschäftigt das Unternehmen Hunderte Angestellte und betreibt riesige Rechenzentren. Eine Freundin sagt: „Ist doch super, das kostet mich gar nichts.“ Du willst herausfinden, wie das Geschäftsmodell funktioniert.","kurz":"Hohe Kosten brauchen Einnahmen, und wenn die Nutzer nichts zahlen, muss jemand anderes zahlen. Wer das ist und was er dafür bekommt, zeigt das Geschäftsmodell. „Kostenlos“ heißt nur, dass man nicht mit Geld bezahlt.","prueffrage":"Angenommen, die App hätte morgen doppelt so viele Nutzer: Hätte das Unternehmen dann mehr Geld, und von wem?","rueckmeldung":[{"option":0,"text":"Ein starkes Wachstum zeigt, dass die App ankommt. Es verrät aber nicht, wer das Unternehmen bezahlt: Eine App mit vielen Nutzern kann von Werbung, Investorengeld oder anderen Quellen leben."},{"option":2,"text":"Gute Bewertungen sagen, dass die Nutzer zufrieden sind. Zufriedenheit bringt aber noch kein Geld ein, und die Sterne im Store verraten nichts über die Einnahmen des Unternehmens."},{"option":3,"text":"Beliebte Inhalte zeigen, was den Nutzern gefällt, und das kann für Werbung durchaus eine Rolle spielen. Wer das Unternehmen tatsächlich bezahlt, lässt sich daraus aber nicht ablesen."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Montag, C.; Lachmann, B.; Herrlich, M.; Zweig, K. (2019): Addictive Features of Social Media/Messenger Platforms and Freemium Games against the Background of Psychological and Economic Theories. IJERPH 16(14), 2612","oeffentlich":true,"doi":"10.3390/ijerph16142612","abruf":"2026-10-12"},{"typ":"url","kurz":"Franck, G. (1999): The Economy of Attention. Telepolis, 7.12.1999","oeffentlich":true,"url":"https://archiv.telepolis.de/features/The-Economy-of-Attention-3444929.html"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"4a2c3b1c5edc1fb9"}},{"id":"qx-e-068","clusterId":"E","werkstueckRef":"E.4.2","stufe":2,"question":"Welche Gestaltung ist bei diesem Erfolgsmaßstab am wahrscheinlichsten, und warum?","scenario":"Eine kostenlose App finanziert sich ausschließlich über Werbung. Ihr Produktteam erhält eine einzige Kennzahl als Erfolgsmaßstab: die durchschnittliche Zeit, die Nutzer pro Tag in der App verbringen. Nun muss das Team entscheiden, wie der Feed gestaltet werden soll.","options":["Ein Feed, der immer weiterlädt, mit Aktualisieren per Wischgeste und roten Hinweispunkten, weil jede Unterbrechung des Scrollens Nutzungszeit kostet.","Ein Feed mit festem Ende nach 20 Beiträgen und einem Hinweis, dass alles Neue gesehen wurde, weil zufriedene Nutzer später wiederkommen.","Ein Feed, der nur auf ausdrückliche Suche Beiträge anzeigt, weil Nutzer dann genau das finden, was sie brauchen.","Ein Feed ohne Benachrichtigungen und ohne automatische Aktualisierung, weil weniger Reize den Nutzern mehr Ruhe verschaffen."],"correctIndex":0,"explanation":"Die App verdient ihr Geld mit Werbung: Ihre Dienste wirken kostenlos, doch die gesammelte Aufmerksamkeit der Nutzer ist die eigentliche Ware, die an Werbetreibende verkauft wird. Deshalb ist jede Design-Entscheidung darauf ausgerichtet, den Nutzer so lange wie möglich auf der Plattform zu halten. Wird Nutzungszeit zum einzigen Erfolgsmaßstab, passen genau die Mechanismen dazu, die das Aufhören erschweren: Feeds ohne Ende, Aktualisieren per Wischgeste und rote Hinweispunkte, die zur Rückkehr locken. Die anderen Gestaltungen mögen für Nutzer angenehmer sein, würden aber genau diese Kennzahl senken. Gratis bedeutet hier nicht, dass es nichts kostet: Bezahlt wird mit Aufmerksamkeit, und das Ziel der App ist nicht automatisch dein eigenes Ziel.","coreRule":"⚡ Wenn ein Dienst gratis ist, frag, was er misst: Die Kennzahl verrät, wofür das Design gebaut ist.","beleg":"Werkstück E.4.2 (Kontext & Tiefe: Das Geschäftsmodell, Das Ziel ist die Maximierung der Verweildauer; Red Flags). Fachbegriffe Infinite Scroll und Pull-to-Refresh bewusst durch Beschreibungen ersetzt.","status":"entwurf","kurz":"Wenn nur die Nutzungszeit zählt, passt alles, was das Aufhören erschwert: endloses Scrollen, Wischen zum Aktualisieren, rote Hinweispunkte. Angenehmere Feeds mit Ende oder mehr Ruhe senken diese Kennzahl, und von ihr lebt eine App, die Aufmerksamkeit verkauft.","prueffrage":"Wie würde sich die durchschnittliche Zeit pro Tag verändern, wenn der Feed nach einer festen Zahl von Beiträgen endet?","rueckmeldung":[{"option":1,"text":"Zufriedene Nutzer, die später wiederkommen, sind ein gutes Ziel. Gemessen wird hier aber die Zeit pro Tag, und ein Feed mit Ende nach 20 Beiträgen verkürzt sie, weil die Nutzung dann von selbst aufhört."},{"option":2,"text":"Wer gezielt sucht, findet schnell, was er braucht, und das ist für Nutzer angenehm. Danach ist die Sitzung aber meist zu Ende, die Nutzungszeit bleibt also kurz, und genau sie gilt als Erfolgsmaßstab."},{"option":3,"text":"Weniger Reize können den Nutzern mehr Ruhe verschaffen. Doch ohne Hinweise und automatische Aktualisierung fehlt, was zur Rückkehr lockt und das Aufhören erschwert, und die Nutzungszeit sinkt."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Montag, C.; Lachmann, B.; Herrlich, M.; Zweig, K. (2019): Addictive Features of Social Media/Messenger Platforms and Freemium Games against the Background of Psychological and Economic Theories. IJERPH 16(14), 2612","oeffentlich":true,"doi":"10.3390/ijerph16142612","abruf":"2026-10-12"},{"typ":"url","kurz":"Franck, G. (1999): The Economy of Attention. Telepolis, 7.12.1999","oeffentlich":true,"url":"https://archiv.telepolis.de/features/The-Economy-of-Attention-3444929.html"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"00e7b23a7a0009e5"}},{"id":"qx-e-069","clusterId":"E","werkstueckRef":"E.4.2","stufe":3,"question":"Eine Nutzerin wundert sich, warum sie kaum aufhören kann zu scrollen: Mal erscheint ein lustiges Video, mal eine langweilige Anzeige, mal etwas Spannendes – nie vorhersehbar. Welche Erklärung trifft den Mechanismus am besten?","options":["Ein neutraler Reiz wird immer wieder mit einem unbedingten Reiz gekoppelt, bis er allein die Reaktion auslöst.","Eine alte Angst wird durch starke positive Reize schrittweise überschrieben und ersetzt.","Die Nutzerin redet sich nachträglich ein, dass ihr das Scrollen guttut und sinnvoll war.","Gelegentliche, unvorhersehbare Belohnungen halten ein Verhalten stärker am Laufen als verlässliche."],"correctIndex":3,"explanation":"Entscheidend ist das Muster der Belohnung: Sie kommt unregelmäßig und lässt sich nicht vorhersagen. Genau darauf baut der Sog auf, denn jeder weitere Wisch könnte der Treffer sein, und jede kleine Belohnung nährt den Drang, weiterzurollen. Fachlich spricht man von operanter Konditionierung mit variablen Belohnungen; Plattformen können dieses Prinzip nutzen, um Menschen möglichst lange zu halten. Die anderen Erklärungen passen nicht zur Situation: Hier wird kein neutraler Reiz an einen Auslöser gekoppelt, keine Angst abgebaut und keine nachträgliche Rechtfertigung beschrieben.","coreRule":"⚡ Unvorhersehbare Belohnungen sind der Haken, an dem das Weiterscrollen hängt.","beleg":"Werkstück E.4.2 (Einstieg: Der Daumen des Sisyphos; Verbindungen; Schmiede-Übung)","status":"entwurf","kurz":"Weil jeder Wisch der Treffer sein könnte, hält die Unvorhersehbarkeit das Scrollen am Laufen: Gelegentliche, unregelmäßige Belohnungen binden stärker als verlässliche. Kommt die Belohnung verlässlich, fehlt dieser Reiz des Ungewissen.","prueffrage":"Was tut die Nutzerin jeweils selbst, und was folgt unmittelbar darauf?","rueckmeldung":[{"option":0,"text":"Lernen durch Verknüpfung gibt es, etwa wenn ein Ton allein schon Erwartung weckt. Hier wird aber kein neutraler Reiz an einen Auslöser gekoppelt; es geht um ein Verhalten, das unregelmäßiger Lohn am Laufen hält."},{"option":1,"text":"Eine Angst, die überschrieben wird, kommt hier nirgends vor: Die Nutzerin wundert sich über ihren Drang weiterzuscrollen, von einer Furcht, die abgebaut würde, ist keine Rede."},{"option":2,"text":"Nachträgliches Schönreden eigenen Verhaltens kommt im Alltag durchaus vor. Beschrieben wird aber, dass sie sich über ihren Drang wundert, nicht, dass sie ihn schönredet. Der Sog entsteht, bevor irgendeine Rechtfertigung nötig ist."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Montag, C.; Lachmann, B.; Herrlich, M.; Zweig, K. (2019): Addictive Features of Social Media/Messenger Platforms and Freemium Games against the Background of Psychological and Economic Theories. IJERPH 16(14), 2612","oeffentlich":true,"doi":"10.3390/ijerph16142612","abruf":"2026-10-12"},{"typ":"doi","kurz":"Lindström, B. u. a. (2021): A computational reward learning account of social media engagement. Nature Communications 12, 1311","oeffentlich":true,"doi":"10.1038/s41467-020-19607-x","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c200e7956df23c89"}},{"id":"qx-e-070","clusterId":"E","werkstueckRef":"E.4.3","stufe":2,"question":"Welche Erklärung für die Veränderung ihres Feeds ist am sparsamsten?","scenario":"Ein Mitarbeiter einer Plattform erklärt: „Unser Empfehlungssystem versteht keine Inhalte. Es misst nur, wie lange Nutzer bleiben und ob sie klicken, kommentieren oder teilen, und zeigt mehr von dem, was diese Werte erhöht.“ Eine Nutzerin hat bisher meist Yoga-Videos geliked. Dann teilt sie zum ersten Mal einen politischen Beitrag mit einem empörten Kommentar. Danach sieht sie in ihrem Feed deutlich mehr empörende politische Beiträge.","options":["Ihr empörter Kommentar hat mehr Engagement erzeugt als ihre Yoga-Likes, also zeigt das System ihr mehr davon.","Das System hat erkannt, dass der geteilte Beitrag falsch ist, und verstärkt deshalb ähnliche Inhalte, um sie zu warnen.","Das System hat ihre politische Einstellung erkannt und will sie auf eine bestimmte Seite ziehen, indem es passende Beiträge zuspielt.","Das System hat ihre Interessen neu bewertet und hält politische Inhalte für sie jetzt für wichtiger und wahrer als Yoga-Videos."],"correctIndex":0,"explanation":"Ein System, das nur Klicks, Kommentare, Shares und Verweildauer misst, braucht keine Absicht und kein Verständnis von Inhalten, um sein Verhalten zu ändern. Ihre Wut erzeugt viel mehr Engagement als ihre sanfte Zuneigung für Yoga, also lernt das System, ihr mehr davon zu zeigen. Die anderen Erklärungen unterstellen dem System etwas, das es nach dieser Beschreibung gar nicht kann: Wahrheit prüfen, Ziele über Meinungen verfolgen oder Wichtigkeit beurteilen. Die einfachste Erklärung braucht keine zusätzliche Annahme. Daraus folgt aber nicht, dass sie automatisch radikalisiert wird: Wie stark solche Feeds Einstellungen tatsächlich verändern, ist empirisch umstritten.","coreRule":"⚡ Erkläre Verhalten mit der einfachsten Annahme, die zu den Daten passt: Ein System, das nur Engagement misst, folgt dem Engagement, nicht der Wahrheit oder einem Plan.","beleg":"Werkstück E.4.3 (Einstieg: Der unsichtbare Gott in der Maschine; Kontext & Tiefe: Der Mechanismus)","status":"entwurf","kurz":"Ein System, das nur Klicks, Kommentare und Verweildauer misst, braucht für den Wandel keine Absicht und kein Inhaltsverständnis: Ihre Wut erzeugt mehr Engagement als Yoga. Der Fehler wäre, dem System Ziele oder Urteile zuzuschreiben.","prueffrage":"Welche Signale kann das System laut Beschreibung überhaupt sehen, und was davon hat sich bei ihr nach dem Teilen verändert?","rueckmeldung":[{"option":1,"text":"Dass sich der Feed nach dem Teilen verändert, stimmt. Falsches zu erkennen und gezielt zu warnen, setzt aber ein Verständnis von Inhalten voraus, das ein System nicht hat, das nur Klicks, Kommentare, Shares und Verweildauer zählt."},{"option":2,"text":"Mehr politische Beiträge lassen schnell an Steuerung denken. Dafür müsste das System aber Meinungen erkennen und ein Ziel damit verfolgen; beides ist nach der Beschreibung nicht nötig, und die einfachere Erklärung kommt ohne diese Zusatzannahme aus."},{"option":3,"text":"Für sie hat sich die Gewichtung tatsächlich verschoben, aber nicht durch ein Urteil des Systems. Es bewertet weder Wichtigkeit noch Wahrheit, es folgt nur den Werten, die steigen, und Empörung treibt sie stärker als Yoga."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Rathje, S.; Van Bavel, J. J.; van der Linden, S. (2021): Out-group animosity drives engagement on social media. PNAS 118(26)","oeffentlich":true,"doi":"10.1073/pnas.2024292118"},{"typ":"doi","kurz":"Gauthier, G.; Hodler, R.; Widmer, P.; Zhuravskaya, E. (2026): The political effects of X's feed algorithm. Nature 652(8109)","oeffentlich":true,"doi":"10.1038/s41586-026-10098-2"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"51abc31fe1ad8494"}},{"id":"qx-e-071","clusterId":"E","werkstueckRef":"E.4.3","stufe":3,"question":"Eine Auswertung von rund 2,7 Millionen Beiträgen von Medienkonten und Abgeordneten zeigte, dass Posts über die politische Gegenseite etwa doppelt so oft geteilt wurden wie Posts über die eigene Seite. Was darfst du daraus schließen?","options":["Dass gewöhnliche Nutzer mehrheitlich Feindseligkeit teilen und sich dadurch zunehmend radikalisieren.","Dass Beiträge dieser Konten über die Gegenseite öfter geteilt wurden als solche über die eigene Seite.","Dass Feed-Algorithmen die Polarisierung der Gesellschaft messbar verstärken, weil so viel geteilt wurde.","Dass negative Gefühlswörter das Teilen stärker vorhersagen als Wörter über die andere Gruppe."],"correctIndex":1,"explanation":"Die Auswertung zeigt nur, dass Beiträge dieser Konten über die Gegenseite häufiger geteilt wurden als solche über die eigene Seite. Untersucht wurden Beiträge von Medienkonten und Abgeordneten: Wie oft sie geteilt wurden, verrät nicht, was gewöhnliche Nutzer mehrheitlich selbst posten oder ob sie sich radikalisieren. Ob Feed-Algorithmen Haltungen verändern, zeigen erst Experimente mit gezielt veränderten Feeds; die größten fanden keine messbare Polarisierung durch den Feed-Algorithmus, ein kleineres eine geringe, kurzfristige Wirkung. Über Gefühlswörter sagt die beschriebene Auswertung nichts; in der Studie selbst sagten Wörter über die andere Gruppe das Teilen sogar rund 4,8-mal so stark voraus wie negative Gefühlswörter allgemein.","coreRule":"⚡ Frag bei einer Studie nicht nur, was sie zeigt, sondern auch, wen sie untersucht hat und was ihr Design überhaupt beweisen kann.","beleg":"Werkstück E.4.3 (Kontext & Tiefe: Die emotionale Asymmetrie); Fn. gl-e-empoerung (Rathje, Van Bavel, van der Linden 2021, PNAS 118(26))","status":"entwurf","kurz":"Die Auswertung zeigt nur, dass in diesen Konten Beiträge über die Gegenseite häufiger geteilt wurden. Wer daraus Aussagen über gewöhnliche Nutzer, ihre Radikalisierung oder die Wirkung von Algorithmen macht, geht über die Daten hinaus.","prueffrage":"Von wem stammten die ausgewerteten Beiträge, und was genau wurde an ihnen gezählt?","rueckmeldung":[{"option":0,"text":"Wie oft Beiträge von Medienkonten und Abgeordneten geteilt werden, zeigt noch nicht, was die Mehrheit gewöhnlicher Nutzer selbst teilt. Und ob sich jemand radikalisiert, lässt sich am Teilen allein gar nicht ablesen."},{"option":2,"text":"Viel Teilen lässt an einen verstärkenden Algorithmus denken. Ob ein Feed Haltungen verändert, zeigen aber erst Experimente mit veränderten Feeds; die größten fanden keine messbare Polarisierung, ein kleineres nur eine geringe, kurzfristige Wirkung."},{"option":3,"text":"Über Gefühlswörter sagt die Auswertung nichts, der Vergleich lässt sich daraus nicht ableiten. In der Studie selbst war es umgekehrt: Wörter über die andere Gruppe sagten das Teilen etwa 4,8-mal so stark voraus wie negative Gefühlswörter."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Rathje, S.; Van Bavel, J. J.; van der Linden, S. (2021): Out-group animosity drives engagement on social media. PNAS 118(26)","oeffentlich":true,"doi":"10.1073/pnas.2024292118"},{"typ":"doi","kurz":"Guess, A. M. u. a. (2023): How Do Social Media Feed Algorithms Affect Attitudes and Behavior in an Election Campaign? Science 381(6656)","oeffentlich":false,"doi":"10.1126/science.abp9364"},{"typ":"doi","kurz":"Piccardi, T. u. a. (2025): Reranking partisan animosity in algorithmic social media feeds alters affective polarization. Science 390(6776)","oeffentlich":false,"doi":"10.1126/science.adu5584"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"6c48b76c64edc6e1"}},{"id":"qx-e-072","clusterId":"E","werkstueckRef":"E.4.3","stufe":4,"question":"Ein Beitrag behauptet: „Der Empfehlungs-Algorithmus einer Videoplattform führt Nutzer Schritt für Schritt in den Extremismus – ganz ohne dass sie es wollen.“ Wie sicher darfst du dieser Behauptung glauben, wenn du die Datenlage kennst?","options":["Die Behauptung gilt als bestätigt: Die großen Feldexperimente haben gezeigt, dass Feed-Algorithmen die Nutzer messbar und stark polarisieren.","Die Behauptung ist widerlegt: Empfehlungen haben auf Meinungen keinerlei Einfluss, und niemand wird über Plattformen radikalisiert.","Die Behauptung ist als Bild eingängig, aber in den Felddaten schwächer belegt: Ein Verstärker-Effekt ist möglich, der erste Schritt war oft eine eigene Entscheidung.","Die Behauptung ist teilweise bestätigt: Bei Textplattformen haben Feldexperimente eindeutig gezeigt, dass Feed-Algorithmen die Nutzer in die Radikalisierung führen."],"correctIndex":2,"explanation":"Eine eingängige Geschichte ist noch kein Beleg. Die Daten sprechen gegen die starke Version der Behauptung: Wer extremistische Kanäle nutzt, kommt meist über Abonnements und Links dorthin, und große Feldexperimente fanden keine messbare Polarisierung durch den Feed-Algorithmus. Auch ein siebenwöchiges Experiment auf X fand keine Wirkung auf Polarisierung. Ganz widerlegt ist die Behauptung damit nicht: Ein kleineres Experiment mit umsortierten X-Feeds zeigte eine leichte, kurzfristige Verschiebung der Haltung zur Gegenpartei, ob sie anhält, ist offen. Die vorsichtigste, belegbare Einordnung lautet daher: Ein Verstärker ist plausibel, aber der erste Schritt ist meist eine eigene Entscheidung. Beide Extreme („bewiesen“ und „widerlegt“) gehen über die Datenlage hinaus.","coreRule":"⚡ Ein eingängiges Bild ist kein Beleg: Prüfe die Daten, bevor du eine Behauptung glaubst – und halte dein Urteil so stark wie die Belege, nicht stärker.","beleg":"Werkstück E.4.3 (Kontext & Tiefe: Der Kaninchenbau-Effekt, Hinweis zur Beleglage); Fn. gl-e-kaninchenbau (Chen u. a. 2023; Hosseinmardi u. a. 2021; Guess u. a. 2023; Piccardi u. a. 2025)","status":"entwurf","scenario":"Der Beitrag verbreitet sich schnell, weil das Bild vom „Kaninchenbau“ so eingängig ist. Du kennst folgende Befunde: Nutzer extremistischer Kanäle kamen laut Auswertungen großer Datensätze überwiegend über Abonnements und externe Links dorthin, nicht über Empfehlungen. Große Feldexperimente mit umgestellten Feed-Algorithmen (2023) fanden keine messbare Polarisierung. Ein kleineres Experiment mit gezielt umsortierten Feeds (2025, zehn Tage) zeigte eine leichte, kurzfristige Veränderung der Haltung zur Gegenpartei.","kurz":"Eine eingängige Geschichte ist noch kein Beleg: Extremistische Kanäle erreichen Nutzer meist über Abonnements und Links, und große Feldexperimente fanden keine Polarisierung. Ein Verstärker ist dennoch plausibel, ganz widerlegt ist die Behauptung nicht.","prueffrage":"Auf welchem Weg sind Nutzer extremistischer Kanäle laut den Daten überhaupt dorthin gekommen?","rueckmeldung":[{"option":0,"text":"Dass es große Feldexperimente gibt, macht die Behauptung nicht stärker, denn sie fanden keine messbare Polarisierung. Nur ein kleineres Experiment zeigte eine leichte, kurzfristige Verschiebung, von einer starken Wirkung ist das weit entfernt."},{"option":1,"text":"Dass Empfehlungen meist nicht der Einstieg sind, spricht gegen die starke Version der Behauptung. „Keinerlei Einfluss“ und „niemand“ gehen aber zu weit: Ein kleineres Experiment zeigte eine leichte, kurzfristige Wirkung, und ob sie anhält, ist offen."},{"option":3,"text":"Die Aufteilung nach Plattformtyp führt in die Irre: Eindeutig bestätigt ist die Radikalisierung durch Feed-Algorithmen nirgends. Das kleine Experiment zeigte nur eine leichte, kurzfristige Verschiebung der Haltung zur Gegenpartei, keinen Weg in den Extremismus."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Chen, A. Y.; Nyhan, B.; Reifler, J.; Robertson, R. E.; Wilson, C. (2023): Subscriptions and External Links Help Drive Resentful Users to Alternative and Extremist YouTube Channels. Science Advances 9(35)","oeffentlich":true,"doi":"10.1126/sciadv.add8080"},{"typ":"doi","kurz":"Gauthier, G.; Hodler, R.; Widmer, P.; Zhuravskaya, E. (2026): The political effects of X's feed algorithm. Nature 652(8109)","oeffentlich":true,"doi":"10.1038/s41586-026-10098-2"},{"typ":"doi","kurz":"Piccardi, T. u. a. (2025): Reranking partisan animosity in algorithmic social media feeds alters affective polarization. Science 390(6776)","oeffentlich":false,"doi":"10.1126/science.adu5584"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c33a85217d18cdea"}},{"id":"qx-e-073","clusterId":"E","werkstueckRef":"E.4.3","stufe":4,"question":"Du liest: „Eine Studie mit Twitter-Daten zeigt, dass Falschnachrichten sich weiter verbreiten als wahre. Der Algorithmus der Plattform ist also schuld.“ Wo liegt der Denkfehler, und was müsstest du dafür wissen?","options":["Der Schluss ist voreilig: Die Studie zeigt, dass Menschen Falsches häufiger teilten; zur Rolle des Algorithmus sagt sie nichts.","Der Schluss stimmt, denn wenn sich Falsches weiter verbreitet, muss der Algorithmus es bevorzugt ausspielen, sonst gäbe es keinen Unterschied.","Der Schluss stimmt nicht, weil die Verbreitung vor allem auf Bots zurückgeht, die gezielt Falsches streuen und Wahres ausbremsen.","Der Schluss stimmt, denn Plattformen verdienen an Aufmerksamkeit, und deshalb ist der Algorithmus als Ursache praktisch bewiesen."],"correctIndex":0,"explanation":"Ein Unterschied in der Verbreitung zeigt noch nicht, wodurch er entsteht. In der Auswertung von rund 126.000 Geschichten (Vosoughi, Roy, Aral 2018) teilten Menschen Falsches häufiger als Wahres, während Bots beide Sorten gleichermaßen beschleunigten. Ob Feed-Algorithmen mitwirkten, wurde nicht untersucht; dazu sagt die Studie also nichts. Wer „der Algorithmus ist schuld“ behauptet, schließt von einem gemessenen Effekt auf eine Ursache, die gar nicht geprüft wurde. Ein plausibler Mechanismus (Plattformen leben von Aufmerksamkeit) ersetzt keinen Beleg. Die Technik kann ein Verstärker sein, getragen wird die Verbreitung laut der Studie aber von Menschen.","coreRule":"⚡ Ein gemessener Effekt beweist keine Ursache, die nicht untersucht wurde: Frage immer, was die Studie tatsächlich geprüft hat.","beleg":"Werkstück E.4.3 (Anwendung & Relevanz: Bei Verschwörungsmythen & Desinformation); Fn. gl-e-vosoughi (Vosoughi, Roy, Aral 2018, Science 359(6380), S. 1146–1151)","status":"entwurf","scenario":"Eine Studie wertete rund 126.000 Geschichten auf Twitter aus und stellte fest: Falsche Nachrichten verbreiteten sich weiter als wahre. Beim Auswerten zeigte sich, dass Menschen Falsches häufiger teilten und dass Bots wahre und falsche Nachrichten gleichermaßen beschleunigten. Ob die Feed-Algorithmen der Plattform etwas dazu beitrugen, war nicht Gegenstand der Untersuchung.","quote":"","quoteLabel":"","kurz":"Gemessen wurde, dass Falsches sich weiter verbreitet und dass Menschen es häufiger teilten. Wer daraus „der Algorithmus ist schuld“ macht, schließt auf eine Ursache, die gar nicht untersucht wurde. Technik kann verstärken, getragen wird es laut Studie von Menschen.","prueffrage":"Welche möglichen Ursachen hat die Studie tatsächlich untersucht, und welche kommt in den Befunden gar nicht vor?","rueckmeldung":[{"option":1,"text":"Dass sich Falsches weiter verbreitet, wirkt wie ein Hinweis auf eine Bevorzugung durch die Technik. Der Unterschied lässt sich aber schon durch das Teilen der Menschen erklären, und genau das zeigt die Studie. Ob der Algorithmus mitwirkt, blieb offen."},{"option":2,"text":"Der Schluss auf den Algorithmus ist tatsächlich nicht belegt. Die Begründung stimmt aber nicht: Bots beschleunigten wahre und falsche Nachrichten gleichermaßen, den Unterschied erzeugten laut Studie die Menschen."},{"option":3,"text":"Dass Plattformen an Aufmerksamkeit verdienen, macht einen Einfluss des Algorithmus plausibel. Ein plausibler Grund ist aber noch kein Beleg, und die Studie hat den Algorithmus gar nicht untersucht."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"MIT News (Dizikes, P., 8.3.2018): Study: On Twitter, false news travels faster than true stories","oeffentlich":true,"url":"https://news.mit.edu/2018/study-twitter-false-news-travels-faster-true-stories-0308","abruf":"2026-10-12"},{"typ":"doi","kurz":"Vosoughi, S.; Roy, D.; Aral, S. (2018): The spread of true and false news online. Science 359(6380)","oeffentlich":false,"doi":"10.1126/science.aap9559"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1db782f4139a5e4a"}},{"id":"qx-e-074","clusterId":"E","werkstueckRef":"E.4.3","stufe":1,"question":"Du liest die Behauptung: „Die Plattform zeigt Nutzern absichtlich Wut-Posts, also muss jemand das so geplant haben.“ Was spricht gegen diesen Schluss?","options":["Ein einfaches Optimierungsziel kann ein Verhalten hervorbringen, das niemand eigens geplant hat; dass Wut im Feed auftaucht, setzt keine Absicht eines Menschen voraus.","Wenn ein System Wut verstärkt, haben die Entwickler das zwangsläufig als eigenes Ziel einprogrammiert, weil Maschinen nur tun, was man ihnen vorgibt.","Weil der Effekt so stark auffällt, kann er nur zufällig entstehen; mit dem Ziel der Plattform, Aufmerksamkeit zu maximieren, hat er nichts zu tun.","Wenn Wut-Posts besonders viel Reichweite bekommen, müssen Mitarbeiter sie von Hand ausgewählt und nach oben geschoben haben."],"correctIndex":0,"explanation":"Aus dem Verhalten eines Systems lässt sich nicht auf die Absicht seiner Entwickler schließen. Ein selbstlernender Algorithmus, der nur Aufmerksamkeit maximiert, findet von allein heraus, dass empörende Inhalte besonders viele Reaktionen auslösen. Solche Eigenschaften, die aus dem Zusammenspiel von Ziel und Nutzerverhalten entstehen, ohne dass jemand sie angelegt hat, heißen emergent. Gleichzeitig ist das Ergebnis kein Zufall, denn es folgt zuverlässig aus dem Ziel, Aufmerksamkeit zu maximieren. Die Frage „Wer wollte das?“ führt hier in die Irre; besser fragt man: „Welches Ziel wird optimiert, und was belohnt es?“","coreRule":"⚡ Ein Ergebnis ist nicht automatisch geplant: Prüfe das Optimierungsziel, bevor du nach einem Schuldigen mit Absicht suchst.","beleg":"Werkstück E.4.3 (Kontext & Tiefe: Emergente Eigenschaft; Der Mechanismus)","status":"entwurf","scenario":"Ein Empfehlungsalgorithmus lernt selbstständig aus dem Verhalten der Nutzer. Sein einziges Ziel: Verweildauer und Interaktionen steigern. Er „weiß“ nicht, was Wut oder Wahrheit ist, sondern nur, welche Inhalte zu mehr Klicks, Kommentaren und Shares führen. Empörende Beiträge lösen davon besonders viele aus, und so tauchen sie immer häufiger in den Feeds auf.","kurz":"Aus dem Verhalten eines Systems lässt sich nicht auf die Absicht dahinter schließen: Wer nur Aufmerksamkeit maximieren lässt, bekommt Wut im Feed, ohne dass jemand sie wollte. Zufall ist das aber nicht, es folgt aus dem Ziel.","prueffrage":"Was genau wurde dem Algorithmus als Ziel vorgegeben, und woher weiß er, welche Beiträge er öfter zeigen soll?","rueckmeldung":[{"option":1,"text":"Dass Maschinen dem Vorgegebenen folgen, stimmt. Vorgegeben war hier aber nur das Ziel, Aufmerksamkeit zu maximieren; dass Wut dabei gut funktioniert, hat der Algorithmus selbst herausgefunden. Daraus folgt nicht, dass sie eigens einprogrammiert wurde."},{"option":2,"text":"Dass Wut auch ohne jede Planung in den Feed gelangen kann, stimmt. Zufällig ist der Effekt deshalb nicht: Er folgt zuverlässig aus dem Ziel, Aufmerksamkeit zu maximieren, weil empörende Beiträge besonders viele Reaktionen auslösen."},{"option":3,"text":"Hohe Reichweite für Wut-Posts setzt keine Handarbeit voraus. Der Algorithmus lernt selbstständig aus Klicks, Kommentaren und Shares, und Empörendes setzt sich dadurch von allein durch."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Rathje, S.; Van Bavel, J. J.; van der Linden, S. (2021): Out-group animosity drives engagement on social media. PNAS 118(26)","oeffentlich":true,"doi":"10.1073/pnas.2024292118"},{"typ":"doi","kurz":"Brady, W. J.; McLoughlin, K.; Doan, T. N.; Crockett, M. J. (2021): How social learning amplifies moral outrage expression in online social networks. Science Advances 7(33)","oeffentlich":true,"doi":"10.1126/sciadv.abe5641","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"726f21b27c86dbea"}},{"id":"qx-e-075","clusterId":"E","werkstueckRef":"E.4.4","stufe":1,"question":"Was ist hier das eigentliche Problem – und was prüfst du als Erstes?","options":["Das Material ist echt, aber sein Zusammenhang ist falsch. Du suchst zuerst die Originalquelle und die vollständige Aufnahme der Rede.","Das Material ist echt, deshalb gibt es nichts zu prüfen. Du nimmst den Satz so, wie er im Video wirkt, als ihre Aussage.","Das Material ist verdächtig, solange keine KI-Spuren ausgeschlossen sind. Du prüfst zuerst Blinzeln, Hautstruktur und Bildränder.","Das Material ist harmlos, solange es nicht neu erzeugt wurde. Du wartest ab, bis jemand eine KI-Manipulation nachweist."],"correctIndex":0,"explanation":"Ob eine Aufnahme echt ist und ob sie das zeigt, was behauptet wird, sind zwei getrennte Fragen. Hier ist das Material echt, aber der Kontext falsch: Der Satz stammt aus einer Rede über ein ganz anderes Thema und wurde mit einer neuen Überschrift versehen. Solche einfachen Manipulationen mit echtem Material sind viel leichter herzustellen als KI-Fälschungen und deshalb häufiger. Im Bild findet sich nichts Gefälschtes. Wer nur nach Bildfehlern sucht, übersieht sie. Wirksam ist die Frage nach der Herkunft: Wo stammt die Aufnahme ursprünglich her, wann wurde sie gemacht, und was kam davor und danach? Die Suche nach der Originalquelle und der vollständigen Aufnahme klärt das am schnellsten.","coreRule":"⚡ Echtes Material kann täuschen: Prüfe nicht nur, ob ein Bild echt ist, sondern ob es das zeigt, was behauptet wird.","beleg":"Werkstück E.4.4 (Kernidee, Absatz zu „Cheap Fakes“)","status":"entwurf","scenario":"Ein Video zeigt eine Stadträtin bei einer Rede, in der sie scheinbar sagt: „Das ist mir alles egal.“ Es verbreitet sich rasant. Ein Faktencheck stellt fest: Bild und Ton sind echt und nicht per KI erzeugt. Das Video stammt aus einer Rede von vor drei Jahren, in der sie über ein ganz anderes Thema sprach; der Satz ist aus einem längeren Zusammenhang herausgeschnitten und mit einer neuen Überschrift versehen.","kurz":"Ob eine Aufnahme echt ist und ob sie zeigt, was behauptet wird, sind zwei getrennte Fragen. Hier ist das Material echt, aber der Satz stammt aus einer alten Rede über ein anderes Thema. Wer nur Bildfehler sucht, übersieht das; die Frage nach der Herkunft klärt es.","prueffrage":"Was hat der Faktencheck über Bild und Ton herausgefunden, und was über die Überschrift?","rueckmeldung":[{"option":1,"text":"Dass das Material echt ist, stimmt. Daraus folgt aber nicht, dass es zeigt, was die Überschrift behauptet: Ein echter Satz kann aus dem Zusammenhang gerissen sein und dann etwas ganz anderes bedeuten als in der Rede."},{"option":2,"text":"KI-Fälschungen gibt es, und Bildfehler können Hinweise sein. Hier sind Bild und Ton aber echt, die Suche nach Spuren liefe ins Leere. Einfache Umdeutungen mit echtem Material sind leichter herzustellen und häufiger."},{"option":3,"text":"Ob etwas harmlos ist, hängt nicht davon ab, ob es neu erzeugt wurde. Auch echtes Material kann irreführen, wenn ein Satz herausgeschnitten und neu betitelt wird. Auf einen KI-Nachweis zu warten, hilft hier nicht, weil gar keine KI im Spiel ist."}],"familie":"bild-und-video-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Brennen, J. S.; Simon, F.; Howard, P. N.; Nielsen, R. K. (2020): Types, Sources, and Claims of COVID-19 Misinformation. Reuters Institute Factsheet","oeffentlich":true,"doi":"10.60625/risj-awvq-sr55"},{"typ":"url","kurz":"Dufour, N. u. a. (2024): AMMeBa: A Large-Scale Survey and Dataset of Media-Based Misinformation In-The-Wild. arXiv:2405.11697v2 (Preprint)","oeffentlich":true,"url":"https://arxiv.org/abs/2405.11697"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"d6e68dad246c301c"}},{"id":"qx-e-076","clusterId":"E","werkstueckRef":"E.4.4","stufe":2,"question":"Du siehst ein Video, in dem ein Politiker etwas Schockierendes sagt. Dein Puls rast, und du willst es sofort teilen. Was ist der klügste erste Schritt?","options":["Auf Blinzeln, Hautglätte und Lippensynchronität achten und bei nichts Auffälligem weiterverbreiten, weil der Blick aufs Bild genug Sicherheit gibt.","Das Video als bloße Behauptung behandeln, nichts teilen und nach Originalquelle und unabhängiger Bestätigung suchen, weil die Quelle mehr Sicherheit gibt.","Es sofort mit dem Zusatz „Ist das echt?“ teilen und die Prüfung anderen überlassen, weil so viele andere mithelfen können.","Die Kommentare lesen und der Mehrheit folgen, bevor du etwas tust, weil viele Betrachter Fälschungen verlässlicher erkennen als ein Einzelner."],"correctIndex":1,"explanation":"Dein rasender Puls ist selbst ein Warnsignal: Genau auf solche Gefühle zielen Fälschungen. Ein aufrührerisches Video ist zunächst nur eine Behauptung, kein Beweis. Der Blick aufs Bild trägt wenig: In Experimenten erkannten Menschen Deepfakes kaum besser als der Zufall, hielten Fälschungen eher für echt als umgekehrt und überschätzten ihre Trefferquote. Typische Merkmale wie Blinzeln oder wachsartige Haut verschwinden zudem mit besserer Technik. Auch mit Fragezeichen geteilt, erreicht das Video viele Menschen; das spätere Dementi erreicht nur einen Bruchteil, und selbst ein Fälschungshinweis nimmt der Wirkung nur einen Teil. Kommentare bieten keine verlässliche Prüfung: Menschen erkennen Deepfakes insgesamt kaum besser als der Zufall, und anonyme Kommentare sind keine unabhängige Bestätigung. Mehr Sicherheit gibt die Frage nach der Originalquelle und ob unabhängige, seriöse Stellen das Video bestätigen.","coreRule":"⚡ Je stärker ein Video auf dich wirkt, desto wichtiger ist die Frage nach seiner Quelle.","beleg":"Werkstück E.4.4 (Das Anti-Denkmuster: Aktivierungs-Fragen 1 und 2; Red Flags)","status":"entwurf","scenario":"","kurz":"Ein schockierendes Video ist zunächst nur eine Behauptung, kein Beweis. Das Bauchgefühl und der Blick aufs Bild trügen: Wer ein Video allein nach Aussehen oder Stimmung beurteilt, hält Fälschungen leicht für echt. Die Herkunft lässt sich prüfen.","prueffrage":"Was genau macht dich gerade so sicher, dass der Politiker das wirklich gesagt hat?","rueckmeldung":[{"option":0,"text":"Blinzeln und Hautglätte waren früher tatsächlich Hinweise. Menschen erkennen Deepfakes aber kaum besser als der Zufall, und solche Merkmale verschwinden mit besserer Technik. Ein unauffälliges Bild belegt also wenig."},{"option":2,"text":"Das Fragezeichen wirkt vorsichtig, ändert aber wenig: Das Video erreicht trotzdem viele Menschen, ein späteres Dementi nur einen Bruchteil. Die Prüfung wird so nur an andere weitergereicht, statt dass du sie leistest."},{"option":3,"text":"Mehrere Blicke wirken verlässlicher als einer. Menschen erkennen Deepfakes insgesamt aber kaum besser als der Zufall, und anonyme Kommentare sind keine unabhängige Bestätigung. Eine Mehrheitsmeinung ersetzt keine Prüfung der Quelle."}],"familie":"bild-und-video-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Diel, A. u. a. (2024): Human Performance in Detecting Deepfakes: A Systematic Review and Meta-Analysis of 56 Papers. Computers in Human Behavior Reports 16","oeffentlich":true,"doi":"10.1016/j.chbr.2024.100538"},{"typ":"doi","kurz":"Köbis, N. C.; Doležalová, B.; Soraperra, I. (2021): Fooled Twice: People Cannot Detect Deepfakes but Think They Can. iScience 24(11)","oeffentlich":true,"doi":"10.1016/j.isci.2021.103364"},{"typ":"doi","kurz":"Clark, S.; Lewandowsky, S. (2026): The Continued Influence of AI-Generated Deepfake Videos Despite Transparency Warnings. Communications Psychology 4, 13","oeffentlich":true,"doi":"10.1038/s44271-025-00381-9"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"2b8f82bbd5d110d1"}},{"id":"qx-e-077","clusterId":"E","werkstueckRef":"E.4.4","stufe":3,"question":"Ein Kollege folgert: „Dann prüfe ich eben jedes verdächtige Video genau und vertraue danach meinem Eindruck.“ Welche Schlussfolgerung ist angemessen?","options":["Wer sich gut konzentriert und genau hinschaut, erkennt Fälschungen verlässlich; ein Eindruck nach gründlichem Hinsehen reicht als Prüfung.","Bei unbekannten Personen kann der Augenschein allein eine Fälschung nicht sicher verraten; sicherer ist es, die Herkunft des Videos zu prüfen.","Wer vorher über die Gefahren von Deepfakes informiert ist, erkennt sie meist zuverlässig; wichtig ist deshalb vor allem das Wissen darüber.","Wer sich seiner Einschätzung sehr sicher ist, liegt in der Regel richtig, denn Sicherheit entsteht aus erkannten Auffälligkeiten im Bild."],"correctIndex":1,"explanation":"Eine Metaanalyse von 56 Arbeiten (Diel u. a. 2024) ergab eine Trefferquote von 55,5 %, also kaum über dem Zufall. Im Versuch mit 210 Teilnehmenden (Köbis u. a. 2021) wurden Fälschungen eher für echt gehalten als umgekehrt, und die Teilnehmenden überschätzten ihre Trefferquote. Wenn weder ein Warntext noch eine Prämie für richtige Antworten die Erkennung verbessern, ist das Gefühl „sieht echt aus“ keine brauchbare Prüfung, und das Selbstvertrauen taugt nicht als Gütesiegel. Wer das Urteil auf die Herkunft stützt (Originalquelle, unabhängige Bestätigung), umgeht die Schwäche des Augenscheins. Ein Training mit Rückmeldung verbesserte die Erkennung in den meisten Experimenten, bloße Hinweise auf typische Fehler brachten gemischte Ergebnisse.","coreRule":"⚡ Dein Gefühl für „echt“ trügt – verlass dich auf Quellenprüfung statt auf Augenschein.","beleg":"Werkstück E.4.4 (Red Flags); Fn. gl-e-erkennung (Köbis u. a. 2021; Diel u. a. 2024, S. 7); Fn. gl-e-deepfake (Diel u. a. 2024, 55,5 %)","status":"entwurf","scenario":"Ein Forschungsteam zeigte 210 Online-Teilnehmenden 16 kurze Videos unbekannter Personen; die Hälfte war gefälscht. Bei den meisten Clips lag die Erkennung nicht verlässlich über dem Zufall. Wer vorab einen Text über die Gefahren von Deepfakes las oder für richtige Antworten bezahlt wurde, schnitt nicht besser ab als die übrigen. Die Selbsteinschätzung lag deutlich über der tatsächlichen Trefferquote.","kurz":"Wenn weder ein Warntext noch eine Prämie die Erkennung verbessern, taugt der Eindruck „sieht echt aus“ nicht als Prüfung. Wer seinem Urteil traut, nur weil er genau hingeschaut hat, überschätzt sich leicht; sicherer ist es, die Herkunft des Videos zu prüfen.","prueffrage":"Wie gut lagen die Teilnehmenden tatsächlich, und wie gut glaubten sie selbst zu liegen?","rueckmeldung":[{"option":0,"text":"Genaues Hinsehen fühlt sich wie eine gründliche Prüfung an. Im Versuch machten aber weder eine Prämie noch ein Warntext die Teilnehmenden besser, und ihr Eindruck blieb unzuverlässig, auch wenn sie sich sicher fühlten."},{"option":2,"text":"Wer über Deepfakes Bescheid weiß, fühlt sich gewappnet. Doch der Text über die Gefahren machte die Teilnehmenden nicht besser: Wissen um das Risiko ist noch kein Erkennen. Geholfen hat in den meisten Experimenten erst Training mit Rückmeldung."},{"option":3,"text":"Sicherheit fühlt sich an wie ein Zeichen für erkannte Hinweise im Bild. Die Teilnehmenden überschätzten aber ihre Trefferquote deutlich, ihr Selbstvertrauen sagte also wenig darüber, ob sie richtig lagen."}],"familie":"bild-und-video-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Diel, A. u. a. (2024): Human Performance in Detecting Deepfakes: A Systematic Review and Meta-Analysis of 56 Papers. Computers in Human Behavior Reports 16","oeffentlich":true,"doi":"10.1016/j.chbr.2024.100538"},{"typ":"doi","kurz":"Köbis, N. C.; Doležalová, B.; Soraperra, I. (2021): Fooled Twice: People Cannot Detect Deepfakes but Think They Can. iScience 24(11)","oeffentlich":true,"doi":"10.1016/j.isci.2021.103364"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"2d7e4e0e95b2c05d"}},{"id":"qx-e-078","clusterId":"E","werkstueckRef":"E.4.4","stufe":4,"question":"Welche Prüffrage trifft die Schwachstelle der Behauptung am besten?","options":["Wie groß ist der Anteil von KI-Bildern unter allen gezählten Bildfälschungen?","Wie realistisch sehen die KI-Bilder aus, die dem Verfasser aufgefallen sind, und sind sie von echten Fotos zu unterscheiden?","Wie viele Menschen haben den Artikel gelesen, und wie oft wurden die erwähnten KI-Bilder in sozialen Netzwerken geteilt?","Welche Programme erzeugen die KI-Bilder, die dem Verfasser aufgefallen sind, und wie leicht lassen sie sich bedienen?"],"correctIndex":0,"explanation":"Die Behauptung betrifft einen Anteil, und dafür braucht es eine systematische Zählung aller Bildfälschungen; auffällige Einzelfälle reichen nicht, denn spektakuläre KI-Bilder bleiben besser im Gedächtnis als unscheinbare Fälschungen. Die vorhandenen Zählungen sprechen gegen die Behauptung: In 225 englischsprachigen Covid-19-Falschmeldungen (Januar bis März 2020) fand sich kein einziger Deepfake, alle manipulierten Bilder und Videos waren mit einfachen Mitteln bearbeitet (Brennen u. a. 2020). Auch in englischsprachigen Faktenchecks bis November 2023 überwogen einfache Mittel, vor allem echte Bilder in falschem Zusammenhang, obwohl KI-Bilder ab Frühjahr 2023 rasch zunahmen (Dufour u. a. 2024, Preprint). Wie es seither steht, ist offen. Realismus, Reichweite oder die verwendeten Programme klären nicht, wie groß der Anteil KI-erzeugter Bilder unter allen Bildfälschungen ist.","coreRule":"⚡ Auffälligkeit ist keine Häufigkeit: Wer „die meisten“ behauptet, braucht eine Zählung, keinen Eindruck.","beleg":"Werkstück E.4.4 (Werkbank-Frage); Fn. gl-e-haeufiger (Brennen u. a. 2020, Factsheet S. 4; Dufour u. a. 2024, Preprint); Anm. anm-gl-e-haeufiger","status":"entwurf","scenario":"Du liest einen Artikel über Desinformation. Er behauptet, die meisten Bildfälschungen im Netz seien heute KI-erzeugt. Als einzigen Beleg führt der Verfasser an, dass ihm in letzter Zeit auffällig viele KI-Bilder in sozialen Netzwerken begegnet sind.","quote":"","quoteLabel":"","kurz":"Die Behauptung betrifft einen Anteil, und dafür braucht es eine Zählung aller Bildfälschungen. Auffällige KI-Bilder bleiben besser im Gedächtnis als unscheinbare Fälschungen, daher täuscht der Eindruck leicht über ihren wahren Anteil.","prueffrage":"Worauf stützt sich der Verfasser, und in welchem Ausschnitt des Netzes hat er seine Beobachtungen gemacht?","rueckmeldung":[{"option":1,"text":"Wie täuschend echt die aufgefallenen Bilder wirken, ist eine berechtigte Frage, wenn es um das Erkennen geht. Über den Anteil unter allen Fälschungen sagt das aber nichts: Auch sehr gute KI-Bilder können im Verhältnis selten sein."},{"option":2,"text":"Viel geteilte Bilder sind leicht sichtbar, aber nur eine Auswahl. Wie oft sie geteilt und wie oft der Artikel gelesen wurde, zeigt nicht, wie groß der Anteil der KI-Bilder an allen Fälschungen ist."},{"option":3,"text":"Welche Programme es gibt und wie leicht sie sich bedienen lassen, erklärt höchstens, warum KI-Bilder entstehen können. Dass sie die Mehrheit der Fälschungen ausmachen, folgt daraus nicht; dafür bräuchte es eine Zählung."}],"familie":"basisrate-beachten","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Brennen, J. S.; Simon, F.; Howard, P. N.; Nielsen, R. K. (2020): Types, Sources, and Claims of COVID-19 Misinformation. Reuters Institute Factsheet","oeffentlich":true,"doi":"10.60625/risj-awvq-sr55"},{"typ":"url","kurz":"Dufour, N. u. a. (2024): AMMeBa: A Large-Scale Survey and Dataset of Media-Based Misinformation In-The-Wild. arXiv:2405.11697v2 (Preprint)","oeffentlich":true,"url":"https://arxiv.org/abs/2405.11697"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"2f6f82f98b38e6ad"}}]`);export{t as n,n as t};